window.DRONE_PAGES_I18N = window.DRONE_PAGES_I18N || {};
window.DRONE_PAGES_I18N["fr"] = {"E001":{"headline":"Un petit drone d’origine inconnue tombe sur la base militaire de Przasnysz, en Pologne","description":"Le 28 janvier 2026, un petit drone ressemblant à un jouet est tombé sur la base militaire de Przasnysz, en Pologne. Son origine est inconnue ; l’implication étrangère n’a pas été établie.","summary":["Le 28 janvier 2026, le personnel de sécurité de la base militaire de Przasnysz, en Pologne, a vu un petit drone ressemblant à un jouet survoler le site avant sa chute. L’incident a été rendu public le 2 février 2026, lorsqu’il a été signalé qu’un petit drone était tombé sur une base de l’armée polonaise.","L’origine et l’opérateur du drone sont inconnus, et l’implication étrangère n’a pas été établie. Son itinéraire avant d’atteindre la base est lui aussi inconnu. Il a été décrit comme un engin rudimentaire, et aucun support d’enregistrement n’y a été identifié. Une enquête a été signalée.","Aucun dégât ni aucune victime n’ont été signalés. Le drone a été sécurisé et remis à la Police militaire."]},"E002":{"headline":"Un drone signalé comme russe pénètre dans l’espace aérien roumain près de Sfântu Gheorghe","description":"Le 25 février 2026, un drone signalé comme russe est brièvement entré dans l’espace aérien roumain au-dessus des eaux territoriales près de Sfântu Gheorghe et de Sulina. Des F-16 ont décollé en urgence.","summary":["Le 25 février 2026, un radar a détecté un drone entrant dans l’espace aérien roumain au-dessus des eaux territoriales près de Sfântu Gheorghe, dans le département de Tulcea, pendant des attaques contre des ports ukrainiens sur le Danube. Le drone en est ressorti au nord de Sulina. L’incursion a été confirmée comme brève ; un premier article la situait à environ 20 minutes, mais ce chiffre n’est pas vérifié et la durée exacte n’a pas été établie.","Le drone a été signalé comme russe, et le ministère roumain de la Défense (MApN) a relié l’incident aux frappes russes contre l’Ukraine. Son modèle est inconnu.","Deux avions de chasse F-16 ont décollé en urgence à 17:50, heure locale, et une alerte RO-Alert a été émise à 18:07. L’alerte a pris fin vers 18:45. Aucun dommage ni débris n’a été signalé."]},"E003":{"headline":"L’armée suédoise relie à un navire russe un drone repéré près du porte-avions français au large de Malmö","description":"En février 2026, un drone a volé près du porte-avions Charles de Gaulle dans l’Øresund, au large de Malmö, en Suède. Les forces suédoises ont mis en cause un navire russe ; la Russie a rejeté cette accusation.","summary":["Fin février 2026, le navire de la marine suédoise HMS Rapp a détecté un drone dans l’Øresund, au large de Malmö, en Suède, lors d’une visite du porte-avions français Charles de Gaulle. Le drone a volé près de la zone protégeant le porte-avions. Les récits divergent sur la date : un premier article indiquait le 26 février, tandis qu’un compte rendu citant l’armée suédoise situe la rencontre au 25 février.","L’armée suédoise a attribué le lancement au navire de renseignement russe Zhigulevsk, qui transitait par l’Øresund, et des données techniques auraient relié le lancement à ce navire. La Russie a rejeté l’allégation. Le modèle du drone n’a pas été identifié de manière concluante.","Le navire suédois a brouillé ou perturbé le drone, mais son sort final est inconnu et aucun abattage n’a été confirmé. Aucune victime n’a été signalée, et les opérations du porte-avions n’auraient pas été affectées. La France a commenté l’incident le 27 février 2026."]},"E004":{"headline":"Un drone militaire découvert dans une mine près de Konin, en Pologne, probablement issu d’un vol de 2025","description":"Le 12 mars 2026, un drone militaire a été trouvé dans une mine près de Konin, en Pologne. Il a été signalé comme probablement russe et probablement lié à une incursion de septembre 2025.","summary":["Le 12 mars 2026, un drone militaire a été trouvé dans une mine de lignite près de Konin, dans la zone de Mniszków–Gałczyce, en Grande-Pologne. Un employé de la mine serait tombé dessus, et il se trouvait peut-être là depuis des mois. La date est celle de la découverte, et non d’un vol : aucun vol en 2026 n’a été établi.","Le drone a été signalé comme probablement russe. Le 13 mars, le ministre polonais de la Défense l’a relié à une incursion de drone en septembre 2025, en décrivant ce lien comme probable plutôt que prouvé. Le modèle du drone n’a pas été précisé.","Aucun dommage n’a été signalé. La police et la Police militaire ont enquêté sur la découverte."]},"E005":{"headline":"Le drone écrasé sur le lac Lavysas identifié comme ukrainien par la Lituanie","description":"Le 23 mars 2026, un drone militaire s’est écrasé sur le lac gelé Lavysas, dans le district de Varėna, en Lituanie. Le gouvernement lituanien l’a identifié comme ukrainien.","summary":["Le 23 mars 2026, un drone militaire est tombé sur la glace du lac Lavysas, dans le district de Varėna, en Lituanie, à environ 20 km de la frontière avec la Biélorussie. Une explosion a été signalée, et les débris ont été retrouvés sur le lac gelé.","Le 24 mars, le gouvernement lituanien a identifié le drone comme ukrainien. Il aurait été destiné à une attaque contre des installations d’exportation de pétrole à Primorsk avant de s’égarer. Une explication faisant intervenir la guerre électronique reste une évaluation plutôt qu’une conclusion établie. Le drone transportait une charge militaire, mais la charge exacte n’a pas été précisée.","Aucune victime n’a été signalée. Le site a été sécurisé et les débris ont été examinés."]},"E006":{"headline":"L’impact du drone sur Auvere reste confirmé ; l’enquête laisse l’origine non résolue","description":"Les procureurs estoniens ont clos l’enquête sur le drone d’Auvere le 23 octobre sans établir ni son origine ni les responsabilités. L’impact du 25 mars sur la cheminée reste confirmé.","summary":["Un drone a heurté la cheminée de la centrale électrique d’Auvere le 25 mars. Aucun blessé ni aucune interruption du réseau électrique n’ont été signalés. Les premières déclarations des autorités estoniennes décrivaient le drone comme ukrainien et signalaient une entrée depuis la Russie.","La clôture de l’enquête par le procureur le 23 octobre n’a établi ni l’origine du drone ni les circonstances précises. L’hypothèse d’un détournement d’un drone ukrainien est restée non prouvée. Les enquêteurs n’ont trouvé aucun indice d’une activité délibérée contre l’Estonie ; cela n’établit pas qu’une autre cible était visée. L’impact confirmé reste un seul événement."]},"E007":{"headline":"Le président letton affirme que le drone écrasé près de Krāslava était ukrainien","description":"Le 25 mars 2026, un drone militaire s’est écrasé dans la région de Krāslava, en Lettonie. Le président letton a dit qu’il était ukrainien ; il était entré par l’espace aérien russe.","summary":["Dans la matinée du 25 mars 2026, un drone militaire s’est écrasé dans une zone rurale de la région de Krāslava, en Lettonie. Un autre compte rendu, celui du Centre d’études orientales (OSW), situe l’écrasement à Dobročina.","Le président letton a déclaré que le drone était ukrainien. Il est entré en Lettonie par l’espace aérien russe pendant des frappes ukrainiennes contre des cibles en Russie. La raison pour laquelle il est tombé en Lettonie, qu’il s’agisse d’une défaillance ou d’un détournement, n’a pas été démontrée.","Aucune victime n’a été signalée. Les autorités lettones ont récupéré les débris et enquêté. Un drone égaré a également été signalé en Estonie le même jour, et les ministres de la Défense baltes ont publié une déclaration commune sur les incidents de drones."]},"E008":{"headline":"Un drone d’opérateur non identifié traverse la Lettonie, de la Biélorussie vers la Russie","description":"Le 25 mars 2026, la Lettonie a signalé un drone qui a brièvement traversé l’est du pays, de la Biélorussie vers la Russie. Sa nationalité et son opérateur n’ont pas été identifiés.","summary":["Le 25 mars 2026, les autorités lettones ont signalé qu’un drone supplémentaire avait brièvement traversé le territoire letton, entrant depuis la Biélorussie et en ressortant vers la Russie. La trajectoire exacte suivie en Lettonie n’a pas été précisée.","La nationalité et l’opérateur du drone n’ont pas été indiqués, et son modèle est inconnu. Les informations établissent qu’il est entré en Lettonie depuis l’étranger, mais aucun débris ni aucune identification publique de l’opérateur n’ont été signalés.","Le drone a été surveillé et aucun engagement n’a été signalé. Aucun dommage n’a été signalé. Il a été signalé comme un vol distinct de celui du drone militaire écrasé le même jour dans la région de Krāslava, en Lettonie."]},"E009":{"headline":"Des drones ukrainiens s’écrasent dans le sud-est de la Finlande le 29 mars","description":"Deux drones se sont écrasés au nord de Kouvola et à Luumäki le 29 mars 2026. Les enquêteurs finlandais ont établi une origine ukrainienne et une entrée non intentionnelle.","summary":["Deux drones se sont écrasés dans le sud-est de la Finlande le 29 mars 2026, au nord de Kouvola et à Luumäki. Les conclusions de l’enquête de septembre établissent une origine ukrainienne et attribuent le détournement au brouillage du GNSS et à la météo, et non à une attaque voulue contre la Finlande.","L’enquête s’est conclue sans autre responsabilité pénale ; les entrées n’en sont pas moins restées illicites. L’événement groupé d’origine et l’URL publiée sont conservés."]},"E010":{"headline":"Détections de drones et découvertes de débris dans le comté de Tartu, en Estonie, et en Finlande","description":"Du 31 mars au 1er avril 2026, des drones et des débris ont été signalés dans le comté de Tartu, en Estonie, ainsi qu’une découverte distincte en Finlande. L’Estonie a évalué ses cas comme ukrainiens.","summary":["Ce groupe conservé réunit des signalements estoniens d’activité et de débris et la récupération d’un drone en Finlande le 31 mars 2026. L’enquête finale finlandaise situe cette récupération à Pyhäjärvi, à Parikkala, et établit une origine ukrainienne et une entrée non autorisée.","La récupération en Finlande est distincte des deux écrasements du 29 mars et de la découverte ultérieure d’Iitti. L’heure de son entrée reste inconnue. La composante estonienne reste un groupe non résolu ; ses observations et objets ne sont pas convertis en fiches supplémentaires."]},"E011":{"headline":"Un drone signalé comme russe s’écrase à Galați, en Roumanie, et endommage des biens","description":"Le 25 avril 2026, un drone militaire signalé comme russe s’est écrasé à Bariera Traian, Galați, en Roumanie, endommageant un poteau et un bâtiment. Ses explosifs ont été détruits.","summary":["Le 25 avril 2026, un drone militaire s’est écrasé dans le secteur de Bariera Traian, à Galați, en Roumanie. Il se serait approché à basse altitude au-dessus du lac Brateș, bien que sa trajectoire précise n’ait pas été reconstituée de manière indépendante. Le drone a endommagé un poteau électrique et une structure d’habitation ou d’atelier.","Les articles publiés à l’époque sur la neutralisation des explosifs ont signalé le drone comme russe. Son modèle n’a pas été précisé. Des chasseurs Typhoon de la RAF avaient décollé en urgence pour des menaces à proximité, mais ce drone n’a pas été abattu.","La présence de matière explosive dans le drone a été confirmée, et les explosifs récupérés ont été détonés lors d’une neutralisation contrôlée le jour même. L’écrasement a causé des dégâts matériels, mais aucune victime n’a été signalée. Il s’agit d’un incident distinct de l’impact d’un drone sur un immeuble d’habitation à Galați le 29 mai 2026."]},"E012":{"headline":"Des fragments de drone trouvés près d’une ferme à Văcăreni, en Roumanie ; opérateur inconnu","description":"Le 25 avril 2026, des fragments de drone ont été trouvés près d’une ferme à Văcăreni, dans le département de Tulcea, en Roumanie. Un lien avec une armée étrangère a été signalé, mais l’opérateur est inconnu.","summary":["Le 25 avril 2026, des fragments de drone ont été trouvés près d’une ferme proche de Văcăreni, dans le département de Tulcea, en Roumanie. La date est celle de la découverte, et non d’un vol : le moment où le drone a volé ou est tombé, et l’itinéraire suivi, sont inconnus, tout comme le nombre de drones dont proviennent les fragments.","Les articles associent les fragments à un drone militaire étranger, mais l’opérateur exact n’a pas été établi.","Aucune victime n’a été signalée. La zone a fait l’objet d’une enquête, et des spécialistes ont collecté et examiné les fragments. Le lendemain, d’autres fragments comportant une charge explosive ont été signalés entre Luncavița et Văcăreni. Les articles roumains ont distingué les deux découvertes, mais il n’a pas été démontré qu’elles provenaient du même drone ou de drones différents."]},"E013":{"headline":"Des fragments de drone avec charge explosive détruits près de Luncavița, en Roumanie","description":"Des fragments de drone trouvés près de Luncavița le 26 avril 2026 ont ensuite été identifiés par le ministère roumain de la Défense comme relevant d’un incident de Geran-2 attribué à la Russie.","summary":["Le 26 avril 2026, d’autres fragments de drone ont été signalés entre Luncavița et Văcăreni, dans le département de Tulcea, en Roumanie, un jour après la découverte de fragments près d’une ferme à Văcăreni. La présence d’une charge explosive parmi les matériaux a été confirmée, et une alerte de sécurité RO-Alert a été émise.","Dans une déclaration du 31 mai, le MApN a rétrospectivement inscrit Luncavița, le 26 avril, parmi des incidents antérieurs de Geran-2 attribués à la Russie. Cela met à jour la provenance initialement non résolue, mais n’établit ni le moment où le drone a volé ou est tombé, ni son itinéraire, ni sa cible visée. Les fragments ne sont pas confirmés comme un second drone complet, et le lien entre leur cellule et la découverte de la veille reste non résolu.","Des artificiers du SRI et des spécialistes du ministère roumain de la Défense (MApN) ont évalué les matériaux, qui ont ensuite été détruits par une détonation contrôlée sur place, sous l’autorité du procureur. Aucune victime n’a été signalée."]},"E014":{"headline":"Un drone d’origine inconnue découvert près de Șerbăuți, dans le département de Suceava, en Roumanie","description":"Le 3 mai 2026, un drone a été trouvé près de Șerbăuți, dans le département de Suceava, en Roumanie, à environ 20 km de l’Ukraine. Son opérateur et sa nationalité n’ont pas été établis.","summary":["Le 3 mai 2026, un drone a été trouvé dans une zone rurale près de Șerbăuți, dans le département de Suceava, en Roumanie, à environ 20 km de l’Ukraine, près de la frontière nord du pays. La date est celle à laquelle le drone a été trouvé et signalé. Le moment où il est réellement tombé, et l’itinéraire qu’il a suivi pour y parvenir, sont inconnus.","Les informations disponibles n’établissent ni la nationalité du drone ni son opérateur, et son modèle n’a pas été précisé. Son identité et sa provenance restent non résolues.","Aucun dommage n’a été signalé. Les autorités roumaines ont enquêté sur la découverte, et le drone a été récupéré."]},"E015":{"headline":"Deux drones pénètrent dans l’espace aérien finlandais près de Virolahti","description":"Deux UAV ont volé dans l’espace aérien finlandais près de Virolahti le 3 mai 2026 avant de passer en Russie. Les enquêteurs ont établi leurs entrées non autorisées.","summary":["La Garde frontière finlandaise a établi que deux UAV avaient volé dans l’espace aérien finlandais près de Virolahti le 3 mai 2026 avant de passer en Russie. Ces entrées non autorisées réunissaient les éléments constitutifs d’une violation du territoire ; l’enquête n’a trouvé aucune intention de violer l’espace aérien finlandais.","L’événement reste une fiche groupée unique. Son origine et son modèle ne sont pas établis ici ; l’absence d’intention n’annule pas les entrées confirmées."]},"E016":{"headline":"Trois drones entrent en Lettonie ; deux s’écrasent, dont un endommage des réservoirs de pétrole à Rēzekne","description":"Le 7 mai 2026, trois drones sont entrés en Lettonie depuis l’espace aérien russe ; deux se sont écrasés, dont un a endommagé des réservoirs de pétrole vides à Rēzekne. Des articles ultérieurs les ont reliés à l’Ukraine.","summary":["Le 7 mai 2026, trois drones sont entrés en Lettonie depuis l’espace aérien russe au-dessus de la zone de Balvi, Ludza et Rēzekne. Deux se sont écrasés et un a quitté la Lettonie. L’un des impacts a touché un site de stockage de pétrole à Rēzekne, où quatre réservoirs de pétrole vides ont été endommagés et un incendie s’est déclaré. Des effets explosifs ont été signalés, mais les charges exactes sont inconnues.","L’origine technique des drones est d’abord restée non résolue ; des articles ultérieurs ont associé les incidents à des drones de frappe ukrainiens. Le ministère letton de la Défense a évoqué la guerre électronique russe comme cause possible. Une enquête militaire et policière a suivi, avec une procédure pénale au titre du chapitre 10 de la Loi pénale lettone.","Aucune victime n’a été signalée. Des avions de l’OTAN ont été déployés et des alertes ont été envoyées sur les téléphones mobiles. Des débris ont été récupérés sur l’un des sites d’écrasement tandis que l’autre était encore recherché. Après les impacts sur les réservoirs de pétrole, les États baltes ont réclamé un renforcement de la défense de l’OTAN."]},"E017":{"headline":"Un drone maritime militaire découvert dans une grotte de Leucade, en Grèce ; l’Ukraine en nie la propriété","description":"Le 7 mai 2026, un pêcheur a trouvé un drone maritime chargé d’explosifs dans une grotte de Leucade, en Grèce. Des responsables grecs l’ont dit de fabrication ukrainienne ; l’Ukraine a nié en être propriétaire.","summary":["Le 7 mai 2026, un pêcheur a trouvé un navire de surface sans équipage militaire, ou drone maritime, dans une grotte côtière de l’île grecque de Leucade. Il aurait déplacé ou remorqué l’engin avant que les autorités ne le sécurisent. Des explosifs ont été signalés sur le drone.","Des responsables grecs ont décrit le drone maritime comme de fabrication ukrainienne ou de type ukrainien. L’Ukraine a nié en être propriétaire, et la propriété reste contestée. Son point de lancement et son itinéraire sont inconnus. Une enquête grecque ultérieure, signalée le 15 mai, a envisagé qu’il ait pu subir une défaillance technique ou s’écarter de sa route.","Aucune victime n’a été signalée. Les garde-côtes, la police et la marine ont enquêté, l’engin a été transféré vers une installation navale, et les explosifs ont ensuite été détruits lors d’une neutralisation contrôlée."]},"E018":{"headline":"Une alerte à des drones présumés suspend l’activité de l’aéroport d’Helsinki, en Finlande","description":"Le 15 mai 2026, des drones présumés près d’Helsinki, en Finlande, ont entraîné une consigne de rester à l’intérieur et l’arrêt de l’activité de l’aéroport. Leur origine étrangère n’a pas été prouvée.","summary":["Le 15 mai 2026, une activité présumée de drones dans l’agglomération d’Helsinki, en Finlande, a déclenché de vastes mesures de protection. Les habitants ont été invités à rester à l’intérieur, l’activité de l’aéroport a été suspendue et des avions de chasse ont décollé en urgence. Le nombre de drones impliqués, et leur type, n’ont pas été établis.","L’origine étrangère n’a pas été prouvée, et la trajectoire d’éventuels drones est inconnue. Les autorités finlandaises ont évalué la menace, et leur déclaration de l’époque ne confirmait pas de menace militaire directe. L’épisode était une alerte et une perturbation, et non une attaque confirmée.","Aucun dommage physique n’a été signalé. L’exploitant aéroportuaire Finavia confirme que le trafic aérien a été suspendu de 04:00 à 07:00, heure locale, puis a repris, avec des retards et des annulations ce jour-là. Il ne donne pas de nombre total d’annulations et n’identifie aucun drone."]},"E019":{"headline":"Des débris d’un drone ukrainien présumé découverts près d’Utena, en Lituanie","description":"Le 17 mai 2026, des débris d’un drone militaire ukrainien présumé ont été trouvés près de Samanė et d’Utena, en Lituanie, puis des explosifs ont été découverts à proximité.","summary":["Le 17 mai 2026, des débris d’un drone militaire présumé ont été trouvés dans la zone de Samanė et d’Utena, en Lituanie, puis de la matière explosive a été découverte à proximité, avec des informations complémentaires le 18 mai. La date est celle de la découverte : la trajectoire du drone est inconnue, et il n’a pas été établi qu’il se soit écrasé ou ait explosé ce jour-là.","Le drone était soupçonné d’être ukrainien, mais cela n’a pas été présenté comme une identification criminalistique définitive, et son identification technique faisait, selon les informations, l’objet d’une enquête. Les explosifs sont liés aux mêmes débris et ne sont pas considérés comme l’indice d’un second drone.","Aucun blessé n’a été signalé. Les autorités ont bouclé le site, récupéré les matériaux et enquêté."]},"E020":{"headline":"Un drone d’origine inconnue pénètre dans l’espace aérien letton près de la frontière russe","description":"Le 17 mai 2026, un drone a été signalé entrant puis quittant l’espace aérien letton près de la frontière russe. Son opérateur et son modèle sont inconnus ; son origine n’est pas résolue.","summary":["Le 17 mai 2026, un drone aurait pénétré dans l’espace aérien letton près de la frontière avec la Russie, puis l’aurait quitté. L’armée lettone aurait suivi cette incursion temporaire. Le lieu précis de l’incursion n’a pas été établi.","L’opérateur et le modèle du drone sont inconnus, et il n’a pas été identifié de façon définitive. Tout lien avec l’Ukraine repose uniquement sur un soupçon tiré du contexte général, et non sur une identification de ce drone.","Le drone a été surveillé et aucun abattage n’a été signalé. Aucun dommage ni autre impact n’a été signalé."]},"E021":{"headline":"Le drone abattu au-dessus de la région de Põltsamaa, en Estonie, identifié comme ukrainien","description":"Le 19 mai 2026, un F-16 roumain sous commandement de l’OTAN a abattu un drone au-dessus de la région de Põltsamaa, en Estonie. L’Estonie a dit qu’il était ukrainien ; Kiev a présenté ses excuses.","summary":["Le 19 mai 2026, un drone est entré dans l’espace aérien estonien et a été abattu au-dessus de la zone de Kablaküla et de Põltsamaa, en Estonie. Un chasseur de l’OTAN a suivi le drone qui approchait, et un F-16 roumain opérant sous commandement de l’OTAN l’a abattu. Les débris ont fait l’objet d’une enquête.","L’Estonie a déclaré que le drone était ukrainien, et Kiev a présenté ses excuses. Le drone aurait été destiné à une cible en Russie. L’Ukraine a affirmé que la guerre électronique russe l’avait dévié ; cette explication est le récit propre de l’Ukraine.","Aucun dommage civil n’a été signalé. Une alerte aérienne dans l’est de la Lettonie le même jour a pu faire partie de la même vague, mais il n’a pas été établi qu’un second drone était impliqué."]},"E022":{"headline":"Une alerte aérienne dans l’est de la Lettonie possiblement liée au drone abattu au-dessus de l’Estonie","description":"Le 19 mai 2026, une alerte aérienne dans l’est de la Lettonie a perturbé trains et examens. Elle pourrait être liée à un drone abattu au-dessus de l’Estonie ; aucun drone distinct n’a été établi.","summary":["Le 19 mai 2026, une alerte aérienne a été déclenchée dans l’est de la Lettonie. Des avertissements à la population et des mesures de mise à l’abri ont suivi, ainsi qu’une réponse de l’OTAN. Les services ferroviaires et des examens ont été perturbés, et certains commerces auraient fermé. Les lieux exacts touchés n’ont pas été établis.","L’alerte est survenue le jour même où un drone signalé comme ukrainien a été abattu au-dessus de l’Estonie, et elle a pu faire partie de la même vague. L’origine de ce qui a déclenché l’alerte, et son lien avec le drone estonien, restent non résolus. Les informations de sources ouvertes n’ont pas établi si un objet distinct était entré en Lettonie, et aucun drone distinct n’a été identifié."]},"E023":{"headline":"Une alerte à un drone présumé perturbe l’aéroport et le rail de Vilnius, en Lituanie","description":"Le 20 mai 2026, un drone présumé a déclenché une alerte de danger aérien à Vilnius, en Lituanie, perturbant l’aéroport et le rail. Son origine n’a pas été établie.","summary":["Le 20 mai 2026, une alerte de danger aérien liée à un drone présumé (UAV) a été émise pour Vilnius, en Lituanie, et son espace aérien environnant. L’alerte, qui comprenait un appel à se mettre à l’abri, a entraîné des fermetures de protection dans la capitale. L’aéroport, les services ferroviaires, le Parlement et les écoles auraient été perturbés, et les autorités ont imposé des restrictions de circulation temporaires.","Le nombre de drones présumés impliqués, et leur modèle, n’ont pas été précisés, et la trajectoire est inconnue. L’identité de l’opérateur du drone et le pays d’où il venait n’ont pas été établis ; aucune attribution définitive n’a été faite.","Aucun impact confirmé n’a été signalé."]},"E024":{"headline":"Une incursion de drone signalée déclenche une alerte de mise à l’abri à la frontière orientale de la Lettonie","description":"Le 21 mai 2026, au moins un drone a été signalé au-dessus des régions frontalières orientales de la Lettonie. Des chasseurs de l’OTAN ont décollé ; l’origine du drone n’a pas été établie.","summary":["Le 21 mai 2026, une menace aérienne a été signalée dans des municipalités lettones le long de la frontière orientale, dans des régions limitrophes de la Biélorussie et de la Russie. Au moins un drone (UAV) a été signalé dans l’espace aérien letton, et les habitants ont reçu l’instruction de se mettre à l’abri.","L’opérateur et le modèle du drone sont inconnus. Un récit le décrit entrant depuis la Biélorussie, mais son origine n’a pas été établie et son identité finale reste non résolue.","Des chasseurs de l’OTAN ont été lancés en réaction. Aucun impact n’a été confirmé."]},"E025":{"headline":"Des objets aériens présumés suscitent une réaction de l’OTAN dans le comté d’Utena, en Lituanie","description":"Le 21 mai 2026, deux objets aériens présumés dans le comté d’Utena, en Lituanie, ont entraîné des alertes et la réaction d’un aéronef de l’OTAN. Leur identité et leur origine ne sont pas confirmées.","summary":["Le 21 mai 2026, deux objets aériens présumés ont été détectés dans l’espace aérien du comté d’Utena, en Lituanie. Des alertes ont été émises et des aéronefs de l’OTAN seraient intervenus.","Il n’a pas été établi de façon définitive que les objets étaient des drones (UAV), ni qu’ils venaient de l’étranger. Aucune conclusion sur chacun des objets n’était disponible, et leur trajectoire n’a pas été précisée.","Aucun dommage physique n’a été signalé. La détection est traitée comme un incident unique impliquant deux objets, et non comme deux incursions confirmées de drones étrangers."]},"E026":{"headline":"Un drone d’origine inconnue tombe dans le lac Drīdzis, en Lettonie, et explose","description":"Le 23 mai 2026, des habitants ont signalé la chute d’un drone dans le lac Drīdzis, dans la municipalité de Krāslava, en Lettonie, puis une explosion. Son origine n’a pas été établie.","summary":["Dans la matinée du 23 mai 2026, des habitants ont signalé la chute d’un drone dans le lac Drīdzis, dans la paroisse de Kombuļi, municipalité de Krāslava, en Lettonie. Le signalement est arrivé vers 08:00, heure locale, ce qui n’est pas nécessairement l’heure exacte de l’écrasement. Une explosion a été observée ; le type de charge est inconnu.","La nationalité et l’opérateur du drone sont inconnus. Il serait arrivé d’une direction proche de la Biélorussie, mais aucune attribution n’a été établie. Les capteurs n’auraient enregistré aucune violation auparavant, et l’origine faisait l’objet d’une enquête.","Aucune victime n’a été signalée. La Police d’État, des sauveteurs en bateau et les forces armées ont fouillé le lac, et des débris possibles ont été localisés."]},"E027":{"headline":"Un drone de contrebande récupéré sans cargaison près de Dumblė","description":"Les garde-frontières lituaniens indiquent que le drone artisanal tombé près de Dumblė le 23 mai 2026 ne transportait aucune cargaison et a été gravement endommagé à l’impact.","summary":["Le 23 mai 2026, un drone artisanal qui, selon le service lituanien des garde-frontières (VSAT), était entré depuis la Biélorussie est tombé près de Dumblė, dans le district de Šalčininkai, après l’intervention des garde-frontières.","Lorsque les agents ont récupéré l’appareil, il était gravement endommagé et ne transportait aucune cargaison. L’avis original du VSAT corrige la description antérieure d’un drone chargé.","Le VSAT a décrit l’appareil comme appartenant à des contrebandiers. L’opérateur n’est pas connu. Aucune victime ni aucun abattage cinétique n’ont été signalés."]},"E028":{"headline":"La Roumanie affirme qu’un drone russe a frappé un immeuble à Galați, faisant deux blessés","description":"Dans la nuit du 29 mai 2026, un drone a frappé un immeuble d’habitation à Galați, en Roumanie, faisant deux blessés. Les autorités roumaines l’ont identifié comme russe ; Moscou a contesté.","summary":["Dans la nuit du 29 mai 2026, un drone a frappé le toit d’un immeuble d’habitation dans le quartier de Mazepa, à Galați, en Roumanie, et déclenché un incendie. Deux personnes ont été légèrement blessées, des habitants ont été évacués et des logements ont été endommagés. Les responsables ont estimé que le drone transportait au moins 30 kg d’explosifs.","Sur la base d’une évaluation officielle des données radar et des débris, les autorités roumaines l’ont identifié comme un drone russe Geran-2. Il était associé à une vague plus large de 43 drones lors d’attaques contre l’Ukraine et a effectué un bref vol au-dessus de la Roumanie avant l’impact. Moscou a contesté l’attribution. La Roumanie n’a pas décrit la frappe comme une attaque intentionnelle dirigée contre la Roumanie.","Deux F-16 roumains et un hélicoptère ont décollé en urgence mais ne sont pas intervenus au-dessus de la ville, et le site a été examiné. Le consul russe a été expulsé et le consulat fermé en réponse. L’incident est distinct de l’écrasement d’un drone à Galați le 25 avril 2026.","Dans sa lettre du 29 mai au Conseil de sécurité de l’ONU, la Roumanie a fait état d’un suivi radar jusque dans le sud de Galați, d’un impact sur un toit résidentiel, d’un incendie, de deux blessés et d’une évacuation. La lettre attribue le drone à la Russie sans en identifier le modèle ni le poids de la charge."]},"E029":{"headline":"Une activité de drones présumée déclenche des alertes aux frontières lettone et estonienne","description":"Dans la nuit du 3 juin 2026, des drones présumés ont déclenché des alertes dans les régions frontalières orientales de la Lettonie et de l’Estonie. Des chasseurs de l’OTAN sont intervenus ; l’origine n’est pas confirmée.","summary":["Dans la nuit du 3 juin 2026, une activité présumée de drones (UAV) a déclenché des alertes dans les régions frontalières orientales de la Lettonie comme de l’Estonie. Des avertissements à la population ont été émis et des chasseurs de l’OTAN sont intervenus. Les trajectoires précises n’ont pas été publiées.","Le nombre et l’identité des objets restent non résolus. Une origine étrangère était soupçonnée, mais elle n’a pas été établie pour chaque objet, et aucun débris ni aucune attribution définitive n’ont été signalés.","Aucun impact ni aucune victime n’ont été confirmés. Les alertes dans les deux pays sont traitées comme un seul groupe transfrontalier, car les trajectoires individuelles ne peuvent pas être comptées de façon fiable."]},"E030":{"headline":"Un drone maritime atteint le port de Constanța, en Roumanie, puis explose de lui-même","description":"Le 5 juin 2026, un drone maritime d’un type utilisé par l’Ukraine a atteint le port de Constanța, en Roumanie, puis a explosé de lui-même. L’Ukraine a imputé sa dérive au brouillage russe.","summary":["Dans la matinée du 5 juin 2026, un drone maritime sans équipage (USV) a été trouvé dans le port de Constanța, en Roumanie, près du terminal pétrolier et des postes à quai, après s’être écarté de sa route pour entrer dans le port. Il a ensuite explosé de lui-même. D’autres détonations ont été signalées à proximité, et d’autres drones maritimes ont été signalés dans les eaux du large ; leur nombre n’a pas été établi.","Le drone était d’un type utilisé par l’Ukraine. L’Ukraine a attribué sa dérive au brouillage russe. Les opérateurs exacts, le nombre d’engins distincts au large et les mécanismes en jeu n’ont pas été pleinement établis.","Les autorités portuaires et de sécurité ont sécurisé la zone, et l’armée et les garde-côtes sont intervenus. Aucune victime ni aucun autre dommage important n’ont été signalés. Le port est un territoire souverain roumain ; la juridiction sur les eaux du large voisines varie."]},"E031":{"headline":"Un chasseur français de l’OTAN abat un drone près de Bērzgale, en Lettonie","description":"Le 8 juin 2026, un chasseur français de l’OTAN a abattu un drone dans l’espace aérien letton près de Bērzgale, en Lettonie. Sa nationalité et son modèle n’ont pas été identifiés de façon concluante.","summary":["Le 8 juin 2026, un drone (UAV) est entré dans l’espace aérien letton et a été intercepté dans la zone de Bērzgale, en Lettonie. Un avion de chasse français opérant avec l’OTAN l’a ensuite abattu.","Un porte-parole militaire letton a déclaré à Reuters que le drone était entré depuis la Russie, selon Euronews. Sa trajectoire exacte et son site de lancement n’ont pas été établis. La direction d’entrée signalée n’identifie ni son opérateur ni sa nationalité ; son modèle, sa charge et sa cible visée restaient non résolus dans les comptes rendus examinés.","Aucune victime n’a été signalée en Lettonie. Après l’abattage, une recherche des débris et une enquête sur ceux-ci ont suivi."]},"E032":{"headline":"La Roumanie détruit près de Rachelu des fragments de drone qu’elle a identifiés comme russes","description":"Le 30 juin 2026, l’armée roumaine a détruit des fragments de drone près de Rachelu, dans le département de Tulcea, en Roumanie. Le ministère de la Défense les a identifiés comme russes.","summary":["Le 30 juin 2026, l’armée roumaine a procédé à la détonation contrôlée de fragments de drone près de Rachelu, dans le département de Tulcea, en Roumanie. Les matériaux récupérés présentaient un risque explosif, de taille non précisée, et ont nécessité une neutralisation d’engins explosifs. Le 30 juin est la date de la neutralisation : le moment où le drone a volé, et celui où les fragments ont été trouvés, n’ont pas été établis.","Le ministère roumain de la Défense a identifié les fragments comme appartenant à un drone russe. L’itinéraire d’origine du drone n’est pas précisé et l’appareil lui-même n’a pas été identifié.","Aucune victime n’a été signalée. La neutralisation est traitée comme une récupération de débris, et non comme une nouvelle incursion en Roumanie démontrée séparément."]},"E033":{"headline":"Incendie du GAS LISBON au large de la Roumanie : un marin mort ; cause liée à des drones non confirmée","description":"Les 17 membres d’équipage du GAS LISBON ont été évacués au large de la Roumanie le 21 juillet. L’un des trois blessés est mort deux jours plus tard. Une cause liée à des drones reste non confirmée.","summary":["Le pétrolier GPL GAS LISBON, battant pavillon libérien, a subi une explosion et un incendie au large de Sfântu Gheorghe, dans la ZEE de la Roumanie, en dehors de ses eaux territoriales. L’Autorité navale a enregistré l’alerte de détresse à 00:05, heure locale, le 21 juillet, ce qui n’est pas l’heure vérifiée de l’explosion.","Deux membres de l’équipage ont décrit une attaque nocturne par trois drones. Leur récit est traité comme une allégation, et non comme une identification définitive de l’arme : le type de drone, les engins et charges utilisés, le point de lancement et l’opérateur ou la nationalité n’ont pas été identifiés, et une cause liée à des drones n’a pas été confirmée.","Cet incident est distinct de l’urgence du vraquier du 24 juillet et du sinistre du PROGRESS IV en août.","Les 17 membres d’équipage ont été évacués. Trois ont été blessés ; l’un de ces trois blessés est mort le 23 juillet à l’hôpital de Tulcea, a déclaré le ministère roumain de la Santé à AGERPRES. Des informations du gouvernement philippin ont corroboré le décès et le retour au pays des deux autres marins blessés. Le bilan des victimes n’établit pas une cause liée à des drones."]},"E034":{"headline":"Le vraquier Christina B endommagé au large de la Roumanie ; mine ou drone, la question reste non résolue","description":"Le 24 juillet 2026, le vraquier Christina B a été endommagé dans la ZEE roumaine de la mer Noire, au large de Sfântu Gheorghe. La question de savoir si une mine ou un drone maritime l’a touché n’est pas résolue.","summary":["Le 24 juillet 2026, le vraquier Christina B, battant pavillon libérien, un charbonnier qui aurait navigué des États-Unis vers l’Ukraine, a lancé un appel de détresse après un possible impact explosif en mer Noire. Le navire se trouvait à environ 22 milles au large de Sfântu Gheorghe, dans la zone économique exclusive (ZEE) de la Roumanie et en dehors des eaux territoriales souveraines roumaines.","Il n’a pas été établi si le navire avait heurté une mine ou avait été touché par un drone maritime. L’engin et le mécanisme de l’explosion sont non identifiés, l’implication d’un drone n’a pas été confirmée, et l’origine et l’opérateur restent non résolus.","Le navire a été endommagé ; aucun blessé n’a été signalé. Les autorités maritimes roumaines sont intervenues, et l’état du navire a été évalué en vue de la poursuite de son voyage ou de réparations."]},"E035":{"headline":"La Roumanie abat un drone qu’elle a identifié comme russe au-dessus du département de Buzău","description":"Le 24 juillet 2026, un F-16 roumain a abattu un drone de type Shahed au-dessus de Padina–Pogoanele, dans le département de Buzău, en Roumanie. Les autorités roumaines l’ont identifié comme russe.","summary":["Le 24 juillet 2026, un F-16 roumain a abattu un drone au-dessus d’une zone inhabitée de Padina–Pogoanele, dans le département de Buzău, en Roumanie. Le drone s’était approché depuis la zone de la mer Noire et du Danube, puis avait parcouru une longue distance à l’intérieur des terres. Des avions italiens de l’OTAN et des appareils roumains sont intervenus avant sa destruction.","Les autorités roumaines l’ont identifié comme un drone russe. Il a été décrit comme de type Shahed, mais sa désignation exacte n’a pas été établie de façon concluante, et les détails de son type et de sa trajectoire précise reposent sur des informations de seconde main. Les débris faisaient l’objet d’une enquête.","Aucune victime n’a été signalée."]},"E036":{"headline":"Un chasseur roumain abat un drone signalé comme russe au-dessus du littoral de Tulcea","description":"Le 25 juillet 2026, un chasseur roumain a abattu un drone signalé comme russe après une brève incursion au-dessus du littoral de Sfântu Gheorghe et de Tulcea, en Roumanie.","summary":["Le 25 juillet 2026, un drone (UAV) a fait une brève incursion dans l’espace aérien roumain au-dessus du secteur côtier de Sfântu Gheorghe et de Tulcea, et a été détruit par un avion de chasse roumain. Il était entré brièvement depuis la zone d’opérations de la guerre en Ukraine. Des fragments ont été recherchés ensuite.","Le drone a été signalé comme russe. Son modèle et sa charge faisaient l’objet d’une enquête, et son identification technique n’était pas terminée dans les comptes rendus de l’époque.","Aucune victime n’a été signalée."]},"E037":{"headline":"La Roumanie abat au large de Sulina un drone qu’elle a identifié comme russe","description":"Le 26 juillet 2026, un F-16 roumain a abattu un drone au-dessus des eaux territoriales, à 12 km au nord-est de Sulina. La Roumanie l’a identifié comme russe, le troisième en trois jours.","summary":["Le 26 juillet 2026, un drone (UAV) arrivant de la mer Noire a été abattu par un F-16 roumain au-dessus des eaux territoriales roumaines, à environ 12 km au nord-est de Sulina, en Roumanie. C’était le troisième drone que la Roumanie détruisait en trois jours consécutifs.","La Roumanie l’a identifié comme un drone russe. Son modèle n’a pas été précisé, et l’enquête sur son modèle et sa charge n’était pas terminée au moment où l’incident a été signalé.","Aucune victime n’a été signalée. Un ambassadeur a été convoqué à la suite de ces violations répétées."]},"E038":{"headline":"Un drone signalé comme russe pénètre brièvement dans le sud-est de la Roumanie","description":"Le 27 juillet 2026, un drone signalé comme russe est brièvement entré dans l’espace aérien du sud-est de la Roumanie et est reparti vers l’Ukraine avant d’être engagé. Aucun impact n’a été signalé.","summary":["Le 27 juillet 2026, un drone (UAV) aurait fait une brève incursion dans l’espace aérien du sud-est de la Roumanie avant de ressortir vers l’Ukraine. Son itinéraire exact n’a pas été précisé. La défense aérienne roumaine a surveillé le vol et y a réagi, mais le drone est reparti avant de pouvoir être engagé.","Le drone a été signalé comme russe, mais les détails de l’incident sont limités : aucune conclusion technique n’était disponible, et le modèle et la charge du drone n’ont pas été signalés. Aucun impact n’a été signalé en Roumanie."]},"E039":{"headline":"Des débris de drone tombent près de Periprava, en Roumanie, après une interception signalée","description":"Le 2 août 2026, un drone lié à des attaques contre l’Ukraine a quitté l’espace aérien roumain, aurait été intercepté en Ukraine, et des débris sont tombés près de Periprava, en Roumanie.","summary":["Dans l’après-midi du 2 août 2026, un drone (UAV) a été détecté au-dessus du bras de Sulina près de Periprava, dans le département de Tulcea, en Roumanie, à 15:09, heure locale. Des F-16 roumains ont décollé en urgence à 15:17 et l’ont surveillé. Le drone a poursuivi son vol vers l’Ukraine, où il aurait été détruit par les forces ukrainiennes, et des débris sont retombés dans un champ près de la frontière, à Periprava. L’alerte a pris fin à 16:05.","Le drone était associé à des attaques contre l’Ukraine ; son modèle final n’a pas été établi. Le ministère roumain de la Défense (MApN) a signalé le vol et la récupération, par l’intermédiaire de HotNews. Une interception et une chute de débris ont été signalées, mais il n’a pas été explicitement établi que le drone avait été abattu.","Aucune victime ni aucun dégât matériel n’ont été signalés. Le champ a été fouillé et les matériaux examinés."]},"E040":{"headline":"Vol de drone : aéroport de Leipzig/Halle, Allemagne","description":"4 août 2026, aéroport de Leipzig/Halle, Allemagne. Série d’attaques par drones explosifs ; attribution étatique officielle. Drone explosif parvenu à l’aéroport, mais charge défaillante.…","summary":["Un drone explosif a atteint l’aéroport, mais la charge a échoué. Par ailleurs, un avion cargo a signalé la rencontre d’un objet et s’est dérouté. Un autre drone d’attaque présumé a été récupéré près de Kabelsketal.","Série d’attaques par drones explosifs ; attribution étatique officielle. Le 1er septembre, l’Allemagne a attribué l’opération à des personnes agissant pour des services de l’État russe ; la Russie a nié toute responsabilité. L’attribution officielle allemande est consignée en tant qu’attribution, et non comme la publication de l’ensemble des éléments criminalistiques et de renseignement sous-jacents. Le démenti russe est conservé. Les conclusions de novembre concernant le site de lancement et le matériel restent des évaluations d’enquête, et non une preuve de la culpabilité d’un individu."]},"E041":{"headline":"Deux drones repérés au-dessus d’une installation militaire dans l’ouest de l’Allemagne","description":"Dans la nuit du 7 au 8 août 2026, deux drones ont été repérés au-dessus d’une installation militaire dans l’ouest de l’Allemagne. Aucun lien étranger ou russe n’a été établi.","summary":["Dans la nuit du 7 au 8 août 2026, deux drones ont été vus au-dessus d’une installation militaire dans l’ouest de l’Allemagne. Le site précis n’a pas été indiqué, et l’observation a été signalée le 8 août. Les points de lancement des drones sont inconnus.","Aucun lien étranger ou russe n’a été établi.","Aucun dégât ni aucune victime n’ont été signalés. Les autorités ont enquêté sur le survol du site sensible."]},"E042":{"headline":"Un drone évalué comme de type ukrainien s’écrase et explose à Kardam, en Bulgarie","description":"Le 8 août 2026, un drone signalé comme un leurre de type Maya s’est écrasé et a explosé dans un champ à Kardam, en Bulgarie. Il a été évalué comme de type ukrainien ; non confirmé.","summary":["Le 8 août 2026, un drone s’est écrasé et a explosé dans un champ de tournesols à Kardam, en Bulgarie, près de la frontière roumaine et à proximité d’infrastructures gazières. Il aurait traversé la Roumanie et la Bulgarie avant de s’écraser. Aucune victime ni aucun dommage important aux infrastructures n’ont été signalés.","Le drone a été signalé comme un leurre de type Maya et a été évalué, dans des articles antérieurs, comme de type ukrainien, mais son attribution finale n’a pas été établie de façon indépendante. Un effet explosif a été observé, mais la configuration exacte du drone est inconnue. Au 26 août, un ministre bulgare avait déclaré que l’Ukraine n’avait pas fourni les informations demandées ; le parquet militaire de Sliven est chargé de l’affaire.","La Bulgarie a enquêté, et des mesures défensives antidrones supplémentaires ont été signalées. Le vol à travers la Roumanie et l’écrasement en Bulgarie sont traités comme un seul incident, et non comme des incidents roumain et bulgare distincts."]},"E043":{"headline":"La marine roumaine détruit deux drones Gerbera à la dérive près de Neptun Deep","description":"Le 11 août 2026, deux drones Gerbera trouvés à la dérive près de Neptun Deep, à 90 milles marins au large de Constanța, dans la ZEE roumaine, ont été détruits. Opérateur non confirmé.","summary":["Dans la matinée du 11 août 2026, un navire civil a signalé deux drones aériens à la dérive en mer près de la zone de travaux de Neptun Deep, à environ 90 milles marins au large de Constanța. La zone se situe dans la zone économique exclusive (ZEE) de la Roumanie, et non dans sa mer territoriale. Une aile de drone distincte a également été trouvée ; il n’a pas été démontré qu’elle provienne d’un troisième drone.","Les drones ont été identifiés comme des drones aériens Gerbera, un type utilisé par la Russie. L’Ukraine a déclaré que les objets n’étaient pas ukrainiens. Aucun opérateur n’a été établi de façon concluante, et les itinéraires de vol d’origine des drones sont inconnus.","Des plongeurs de la marine roumaine et des spécialistes de la neutralisation d’engins explosifs, appuyés par les garde-côtes, ont détruit les deux drones, qui présentaient un risque explosif potentiel, et récupéré l’aile, qui aurait été non dangereuse. Aucune victime n’a été signalée. Il s’agissait de drones aériens flottant en mer, et non de navires de surface sans équipage, et ils sont distincts d’un cas de drone maritime du 20 août."]},"E044":{"headline":"La Lettonie dit que le drone abattu près de Rugāji par un avion italien était ukrainien","description":"Le 14 août 2026, un Eurofighter italien de l’OTAN a abattu un drone près de Rugāji, en Lettonie. Le 20 août, la Lettonie a confirmé que le drone était d’origine ukrainienne.","summary":["Tôt le 14 août 2026, un drone (UAV) qui approchait a été abattu par un Eurofighter italien volant avec l’OTAN près de Rugāji, dans la municipalité de Balvi, en Lettonie, à environ 35 km de la frontière russe. Des soldats ont ensuite recherché les débris.","Le drone n’a d’abord pas été identifié. Le 20 août, la Lettonie a confirmé qu’il était d’origine ukrainienne. Il pourrait être entré en Lettonie depuis la Biélorussie, et des interférences électroniques russes ont été envisagées, mais ni l’un ni l’autre n’a été établi de façon indépendante.","Aucune victime n’a été signalée. L’identification du 20 août était une mise à jour du même incident, et non une seconde incursion."]},"E045":{"headline":"Un avion espagnol de l’OTAN abat un drone signalé comme russe près de Galați, en Roumanie","description":"Le 16 août 2026, un F/A-18 espagnol affecté à l’OTAN a abattu un drone entre Băleni et Cudalbi, dans le département de Galați, en Roumanie. Il a été signalé comme russe.","summary":["Le 16 août 2026, un drone a été abattu entre Băleni et Cudalbi, dans le département de Galați, en Roumanie, à environ 24 km de Galați. Il serait entré dans l’espace aérien roumain par la Moldavie. Un chasseur F/A-18 espagnol affecté à l’OTAN l’a engagé au-dessus d’une zone inhabitée.","Le drone a été signalé comme russe, et un compte rendu de l’OTAN a décrit son origine comme apparemment russe. Des articles antérieurs indiquaient qu’il s’agissait d’un Geran-2, mais son type exact n’a pas été vérifié de façon indépendante. L’abattage lui-même a été confirmé.","Aucune victime n’a été signalée, et aucun détail sur la charge n’a été donné. Les débris ont été récupérés et ont fait l’objet d’une enquête."]},"E046":{"headline":"Un drone suivi jusqu’en Roumanie s’écrase au nord-est de Grindu, dans le département de Tulcea","description":"Le 20 août 2026, un drone est entré dans l’espace aérien roumain à l’est de Galați et s’est écrasé près de Grindu, dans le département de Tulcea. Son modèle et son opérateur n’ont pas été précisés.","summary":["Aux premières heures du 20 août 2026, un drone s’est écrasé à environ 4 km au nord-est de Grindu, dans le département de Tulcea, en Roumanie. Selon le ministère roumain de la Défense nationale, un groupe de drones a été détecté près de l’Ukraine à 02:23 et une alerte a été émise à 03:20 ; un drone est entré dans l’espace aérien roumain à environ 13 km à l’est de Galați à 03:21 et s’est écrasé à 03:24. L’alerte a pris fin à 03:52, heure locale.","Le drone était associé à des attaques de l’autre côté du Danube, mais le communiqué initial du ministère n’a précisé ni son modèle ni son opérateur, et aucun résultat criminalistique complet n’est disponible.","Il a brûlé brièvement après l’écrasement et le feu s’est éteint de lui-même ; aucune victime ni aucun dégât matériel n’ont été signalés. Des chasseurs F-18 espagnols et un hélicoptère roumain IAR-330 SOCAT sont intervenus, suivis d’une recherche et d’un examen technique. Un article antérieur indiquait que les fragments récupérés ne présentaient pas de risque explosif, ce que le communiqué initial n’a pas confirmé. L’écrasement est distinct du drone maritime signalé près de Neptun Deep le même jour."]},"E047":{"headline":"Un F-16 roumain tire sur un drone naval explosif près des travaux de Neptun Deep","description":"La Roumanie a neutralisé un drone maritime explosif près de Neptun Deep le 20 août. Son président l’a ensuite attribué à la marine russe.","summary":["Le 20 août 2026, un navire de surface sans équipage, ou drone maritime, chargé d’explosifs a été détecté à quelques centaines de mètres des travaux offshore de Neptun Deep, à environ 80 milles marins à l’est de Constanța, dans la zone économique exclusive de la Roumanie.","Un F-16 roumain a tiré sur lui avec son canon, l’endommageant sans le détruire entièrement, puis une équipe de neutralisation d’engins explosifs de la marine l’a neutralisé. Les informations officielles ont confirmé une charge explosive de taille non précisée. Le ministère de la Défense a d’abord décrit deux drones, puis corrigé en un seul. Aucune victime ni aucun dommage aux infrastructures n’ont été signalés.","Le 23 septembre, le président Nicușor Dan a déclaré au Conseil de sécurité de l’ONU que le drone du 20 août était un drone de la marine russe. Il n’a pas divulgué les éléments étayant cette attribution. Le point de lancement et la cible visée restent non vérifiés. Le cas est distinct du drone aérien écrasé près de Grindu le même jour.","Dans un récit rétrospectif publié par SpotMedia le 24 novembre, l’ancien ministre de la Défense Radu Miruță a décrit des ouvriers filmant le drone près des supports de la plateforme et un remorqueur tentant de le tenir à distance. Il a également indiqué avoir reçu un avis russe de restriction de vol après avoir ordonné l’intervention des chasseurs. L’avis original n’a pas été examiné de façon indépendante ; ces détails mettent à jour l’incident d’août et ne constituent pas un nouvel événement."]},"E048":{"headline":"La marine détruit des débris de drone explosif trouvés sur la plage de Tuzla, en Roumanie","description":"Le 22 août 2026, la marine a détruit des débris de drone explosif sur la plage de Tuzla, en Roumanie. Ils ont été évalués à titre préliminaire comme de fabrication ukrainienne ; opérateur non confirmé.","summary":["Le 22 août 2026, des fragments d’un drone aérien contenant des explosifs ont été trouvés dans la zone de la plage de Tuzla, dans le département de Constanța, en Roumanie. La découverte a été signalée aux services d’urgence, la zone a été bouclée et des spécialistes ont examiné l’objet.","Une évaluation préliminaire du ministère roumain de la Défense nationale (MApN) a indiqué une fabrication ukrainienne. Cette conclusion est préliminaire, et l’opérateur et la mission du drone n’ont pas été confirmés. La date et l’itinéraire de son vol d’origine sont inconnus, tout comme le nombre de drones dont proviennent les fragments.","Une équipe de neutralisation d’engins explosifs de la marine a procédé à deux détonations contrôlées, la première n’ayant pas détruit entièrement la charge ; les deux explosions faisaient partie d’une même neutralisation. Les procureurs de la cour d’appel de Constanța ont été informés. Aucune victime n’a été signalée."]},"E049":{"headline":"Un fragment de drone Gerbera explosif neutralisé au large de Gura Portiței, en Roumanie","description":"Le 23 août 2026, un fragment flottant de drone Gerbera contenant des explosifs a été neutralisé en mer au large de Gura Portiței, en Roumanie. Son opérateur n’est pas établi.","summary":["Le 23 août 2026, un objet suspect a été trouvé flottant dans les eaux côtières au large de Gura Portiței, dans le département de Tulcea, en Roumanie. Des spécialistes de la neutralisation d’engins explosifs de la marine l’ont examiné ; il s’agissait du corps ou d’un fragment d’un drone aérien Gerbera contenant de la matière explosive.","Le ministère roumain de la Défense nationale a confirmé le type et le risque explosif. Des articles antérieurs qualifiaient le drone de russe, et le Gerbera est un type utilisé par la Russie, mais le type seul n’établit pas qui en était l’opérateur. La date et l’itinéraire de son vol d’origine sont inconnus, et la juridiction exacte en mer n’a pas été précisée.","L’équipe de neutralisation, travaillant depuis un navire des garde-côtes, a neutralisé l’objet sur place. Aucune victime n’a été signalée. Le fragment provenait d’un drone aérien, et non d’un drone maritime, et ne fait pas partie de l’incident du drone maritime de Neptun Deep."]},"E050":{"headline":"Un drone signalé comme russe tombe dans un arbre près d’une maison à Ciușlea, en Roumanie","description":"Le 24 août 2026, un drone signalé comme russe est tombé dans un arbre à environ 5 m d’une maison à Ciușlea, dans le département de Vrancea, en Roumanie. Il ne transportait pas d’explosifs.","summary":["Le 24 août 2026, un drone est tombé dans un arbre à environ 5 mètres d’une maison à Ciușlea, dans le département de Vrancea, en Roumanie. Il serait entré dans l’espace aérien roumain par la Moldavie.","Le drone a été signalé comme russe ; son modèle précis n’a pas été établi. Le ministère roumain de la Défense nationale (MApN) a indiqué qu’il ne transportait aucune charge explosive.","Aucun blessé n’a été signalé malgré la proximité de la chute du drone par rapport à la maison. Des avions de chasse et un hélicoptère sont intervenus, la zone a été sécurisée et le drone a été récupéré pour enquête. Des articles antérieurs mentionnaient aussi une évacuation de précaution."]},"E051":{"headline":"Un fragment de drone présumé trouvé près de la promenade du casino de Constanța, en Roumanie","description":"Dans la soirée du 25 août 2026, des passants ont trouvé un fragment de drone présumé près de la promenade du casino de Constanța, en Roumanie. Son origine n’a pas été établie.","summary":["Dans la soirée du 25 août 2026, des passants ont remarqué un objet près du casino de Constanța, en Roumanie. L’objet, un élément de drone présumé, se serait échoué entre les brise-lames, près de la promenade du casino. La découverte a été signalée dans des articles le 26 août.","L’objet n’a pas été confirmé comme faisant partie d’un drone, et son identité complète, son origine et son opérateur n’ont pas été établis. Aucun explosif n’a été identifié lors de son examen.","Des pompiers et des spécialistes ont récupéré et examiné l’objet, et aucun dommage n’a été signalé. Il s’agit d’une découverte distincte du drone explosif trouvé sur la plage d’Olimp le lendemain matin."]},"E052":{"headline":"Plage évacuée après la détonation d’un fragment de drone explosif à Olimp, en Roumanie","description":"Le 26 août 2026, la plage d’Olimp, dans le département de Constanța, en Roumanie, a été évacuée et un fragment de drone explosif qui s’y trouvait a été détoné. Aucune origine n’a été annoncée.","summary":["Le 26 août 2026, un fragment de drone contenant de la matière explosive a été trouvé sur la plage touristique d’Olimp, dans le département de Constanța, en Roumanie. La plage a été évacuée, l’accès a été restreint, un cordon a été mis en place et une alerte RO-Alert a été émise.","Des spécialistes de la Brigade antiterroriste du SRI ont détoné les matériaux sur la plage lors d’une explosion contrôlée. Aucune victime n’a été signalée.","Les autorités n’avaient annoncé ni l’origine du fragment ni le modèle de drone dans les informations du 26 au 27 août, et la date et l’itinéraire du vol d’origine sont inconnus."]},"E053":{"headline":"Le navire marchand Progress IV coule au large de la Roumanie ; frappe de drone non confirmée","description":"Le 27 août 2026, le navire Progress IV a pris feu et a coulé au large de Sfântu Gheorghe, dans la ZEE roumaine. Les 12 membres d’équipage ont été secourus ; une frappe de drone n’est pas confirmée.","summary":["Le 27 août 2026, le navire marchand Progress IV a pris feu et a coulé en mer Noire, à environ 15–20 milles marins de Sfântu Gheorghe, dans la zone économique exclusive de la Roumanie. Un appel de détresse a été émis vers 17:55, heure locale, et les 12 membres d’équipage avaient tous été secourus à 20:47.","Un impact sur le navire a été allégué, et les autorités ont indiqué que sa cause nécessitait une enquête. Une attaque de drone restait une hypothèse : aucun drone ni aucune autre arme n’a été identifié, et aucune explosion ni frappe de drone n’a été établie. Le pavillon du navire a été signalé comme celui de la République dominicaine, tandis qu’une source du secteur maritime citait la Dominique.","Un membre d’équipage a été blessé, avec une fracture du bras selon les informations ; les premières descriptions d’une blessure grave ne sont pas étayées par les comptes rendus ultérieurs. Le centre de coordination de sauvetage maritime (MRCC) a coordonné un navire commercial, la Police des frontières et des navires de sauvetage.","Le 24 novembre, Libertatea a rapporté que la Direction hydrographique maritime roumaine estimait que le navire avait été touché par un drone. Les avis de navigation publiés par la Direction établissent la présence de l’épave et signalent des dangers, mais n’indiquent pas de cause. Aucune conclusion criminalistique, aucune arme ni aucun opérateur n’est établi."]},"E054":{"headline":"Un berger trouve un drone explosif près de Viișoara, en Roumanie ; origine contestée","description":"Le 1er septembre 2026, un berger a trouvé un drone endommagé contenant des explosifs dans un champ près de Viișoara, dans le département de Vaslui, en Roumanie. Son origine officielle n’est pas résolue.","summary":["Le 1er septembre 2026, un berger qui gardait des moutons a trouvé un drone (UAV) endommagé dans un champ près de Viișoara, dans le département de Vaslui, en Roumanie. La date est celle de la découverte vérifiée, et non une date de chute établie : la personne qui l’a trouvé n’a pas vu le drone tomber, et son itinéraire de vol et l’heure de sa chute sont inconnus. Avant l’arrivée des autorités, le berger a manipulé le drone et en a déconnecté certaines pièces.","Des spécialistes ont confirmé qu’il contenait de la matière explosive. Le type de drone n’a pas été confirmé, et son origine officielle n’est pas résolue : des informations locales ont avancé des affirmations contradictoires selon lesquelles il était russe ou ukrainien, et l’identité et la provenance de l’engin faisaient l’objet d’une enquête.","Des gendarmes ont sécurisé le site et des artificiers du SRI ont détruit le drone par une détonation contrôlée. Les procureurs de la cour d’appel de Iași ont été informés. Aucune victime n’a été signalée."]},"E055":{"headline":"Drone trouvé à Pellinki le 1er septembre ; une origine russe jugée probable","description":"Un drone trouvé à Pellinki le 1er septembre a été évalué comme probablement d’origine russe. Selon les enquêteurs, il est tombé en mer hors de Finlande ; les investigations se sont poursuivies.","summary":["Un civil a trouvé un UAV parmi les rochers du rivage de Pellinki le 1er septembre 2026 ; une patrouille des garde-frontières l’a confirmé. La date antérieure du registre, le 2 septembre, était la date de la première communication. L’adresse de la page publiée est conservée.","Le 10 septembre, les garde-frontières ont indiqué que les données de l’appareil suggéraient un aéronef probablement d’origine russe qui avait perdu le contrôle et manqué de carburant avant de tomber en mer en dehors de la Finlande. Cette conclusion était préliminaire et l’enquête s’est poursuivie.","Il s’agit toujours d’une seule récupération, et non d’une incursion aérienne ou d’un écrasement établi en Finlande. L’opérateur et la finalité initiale restent non résolus. Le point sur la carte est un ancrage approximatif dans l’archipel."]},"E056":{"headline":"Un drone à réaction signalé comme russe passe de la Moldavie au nord-est de la Roumanie","description":"Le 8 septembre 2026, un drone à réaction signalé comme russe a volé de la Moldavie vers le nord-est de la Roumanie pendant environ 30 minutes, entraînant des restrictions à l’aéroport de Iași.","summary":["Le 8 septembre 2026, un drone à réaction est entré dans l’espace aérien roumain depuis la Moldavie vers 16:37, heure locale, et a traversé le secteur de Neamț, Botoșani et Iași, dans le nord-est de la Roumanie. Il est resté environ 30 minutes dans l’espace aérien roumain avant de repartir vers la Moldavie, où il se serait écrasé. Les horaires de différentes parties du vol varient selon les comptes rendus.","Le drone a été signalé comme russe. Son identification technique comme Geran-4 à réaction est attribuée à des informations roumaines et moldaves.","Deux chasseurs F/A-18 espagnols ont décollé en urgence, et les autorités ont surveillé le vol et averti les habitants. Des restrictions ont été imposées à l’aéroport de Iași et des alertes civiles ont été émises. Aucun impact ni aucune victime n’ont été signalés en Roumanie ; l’écrasement signalé a eu lieu hors de l’UE, en Moldavie."]},"E057":{"headline":"Drone récupéré sur la plage de Rusinowo ; ogive neutralisée en toute sécurité","description":"Un drone s’est échoué près de Rusinowo le 14 septembre. Le parquet a identifié à titre préliminaire un Gerbera de fabrication russe et décrit une neutralisation contrôlée de l’ogive.","summary":["Un équipage de la marine a observé un UAV dérivant près de Jarosławiec vers 09:20 le 14 septembre ; il s’est échoué près de Rusinowo vers 11:25, selon la déclaration du parquet de Poznań du 1er octobre. Il s’agit d’un seul événement de récupération et de neutralisation, et non d’un autre événement survenu à la date de publication du suivi.","Des spécialistes ont séparé une ogive comportant une charge explosive potentielle et l’ont détruite par une détonation contrôlée. Les enquêteurs ont identifié à titre préliminaire un Gerbera de fabrication russe. L’opérateur, la cible, l’itinéraire de vol et les circonstances de l’impact en mer restent non résolus ; la fabrication n’établit ni l’opérateur ni l’intention.","L’enquête a été transférée à Poznań le 25 septembre et des expertises spécialisées ont été ordonnées. Aucune victime ni aucun dégât n’ont été signalés."]},"E058":{"headline":"Un chasseur italien de l’OTAN abat un drone Gerbera près de Pratkūnai, en Lituanie","description":"Dans la nuit du 14 au 15 septembre 2026, un avion italien de l’OTAN a abattu un drone Gerbera, un type utilisé par la Russie, près de Pratkūnai, en Lituanie. Aucune victime n’a été signalée.","summary":["Dans la nuit du 14 au 15 septembre 2026, un avion de chasse italien opérant avec l’OTAN a engagé et abattu un drone au-dessus de la Lituanie, près de Pratkūnai. Les autorités lituaniennes ont ensuite examiné les débris et l’électronique du drone. Aucune victime n’a été signalée.","Le drone a été identifié comme un Gerbera, un type utilisé par la Russie. Le 16 septembre, le président lituanien a estimé qu’il était probablement destiné à une cible ukrainienne. Un possible détournement par la guerre électronique ukrainienne a été avancé pour expliquer comment il a atteint la Lituanie, mais cette explication causale est une évaluation. Ni l’identification d’un type russe ni l’évaluation de la cible visée ne prouvent une attaque délibérée contre la Lituanie.","Le ministre lituanien de la Défense, Robertas Kaunas, a déclaré que le drone transportait un explosif, a rapporté Reuters le 15 septembre. Il s’agit d’une déclaration officielle attribuée ; les conclusions criminalistiques indépendantes et la charge explosive exacte n’ont pas été examinées. Elle n’établit pas une attaque délibérée contre la Lituanie."]},"E059":{"headline":"La Roumanie dit que la charge d’un drone russe a explosé en vol avant l’écrasement à Solca","description":"Le 24 septembre 2026, un drone entré depuis l’Ukraine s’est écrasé près de Solca, en Roumanie, après que sa charge a explosé en vol. Des responsables roumains l’ont dit russe.","summary":["Le 24 septembre 2026, un petit drone a franchi la frontière depuis l’Ukraine vers l’espace aérien roumain au-dessus du nord de Botoșani et s’est écrasé dans un bois près de Solca, dans le département de Suceava, après environ quatre minutes dans l’espace aérien roumain ; un radar militaire a confirmé l’entrée. Le ministre Miruță a déclaré que sa charge explosive s’était détachée peu avant l’écrasement et avait explosé en l’air. Des habitants ont localisé et filmé les débris.","Miruță a décrit un drone de modèle russe doté d’un équipement que les spécialistes roumains n’avaient jamais rencontré. L’Institute for the Study of War a identifié les débris, à partir d’images géolocalisées, comme un drone russe de type Gerbera ; il s’agit de l’évaluation de l’ISW, et non d’une identification officielle du modèle par la Roumanie. Le ministère lituanien des Affaires étrangères a attribué à des drones russes les incursions plus larges du 24 septembre en Roumanie et en Moldavie. L’unité de lancement, la cible visée et la cause de l’incursion restent non résolues.","Deux F-16 roumains ont décollé de Borcea pour surveiller le drone, et un hélicoptère IAR-330 SOCAT a décollé de Bacău à 07:21. Miruță a déclaré que les conditions pour l’engager n’étaient pas réunies ; il n’a pas été abattu. Des équipes du ministère de l’Intérieur ont sécurisé le site. Aucune victime ni aucun dégât matériel n’ont été signalés, et il n’y a pas eu d’incendie sur le site de l’écrasement."]},"E060":{"headline":"Un drone d’origine inconnue survole le bras de Chilia, en Roumanie","description":"Dans la nuit du 12 au 13 août 2026, un drone a volé environ 10 minutes le long du bras de Chilia, en Roumanie, avant de repartir vers l’Ukraine. Son origine n’est pas établie.","summary":["Dans la nuit du 12 au 13 août 2026, un drone (UAV) est entré dans l’espace aérien roumain et a volé environ 10 minutes le long du bras de Chilia, puis est reparti vers l’Ukraine, en ressortant à environ 13 km au sud-ouest de Chilia Veche. L’armée roumaine a surveillé le vol. Des explosions ont été signalées après le départ du drone, mais aucun impact en Roumanie n’a été établi.","La nationalité et l’opérateur du drone n’ont pas été établis, et son identité reste non résolue.","Des F-16 roumains ont également réagi à une cible ultérieure à proximité. La trajectoire nocturne a été signalée en même temps que la découverte de fragments de drone sur la plage de Costinești le même jour, mais les deux n’ont pas été liés, et le lien du drone avec des récupérations ultérieures n’est pas résolu."]},"E061":{"headline":"Des fragments de drone d’origine inconnue trouvés sur la plage de Costinești, en Roumanie","description":"Les 13 et 14 août 2026, des fragments de drone aérien ont été trouvés sur la plage de Tineretului, à Costinești, en Roumanie. Leur origine et le nombre de drones sont inconnus.","summary":["Vers 08:15 le 13 août 2026, des matériaux de drone aérien ont été signalés près des brise-lames de la plage de Tineretului, à Costinești, en Roumanie, après s’être échoués. L’accès des touristes a été restreint. Un autre fragment a été trouvé à proximité le lendemain, 14 août.","L’origine et l’opérateur des matériaux n’ont pas été établis. Des responsables les ont identifiés comme des fragments d’un drone aérien, et non d’un drone maritime. Le lien entre les fragments, le nombre de drones distincts dont ils proviennent et leur provenance exacte faisaient l’objet d’une enquête, et aucune route de vol n’a été observée.","Des plongeurs militaires et des spécialistes de la neutralisation d’engins explosifs, les garde-côtes et d’autres services d’urgence sont intervenus et ont récupéré les matériaux. Aucun risque pyrotechnique n’a été signalé pour les matériaux examinés, et aucun blessé n’a été signalé. Les procureurs de la cour d’appel de Constanța ont été informés."]},"E062":{"headline":"Un fragment de drone d’origine inconnue s’échoue sur la plage de Saturn, en Roumanie","description":"Le 14 août 2026, les vagues ont rejeté un fragment de drone aérien sur la plage de Saturn, dans le département de Constanța, en Roumanie. Des touristes ont alerté les autorités ; son origine n’est pas résolue.","summary":["Dans l’après-midi du 14 août 2026, les vagues ont rejeté un fragment de drone aérien sur la plage de Saturn, dans le département de Constanța, sur la côte roumaine. Des touristes ont alerté les autorités, et l’accès à la zone a été restreint pendant l’examen de l’objet.","L’identité de celui qui a lancé le drone, et le type de drone dont provient le fragment, n’ont pas été établis. Les informations roumaines sur la découverte évoquaient aussi des fragments trouvés à Costinești, mais aucun lien entre les deux découvertes n’a été établi.","Des spécialistes ont indiqué que le fragment ne contenait aucun élément pyrotechnique. Il a été examiné et récupéré, et aucun blessé n’a été signalé."]},"E063":{"headline":"Un drone s’écrase dans le nord de Tulcea, en Roumanie ; des débris dans les monts Măcin","description":"Le 14 août 2026, au moins un drone s’est écrasé dans le nord du département de Tulcea, en Roumanie, avec des débris signalés ensuite dans les monts Măcin. Son origine est inconnue.","summary":["Le 14 août 2026, au moins un drone s’est écrasé dans le nord du département de Tulcea, en Roumanie. Un appel d’urgence a signalé un écrasement dans une forêt, ayant provoqué un incendie localisé. Les premières informations le situaient près de Luncavița et de Cetățuia ; des informations ultérieures ont localisé des débris près de Greci, dans les monts Măcin. Le drone aurait volé suffisamment bas pour échapper au radar, et son itinéraire est inconnu.","L’origine et le modèle du drone n’ont pas été établis dans les informations de l’époque. On ignore aussi si les signalements de Luncavița et de Greci décrivent un seul site d’écrasement ou des sites liés ou distincts.","Des spécialistes militaires sont intervenus avec un appui d’hélicoptère, et la Police des frontières a mis en place un cordon. Un suivi ultérieur a fait état d’une neutralisation contrôlée dans les monts Măcin le même jour ; la charge exacte n’a pas été établie. Aucune victime ni aucun dégât matériel n’ont été signalés. Un objet distinct découvert le même jour à Plauru est un incident différent."]},"E064":{"headline":"Un drone trouvé près de Plauru, en Roumanie, détruit le lendemain par des spécialistes","description":"Un drone trouvé près de Plauru, dans le département de Tulcea, en Roumanie, le 14 août 2026 a été détruit lors d’une détonation contrôlée le 15 août. Son origine et son modèle sont inconnus.","summary":["Le 14 août 2026, une équipe militaire roumaine a repéré un drone près de Plauru, dans le département de Tulcea, près de la frontière ukrainienne. Le site a été sécurisé le jour même, et le 15 août, des spécialistes ont détruit l’objet par une détonation contrôlée.","La nationalité et le modèle du drone n’ont pas été établis, et les communiqués du ministère roumain de la Défense nationale (MApN) n’ont donné aucun détail technique. La date et l’itinéraire de son vol d’origine sont inconnus : le 14 août est le jour de sa découverte, pas nécessairement celui de son vol.","Aucune victime n’a été signalée, et la charge exacte n’a pas été précisée. La découverte de Plauru s’est faite à un endroit différent des débris signalés dans les monts Măcin le même jour."]},"E065":{"headline":"Un démarreur trouvé au large de Tyulenovo, en Bulgarie ; lien avec un drone non établi","description":"Le 14 août 2026, la marine bulgare a récupéré un objet à la dérive à environ 50 m au large de Tyulenovo, en Bulgarie, identifié comme un démarreur. Tout lien avec un drone n’est pas prouvé.","summary":["Le 14 août 2026, la marine bulgare a examiné un objet à la dérive à environ 50 mètres du rivage à Tyulenovo, dans le district de Dobrich, en Bulgarie, et l’a emmené vers une base navale.","L’objet a été identifié uniquement comme un démarreur. Il n’a pas été établi qu’il provenait d’un drone ; il ne s’agit donc pas d’une découverte de drone confirmée, et son origine est inconnue. Les associations avec des drones russes ou ukrainiens établies pour l’ensemble plus large des découvertes n’identifient pas cet objet. On ignore aussi quand et comment il s’est retrouvé en mer.","Aucune victime n’a été signalée."]},"E066":{"headline":"Un drone de reconnaissance d’origine inconnue s’échoue à Primorsko, en Bulgarie","description":"Le 14 août 2026, un drone de reconnaissance s’est échoué sur la plage de Primorsko, dans le district de Bourgas, en Bulgarie, et la marine l’a emmené à sa base. Son origine n’est pas résolue.","summary":["Le 14 août 2026, un drone de reconnaissance (UAV) s’est échoué sur la plage de Primorsko, dans le district de Bourgas, en Bulgarie. Il a été examiné, et la marine bulgare l’a transporté vers une base navale.","Aucun opérateur n’a été identifié pour le drone, et le communiqué signalant la découverte n’a donné aucune identification définitive. Les associations avec des drones russes ou ukrainiens établies pour l’ensemble plus large des découvertes n’identifient pas celui-ci. Le moment de sa chute et la route qu’il a suivie sont inconnus.","Aucune victime n’a été signalée, et l’éventuelle charge n’a pas été précisée."]},"E067":{"headline":"Des pièces de drone d’origine inconnue trouvées sur la plage de Lozenets, en Bulgarie","description":"Le 14 août 2026, des pièces de drone ont été trouvées sur la plage de Lozenets, dans le district de Bourgas, en Bulgarie, et récupérées par la marine. L’identité de l’opérateur du drone n’est pas résolue.","summary":["Le 14 août 2026, des pièces de drone ont été découvertes sur la plage de Lozenets, dans le district de Bourgas, en Bulgarie. La découverte a entraîné une intervention de la marine bulgare, qui a récupéré les pièces et les a emmenées vers une base.","Aucun opérateur n’a été identifié, et le communiqué signalant la découverte n’a donné aucune identification définitive du drone. Les associations avec des drones russes ou ukrainiens établies pour l’ensemble plus large des découvertes n’identifient pas ces pièces. La date de la chute du drone et son itinéraire d’origine sont inconnus.","Aucune victime n’a été signalée, et l’éventuelle charge n’a pas été précisée."]},"E068":{"headline":"Signalement non vérifié de débris d’aéronef ou de drone près d’Albena, en Bulgarie","description":"Un signalement de seconde main fait état de débris d’aéronef ou de drone récupérés sur la côte entre Albena et Kranevo, en Bulgarie, le 22 août 2026. Il n’est pas vérifié.","summary":["Un signalement de seconde main indique que, le 22 août 2026, des débris décrits comme provenant d’un aéronef ou d’un drone ont été trouvés sur la côte entre la station balnéaire d’Albena et Kranevo, en Bulgarie, entraînant une intervention de la marine. Les débris auraient été inspectés et récupérés.","Le récit provient uniquement d’un article secondaire de SofiaBeacon qui rappelait deux récupérations de débris côtiers le 22 août. L’objet exact, son origine et le communiqué officiel d’origine n’ont pas été vérifiés. Aucun opérateur n’a été identifié, et les associations avec des drones russes ou ukrainiens établies pour l’ensemble plus large des découvertes n’identifient pas ces débris. Le moment et la manière dont ils ont atteint la côte sont inconnus.","Aucune victime n’a été signalée."]},"E069":{"headline":"Signalement non vérifié de débris d’aéronef ou de drone à Rakitnika, en Bulgarie","description":"Un signalement de seconde main fait état de débris d’aéronef ou de drone récupérés dans la zone de Rakitnika, près de Varna, en Bulgarie, le 22 août 2026. Le récit n’est pas vérifié.","summary":["Un signalement de seconde main indique que, le 22 août 2026, des débris décrits comme provenant d’un aéronef ou d’un drone ont été trouvés dans la zone de Rakitnika, près de Varna, en Bulgarie. La marine les aurait inspectés et récupérés.","Le récit provient uniquement d’un article secondaire de SofiaBeacon qui rappelait deux récupérations de débris côtiers le 22 août et identifiait Rakitnika comme un lieu d’intervention. L’objet exact, son origine et le communiqué officiel d’origine n’ont pas été vérifiés. Aucun opérateur n’a été identifié, et les associations avec des drones russes ou ukrainiens établies pour l’ensemble plus large des découvertes n’identifient pas ces débris.","Aucune victime n’a été signalée."]},"E070":{"headline":"Un drone de reconnaissance électrique récupéré en mer près de Tsarevo, en Bulgarie","description":"Le 25 août 2026, la marine bulgare a récupéré en mer un drone de reconnaissance électrique entre Tsarevo et Varvara, en Bulgarie. Son origine n’est pas résolue.","summary":["Le 25 août 2026, un drone de reconnaissance électrique (UAV) a été trouvé en mer entre Tsarevo et Varvara, en Bulgarie. Il a été inspecté en mer et signalé comme non dangereux, et une équipe de la marine bulgare de Bourgas l’a transporté vers une base.","Aucun opérateur n’a été identifié pour le drone, et les communiqués qui le signalent n’ont donné aucune identification définitive. Les associations avec des drones russes ou ukrainiens établies pour l’ensemble plus large des découvertes n’identifient pas celui-ci. Le moment de la chute du drone et la route qu’il a suivie sont inconnus.","Aucune victime n’a été signalée."]},"E071":{"headline":"Une aile de drone militaire s’échoue sur la côte de Kamchia, en Bulgarie","description":"Dans la soirée du 25 août 2026, une aile de drone militaire s’est échouée sur la côte de la station balnéaire de Kamchia, en Bulgarie, et la marine l’a récupérée. Origine non résolue.","summary":["Dans la soirée du 25 août 2026, une aile d’un drone militaire s’est échouée sur la côte de la station balnéaire de Kamchia, en Bulgarie. Une équipe de la marine bulgare de Varna l’a récupérée.","L’aile ne portait aucune munition. Aucun opérateur n’a été identifié, et les communiqués qui la signalent n’ont donné aucune identification définitive. Les associations avec des drones russes ou ukrainiens établies pour l’ensemble plus large des découvertes n’identifient pas cette aile. Le moment et le lieu de la chute du drone sont inconnus.","Aucune victime n’a été signalée. Il n’a pas été établi si l’aile appartient au même appareil qu’un drone signalé lors d’une intervention distincte le 27 août."]},"E072":{"headline":"Des restes de drone récupérés sur la plage de Kabakum, près de Varna, en Bulgarie","description":"Le 26 août 2026, des restes de drone trouvés sur la plage de Kabakum, près de Varna, en Bulgarie, ont été emmenés à Varna par la marine. Aucun explosif n’a été trouvé ; origine non résolue.","summary":["Tôt le 26 août 2026, après une alerte reçue vers 01:30, la plage de Kabakum (aussi orthographiée Cabacum), près de Varna, en Bulgarie, a été sécurisée à la suite de la découverte de restes de drone. Les informations décrivaient les matériaux à la fois comme un UAV et comme des restes de fuselage.","La marine bulgare a inspecté les matériaux, n’a trouvé aucun explosif et les a transportés à Varna.","Aucun opérateur n’a été identifié, et les communiqués n’ont donné aucune identification définitive. Les associations avec des drones russes ou ukrainiens établies pour l’ensemble plus large des découvertes n’identifient pas celui-ci. Le moment de la chute du drone est inconnu. Aucune victime n’a été signalée."]},"E073":{"headline":"Un drone flottant détruit en mer par la marine près de Pomorie, en Bulgarie","description":"Le 26 août 2026, la marine a détruit en mer un drone flottant près de Pomorie, en Bulgarie. La charge exacte n’a pas été indiquée, et l’origine du drone n’est pas résolue.","summary":["Le 26 août 2026, un objet flottant en mer Noire près de Pomorie, en Bulgarie, a été identifié comme un drone (UAV). La marine bulgare l’a détruit en mer.","La charge exacte n’a pas été indiquée, et la destruction contrôlée ne montre pas à elle seule que le drone transportait une ogive active. Aucun opérateur n’a été identifié, et les communiqués qui le signalent n’ont donné aucune identification définitive. Les associations avec des drones russes ou ukrainiens établies pour l’ensemble plus large des découvertes n’identifient pas celui-ci. Le moment de la chute du drone et la route qu’il a suivie sont inconnus.","Aucune victime n’a été signalée."]},"E074":{"headline":"Un drone détruit en mer par la marine à Pasha Dere, au sud de Varna, en Bulgarie","description":"Le 26 août 2026, la marine a détruit en mer un drone à Pasha Dere, au sud de Varna, en Bulgarie. La charge exacte n’a pas été indiquée ; son origine n’est pas résolue.","summary":["Le 26 août 2026, un drone (UAV) a été inspecté dans les eaux côtières de Pasha Dere, au sud de Varna, en Bulgarie. La marine bulgare l’a détruit en mer.","La charge exacte n’a pas été indiquée, et la destruction contrôlée n’établit pas en soi que le drone transportait une charge explosive. Aucun opérateur n’a été identifié, et les communiqués qui le signalent n’ont donné aucune identification définitive. Les associations avec des drones russes ou ukrainiens établies pour l’ensemble plus large des découvertes n’identifient pas celui-ci. Le moment de la chute du drone et la route qu’il a suivie sont inconnus.","Aucune victime n’a été signalée."]},"E075":{"headline":"Un drone partiellement immergé remorqué jusqu’à Varna depuis le large du cap Galata, en Bulgarie","description":"Le 26 août 2026, un drone partiellement immergé trouvé à 2,6 milles marins au nord-est du cap Galata, en Bulgarie, a été remorqué jusqu’à la base navale de Varna. Son origine n’est pas résolue.","summary":["Le 26 août 2026, un drone aérien (UAV) partiellement immergé a été trouvé en mer à 2,6 milles marins au nord-est du cap Galata, en Bulgarie. Son moteur et son nez étaient sous l’eau, la queue étant visible.","Aucune matière explosive n’a été trouvée. Le drone a été remorqué jusqu’à la base navale de Varna et sorti de l’eau.","Aucun opérateur n’a été identifié, et le communiqué qui le signale n’a donné aucune identification définitive. Les associations avec des drones russes ou ukrainiens établies pour l’ensemble plus large des découvertes n’identifient pas celui-ci. Le moment de la chute du drone et la route qu’il a suivie sont inconnus. Aucune victime n’a été signalée."]},"E076":{"headline":"Une aile de drone trouvée près du camping Laguna à Sables d’Or, en Bulgarie","description":"Le 26 août 2026, une aile de drone a été trouvée près de la plage du camping Laguna, dans la station de Sables d’Or, en Bulgarie, et emmenée par la marine. Origine non résolue.","summary":["Le 26 août 2026, une aile de drone a été trouvée près de la plage de la station, au camping Laguna, à Sables d’Or, en Bulgarie. Une équipe de la marine bulgare de Varna l’a transportée vers une base.","Aucun opérateur n’a été identifié, et le communiqué qui la signale n’a donné aucune identification définitive. Les associations avec des drones russes ou ukrainiens établies pour l’ensemble plus large des découvertes n’identifient pas cette aile. L’éventuelle charge n’a pas été précisée, et le moment de la chute du drone est inconnu. Aucune victime n’a été signalée."]},"E077":{"headline":"Une aile de drone récupérée sur la plage nord de Bourgas, en Bulgarie","description":"Le 26 août 2026, la marine a récupéré une aile de drone sur la plage nord de Bourgas, en Bulgarie ; elle avait d’abord été signalée comme un UAV. Origine non résolue.","summary":["Le 26 août 2026, un objet sur la plage nord de Bourgas, en Bulgarie, a d’abord été signalé comme un drone (UAV), puis s’est révélé être une aile de drone. Une équipe de la marine bulgare de Bourgas l’a récupérée.","Aucun opérateur n’a été identifié, et le communiqué qui la signale n’a donné aucune identification définitive. Les associations avec des drones russes ou ukrainiens établies pour l’ensemble plus large des découvertes n’identifient pas cette aile. L’éventuelle charge n’a pas été précisée, et le moment de la chute du drone est inconnu. Aucune victime n’a été signalée."]},"E078":{"headline":"Une section de queue de drone flottante récupérée au sud de Kavarna, en Bulgarie","description":"Le 27 août 2026, une équipe navale bulgare a récupéré une section de queue de drone flottante à 8 milles marins au sud de Kavarna, en Bulgarie. Son origine n’est pas résolue.","summary":["Le 27 août 2026, une équipe navale bulgare a identifié un fragment de drone flottant, la section de queue, en mer à 8 milles marins au sud de Kavarna, en Bulgarie. Il a été transporté à la base navale de Varna.","Aucun opérateur n’a été identifié, et le communiqué qui le signale n’a donné aucune identification définitive. Les associations avec des drones russes ou ukrainiens établies pour l’ensemble plus large des découvertes n’identifient pas cette section de queue. Le moment de la chute du drone et la route qu’il a suivie sont inconnus.","L’éventuelle charge n’a pas été précisée, et aucune victime n’a été signalée."]},"E079":{"headline":"Un drone sans explosifs récupéré en mer Noire à Kamchia, en Bulgarie","description":"Le 27 août 2026, un drone sans explosifs à bord a été trouvé dans les eaux de la mer Noire à Kamchia, en Bulgarie, et emmené à la base navale de Varna. Origine non résolue.","summary":["Le 27 août 2026, une équipe a inspecté un objet signalé dans les eaux de la mer Noire à Kamchia, sur la côte bulgare, et l’a identifié comme un drone (UAV). La date est celle de la découverte et de l’intervention : le moment où le drone est tombé, et la route qu’il a suivie, sont inconnus.","L’origine de ce drone n’a pas été établie, et aucun opérateur n’a été identifié. Les associations plus larges avec la Russie ou l’Ukraine établies pour cet ensemble de découvertes côtières n’identifient pas cet objet en particulier.","Aucun explosif n’était à bord et aucune victime n’a été signalée. Le drone a été transporté à la base navale de Varna. Son lien avec une aile de drone signalée le 25 août n’est pas résolu ; les deux ne sont pas présumés être le même objet."]},"E080":{"headline":"Un drone présumé aperçu au large de Chernomorets, en Bulgarie ; des débris trouvés sur la plage","description":"Le 27 août 2026, un drone présumé a été aperçu à environ 1–1,5 km au large de Chernomorets, en Bulgarie ; des débris sur la plage auraient été récupérés le 28 août. Origine non résolue.","summary":["Le 27 août 2026, un objet soupçonné d’être un drone (UAV) a été aperçu à environ 1–1,5 km au large de Chernomorets, dans la municipalité de Sozopol, sur la côte bulgare de la mer Noire. Un article du 28 août indiquait que des débris de drone avaient été récupérés sur la plage à cet endroit.","L’origine du drone n’a pas été établie et aucun opérateur n’a été identifié. Les associations plus larges avec la Russie ou l’Ukraine établies pour cet ensemble de découvertes côtières n’identifient pas cet objet en particulier. Il n’a pas non plus été prouvé que les débris de la plage provenaient de l’objet aperçu au large.","Aucune victime n’a été signalée. La marine de Bourgas est intervenue et a transporté les débris vers une base. Le moment où le drone est tombé, et la route qu’il a suivie, sont inconnus."]},"E081":{"headline":"La marine détruit un drone repéré près de l’île Sveti Ivan, à Sozopol, en Bulgarie","description":"Un drone repéré le 27 août 2026 sur la jetée nord face à l’île Sveti Ivan, à Sozopol, en Bulgarie, a été détruit sur place par la marine. Origine non résolue.","summary":["Le 27 août 2026, un drone (UAV) a été repéré sur la jetée nord face à l’île Sveti Ivan, dans la zone de Sozopol, sur la côte bulgare de la mer Noire. La marine bulgare a détruit l’objet sur place, lors d’une neutralisation contrôlée annoncée le 28 août ; l’heure exacte de la neutralisation n’a pas été précisée.","L’origine de ce drone n’a pas été établie, et aucun opérateur n’a été identifié. Les associations plus larges avec la Russie ou l’Ukraine établies pour cet ensemble de découvertes côtières n’identifient pas cet objet en particulier. Le moment où il est tombé, et la route qu’il a suivie, sont inconnus.","Le danger exact que présentait l’objet n’a pas été précisé, et aucune victime n’a été signalée. La destruction était une neutralisation contrôlée menée par les autorités, et non une explosion causée par le drone lui-même."]},"E082":{"headline":"Une équipe navale récupère un drone à 1 km au nord du phare de Shabla, en Bulgarie","description":"Le 28 août 2026, une équipe navale a trouvé un drone à environ 1 km au nord du phare de Shabla, en Bulgarie, l’a jugé sans danger et l’a emmené à Varna. Origine non résolue.","summary":["Le 28 août 2026, une équipe navale a trouvé et identifié un drone (UAV) à environ 1 km au nord du phare de Shabla, sur la côte bulgare de la mer Noire. La date est celle de la découverte et de l’intervention : le moment où le drone est tombé, et la route qu’il a suivie, sont inconnus.","L’origine de ce drone n’a pas été établie et aucun opérateur n’a été identifié. Les associations plus larges avec la Russie ou l’Ukraine établies pour cet ensemble de découvertes côtières n’identifient pas cet objet en particulier.","Le drone a été jugé sans danger et transporté à la base navale de Varna. Aucune victime n’a été signalée. Bien que Shabla soit un site de récupération distinct, il n’a pas été établi qu’il s’agisse d’un drone différent de ceux trouvés ailleurs sur la côte."]},"E083":{"headline":"La marine identifie des débris de drone sur la plage de Bungalata, à Ahtopol, en Bulgarie","description":"Le 28 août 2026, la marine bulgare a identifié des débris de drone sur la plage de Bungalata, à Ahtopol, en Bulgarie, et les a emmenés à une base. Leur origine n’a pas été établie.","summary":["Le 28 août 2026, la marine bulgare a identifié des matériaux trouvés sur la plage de Bungalata, à Ahtopol, sur la côte bulgare de la mer Noire, comme des débris d’un drone (UAV). La date est celle de la découverte et de l’intervention : le moment où le drone est tombé, et la route qu’il a suivie, sont inconnus.","L’origine des débris n’a pas été établie et aucun opérateur n’a été identifié. Les associations plus larges avec la Russie ou l’Ukraine établies pour cet ensemble de découvertes côtières n’identifient pas cet objet en particulier.","Aucune victime n’a été signalée. Une équipe de la marine de Bourgas a transporté les matériaux vers une base. Bien que la plage de Bungalata soit un site de récupération distinct, il n’a pas été établi que les débris proviennent d’un drone différent d’autres découvertes sur la côte."]},"E084":{"headline":"Une cible aérienne non identifiée au nord de l’île des Serpents déclenche une alerte près de la Roumanie","description":"Le 27 août 2026, deux F-18 espagnols ont décollé en urgence après une cible aérienne non identifiée à 33 km au nord de l’île des Serpents. Aucune entrée dans l’espace aérien roumain n’a été établie.","summary":["Le 27 août 2026, une cible aérienne a été signalée au-dessus de la mer Noire, à 33 km au nord de l’île des Serpents, près du secteur ukrainien de la mer Noire. Elle a été détectée au radar, et deux chasseurs F-18 espagnols ont décollé en urgence dans le cadre d’une réaction de l’OTAN du côté roumain. L’heure exacte n’a pas été établie.","L’identité complète de la cible comme drone (UAV) n’a pas été établie, et son origine est inconnue. Elle a été signalée en dehors de l’espace aérien roumain avéré et aucune entrée en Roumanie n’a été établie ; l’alerte ne constitue donc pas une incursion confirmée dans l’UE.","Aucun impact en Roumanie n’a été établi. L’alerte a été signalée en même temps que des informations sur un incident maritime impliquant le Progress IV, dont le mécanisme d’impact est inconnu, mais aucun lien de causalité entre les deux n’a été démontré. L’alerte n’est pas la preuve de ce qui a causé l’incident du Progress IV."]},"N004":{"headline":"Des garde-frontières lituaniens contraignent à se poser un drone de contrebande de cigarettes près de Purvėnai","description":"Dans la nuit du 27 janvier 2026, des garde-frontières ont contraint à se poser un drone cargo transportant des cigarettes près de Purvėnai, en Lituanie, dans une affaire de contrebande liée à la Biélorussie.","summary":["Dans la nuit du 27 janvier 2026, le Service d’État des garde-frontières de Lituanie (VSAT) a détecté un quadricoptère entrant en Lituanie près du village de Purvėnai, dans le district de Šalčininkai. Le communiqué officiel, publié le 28 janvier, évoquait la nuit de mardi sans préciser de quel côté de minuit le vol avait eu lieu. Après une intervention électronique antidrone, le drone a été contraint de se poser, et les garde-frontières l’ont récupéré avec, à proximité, une cargaison de 1 000 paquets de cigarettes estampillés biélorusses.","Le drone aurait approché depuis la Biélorussie, et le VSAT a attribué le vol à des contrebandiers opérant de l’autre côté de la frontière biélorusse. La nationalité des opérateurs et tout parrainage étatique n’ont pas été établis. L’affaire a été traitée comme un vol cargo criminel, et non comme une frappe militaire, et ne prouve pas une attaque d’un État étranger.","Aucune victime ni aucun dommage à des tiers n’ont été signalés. Le drone et la cargaison de cigarettes ont été saisis."]},"N005":{"headline":"Un drone de contrebande de cigarettes récupéré dans un pin près de Milvydai, en Lituanie","description":"Dans la nuit du 23 au 24 février 2026, un drone de contrebande de cigarettes a été intercepté près de Milvydai, en Lituanie, puis récupéré dans un pin près de la frontière.","summary":["Dans la nuit du 23 au 24 février 2026, des garde-frontières lituaniens ont intercepté un drone cargo près de Milvydai, dans le district de Šalčininkai, près de la frontière avec la Biélorussie. Après une intervention électronique antidrone, le drone s’est retrouvé coincé dans la cime d’un pin, à environ 0,5 km de la frontière. Il transportait 500 paquets de cigarettes. Le 24 février, du personnel forestier a aidé les garde-frontières à le récupérer, et le Service d’État des garde-frontières (VSAT) a publié l’affaire le 25 février.","Le VSAT a attribué le vol à des contrebandiers opérant de l’autre côté de la frontière biélorusse. La nationalité des opérateurs et tout parrainage étatique n’ont pas été établis, et la trajectoire complète du drone n’a pas été rendue publique. L’affaire a été traitée comme un vol cargo criminel, et non comme une frappe militaire, et ne prouve pas une attaque d’un État étranger.","Aucune victime ni aucun dommage à des tiers n’ont été signalés. Le drone et sa cargaison ont été saisis, et une procédure administrative a suivi."]},"N010":{"headline":"Un drone de contrebande de cigarettes venu de Biélorussie mis à terre près de Dubas, en Lituanie","description":"Dans la nuit du 5 avril 2026, des garde-frontières lituaniens ont mis à terre un drone transportant des cigarettes de contrebande depuis la Biélorussie, près de Dubas, dans le district de Varėna.","summary":["Dans la nuit du 5 avril 2026, peut-être jusqu’au 6 avril, des garde-frontières lituaniens ont utilisé une surveillance thermique pour détecter un drone entrant près du village de Dubas, dans le district de Varėna. Une action antidrone l’a fait tomber dans une zone boisée voisine. Le drone transportait 1 000 paquets de cigarettes NZ Gold.","Le drone aurait approché depuis la Biélorussie, et le Service d’État des garde-frontières (VSAT) a attribué le vol à des contrebandiers opérant de l’autre côté de la frontière biélorusse. La nationalité des opérateurs et tout parrainage étatique n’ont pas été établis. Il s’agissait d’un vol cargo criminel, et non d’une frappe militaire, et cela ne prouve pas une attaque d’un État étranger.","Aucune victime ni aucun dommage à des tiers n’ont été signalés. Le drone et sa cargaison ont été saisis et une procédure administrative a suivi. Le VSAT a publié l’affaire le 7 avril 2026."]},"N011":{"headline":"Un drone de contrebande s’écrase près de Krupaviesai, en Lituanie, après interception","description":"Avant l’aube du 7 mai 2026, un drone cargo transportant des cigarettes s’est écrasé dans un champ près de Krupaviesai, en Lituanie, après une action antidrone des garde-frontières.","summary":["Avant l’aube du 7 mai 2026, des garde-frontières lituaniens ont employé des mesures antidrones contre un drone cargo chargé près de Krupaviesai, dans le district de Šalčininkai. L’intervention a fait tomber le drone dans un champ, et il s’est brisé. Il transportait 850 paquets de cigarettes Minsk Capital QS.","Le drone aurait approché depuis la Biélorussie, et le Service d’État des garde-frontières (VSAT) a attribué le vol à des contrebandiers opérant de l’autre côté de la frontière biélorusse. La nationalité des opérateurs et tout parrainage étatique n’ont pas été établis. Le vol était une opération cargo criminelle, et non une frappe militaire, et ne prouve pas une attaque d’un État étranger.","Aucune victime ni aucun dommage à des tiers n’ont été signalés. Le drone brisé et sa cargaison ont été saisis. Le VSAT, qui a publié l’affaire le 8 mai, l’a décrite comme la 17e interception de ce type de l’année."]},"N012":{"headline":"Des garde-frontières contraignent à se poser un drone chargé de cigarettes à Šalčininkai, en Lituanie","description":"Le 14 juin 2026, des garde-frontières lituaniens ont contraint à se poser un drone de contrebande de cigarettes signalé comme venant de Biélorussie, dans le district de Šalčininkai, en Lituanie.","summary":["Le dimanche 14 juin 2026, des garde-frontières lituaniens ont détecté un drone cargo artisanal approchant près de Daugidonys, dans le district de Šalčininkai, à la frontière biélorusse, et ont utilisé un équipement antidrone contre lui. Le drone est tombé et a été récupéré dans des champs à Dimitrai. Il transportait 200 paquets de cigarettes NZ Gold. L’incident a été signalé le lundi 15 juin.","Selon le service lituanien des garde-frontières (VSAT), le drone était piloté par des contrebandiers opérant depuis la frontière biélorusse ou de l’autre côté de celle-ci. La nationalité de l’opérateur n’a pas été établie, ni aucun parrainage étatique ; le récit officiel décrit une opération cargo criminelle, et non une frappe militaire, et ne prouve pas une attaque d’un État étranger.","Aucune victime ni aucun dommage à des tiers n’ont été signalés. Le drone a été mis à terre par des moyens électroniques, récupéré et saisi, et une procédure administrative a suivi. Il n’est pas classé comme un abattage ni comme un écrasement confirmé."]},"N015":{"headline":"L’Allemagne arrête un Moldave soupçonné d’espionnage par drone à Munich","description":"Le 15 juillet 2026, un homme a été arrêté à Munich, en Allemagne, après qu’un drone a filmé le site d’un fabricant de défense. Les enquêteurs allèguent de l’espionnage ; aucun État n’est nommé.","summary":["Dans la soirée du mercredi 15 juillet 2026, des habitants de Munich, en Allemagne, ont alerté la police au sujet d’un drone filmant les locaux d’un fabricant d’armes. Une source sécuritaire de Reuters a nommé l’entreprise : KNDS. Un suspect moldave de 37 ans a été arrêté près du site, et un mandat d’arrêt et un placement en détention provisoire ont été annoncés le vendredi 17 juillet.","Les enquêteurs ont allégué qu’il recueillait des renseignements pour une entité étrangère ou une organisation interdite, mais aucun État commanditaire n’a été nommé. Le drone aurait été lancé localement ; aucun vol transfrontalier n’est allégué. La seule nationalité du suspect ne prouve pas qu’il était dirigé par un État étranger, et l’affaire relève d’une allégation, non d’une condamnation.","Le modèle du drone n’a pas été précisé, et aucune charge ni aucun dommage n’ont été signalés."]},"N023":{"headline":"Selon des informations grecques, des F-16 ont intercepté un UAV turc entre Samothrace et Lemnos","description":"Le 28 août 2026, des informations grecques ont indiqué que des F-16 avaient intercepté un UAV militaire turc entre Samothrace et Lemnos, en Grèce. L’attribution repose sur le récit grec.","summary":["Dans la matinée du 28 août 2026, un drone (UAV) a été signalé volant dans le nord de la mer Égée, entre Samothrace et Lemnos et près de la zone de l’aéroport d’Alexandroupoli. Selon les informations grecques, deux chasseurs F-16 grecs l’ont identifié ou intercepté. Aucun tir ni abattage n’a été signalé, et la trajectoire exacte n’a pas été publiée.","Les informations grecques ont décrit l’UAV comme un drone militaire turc et le vol comme une violation de l’espace aérien. Ces deux qualifications proviennent du récit grec ; elles n’ont pas été tranchées de manière indépendante, et aucune attribution criminalistique indépendante n’a été revendiquée. Le modèle et le nombre exact de franchissements n’ont pas été précisés.","Le récit grec relie la rencontre à une précaution prise par un vol de passagers d’Aegean près de l’aéroport d’Alexandroupoli, qui aurait suivi une trajectoire alternative ou pris une précaution de basse altitude avant de poursuivre vers Athènes. Aucune collision ni victime n’a été signalée. La précaution aéroportuaire est traitée comme faisant partie de la même rencontre, et non comme un incident distinct."]},"N028":{"headline":"La marine détruit un drone flottant en mer au large du récif de Pomorie, en Bulgarie","description":"Le 2 septembre 2026, la marine bulgare a détruit un drone flottant à environ 9 milles marins au large du pont de Bourgas et du récif de Pomorie. Son opérateur est inconnu.","summary":["Le 2 septembre 2026, un drone flottant (UAV) a été trouvé à environ 9 milles marins en face du pont de Bourgas et du récif de Pomorie, dans des eaux signalées comme côtières ou territoriales bulgares. Des personnels de la marine l’ont identifié et l’ont détruit en mer. L’opération a été annoncée le 3 septembre.","Aucun opérateur ni aucune origine nationale n’ont été annoncés pour cet objet, et son modèle n’a pas été précisé. Le moment où il a volé ou est tombé, et la question de savoir s’il est lié à d’autres drones récupérés le long de la côte, ne sont pas résolus. Aucune charge n’a été signalée, et aucune ne peut être déduite de la manière dont il a été détruit.","Le site était l’un des trois lieux d’intervention en mer gérés depuis la base de Bourgas de la marine dans une annonce officielle couvrant six missions de la marine. Il est distinct d’une découverte antérieure à Pomorie le 26 août."]},"N029":{"headline":"Un drone de reconnaissance trouvé sur le rivage du cap Kaliakra, en Bulgarie","description":"Le 2 septembre 2026, des personnels de la marine bulgare ont identifié comme un drone de reconnaissance un objet trouvé sur le rivage du cap Kaliakra. Son opérateur et son origine ne sont pas résolus.","summary":["Le 2 septembre 2026, des personnels de la marine ont identifié comme un drone de reconnaissance (UAV) un objet trouvé sur le rivage du cap Kaliakra, sur la côte bulgare de la mer Noire. La découverte a été annoncée le 3 septembre.","Le modèle, l’opérateur et le fabricant du drone n’ont pas été annoncés, et son origine n’est pas résolue. Le moment où il a volé ou est tombé, et la question de savoir s’il est lié à d’autres drones récupérés le long de la côte, ne sont pas connus. Aucune charge n’a été signalée.","Le drone a été transporté à la base navale de Varna. Cette récupération sur le rivage est distincte d’une opération en mer du 6 septembre."]},"N030":{"headline":"La marine détruit un drone flottant en mer au large du cap Kolokita, en Bulgarie","description":"Le 2 septembre 2026, la marine bulgare a identifié un drone flottant dans les eaux au large du cap Kolokita, en Bulgarie, et l’a détruit en mer. Son opérateur est inconnu.","summary":["Le 2 septembre 2026, un drone (UAV) a été trouvé flottant dans les eaux au large du cap Kolokita, signalées comme eaux côtières ou territoriales bulgares. La marine l’a identifié et l’a détruit en mer. L’intervention a été annoncée le 3 septembre.","Aucun opérateur ni aucune origine nationale n’ont été annoncés, et le modèle n’a pas été précisé. La date du vol ou de la chute du drone est inconnue, tout comme tout lien avec d’autres appareils récupérés sur la côte bulgare. Aucune charge n’a été signalée, et la méthode de destruction n’en est pas la preuve.","Le cap Kolokita a été identifié comme un lieu distinct dans le même communiqué officiel, qui décrivait six missions de la marine ; il était l’un des trois lieux d’intervention en mer gérés depuis la base de Bourgas de la marine."]},"N031":{"headline":"La marine détruit en mer des débris de drone flottants au large de Maslen Nos, en Bulgarie","description":"Le 2 septembre 2026, la marine bulgare a identifié des matériaux de drone flottants dans les eaux au large de Maslen Nos, en Bulgarie, et les a détruits en mer. Leur opérateur est inconnu.","summary":["Le 2 septembre 2026, des matériaux flottant dans les eaux au large de Maslen Nos, signalées comme eaux côtières ou territoriales bulgares, ont été identifiés par la marine comme provenant d’un drone (UAV). Des personnels de la marine ont détruit les matériaux en mer. L’opération a été annoncée le 3 septembre.","Aucun opérateur ni aucune origine nationale n’ont été annoncés, et le modèle du drone n’a pas été précisé. On ignore quand le drone a volé ou est tombé, ou si les matériaux sont liés à d’autres drones récupérés le long de la côte. Aucune charge n’a été signalée, et aucune ne doit être déduite de la méthode de neutralisation.","Maslen Nos figurait comme un lieu distinct dans une annonce officielle de six missions de la marine, comme l’un des trois sites en mer gérés depuis la base de Bourgas de la marine."]},"N032":{"headline":"Des fragments de drone militaire trouvés sur la plage de la ville de Pomorie, en Bulgarie","description":"Le 2 septembre 2026, des personnels de la marine de Bourgas sont intervenus pour des fragments de drone militaire non identifié sur la plage de la ville de Pomorie, en Bulgarie. Opérateur inconnu.","summary":["Le 2 septembre 2026, des personnels de la marine de Bourgas sont intervenus pour des fragments de drone militaire trouvés sur la plage de la ville de Pomorie, sur la côte bulgare de la mer Noire. La découverte a été annoncée le 3 septembre.","Les fragments ont été officiellement signalés comme des débris de drone militaire, mais le drone n’a pas été identifié : son opérateur est inconnu, et le nombre d’aéronefs concernés n’est pas connu. Le moment où l’aéronef a volé ou est tombé, et la question de savoir si les fragments sont liés à d’autres drones récupérés le long de la côte, ne sont pas résolus. Aucune charge n’a été signalée.","Un examen naval a été signalé, mais la méthode finale de traitement des fragments n’a pas été précisée. Cette découverte sur la plage est distincte d’une découverte en mer du 26 août."]},"N033":{"headline":"Un objet conique sur la plage de Topola, en Bulgarie, non confirmé comme un drone","description":"Le 2 septembre 2026, un objet de forme conique trouvé sur la plage de Topola, à Dobrich, en Bulgarie, a été emmené à la base navale de Varna. Il n’a pas été confirmé comme un drone.","summary":["Le 2 septembre 2026, un objet suspect de forme conique a été trouvé sur la plage de Topola, à Dobrich, en Bulgarie. Il a été inclus dans une annonce officielle de six missions de la marine, publiée le 3 septembre, et a été emmené à la base navale de Varna.","L’identité de l’objet n’a pas été établie, et il n’a pas été confirmé comme un drone (UAV) ; sa forme seule ne montre pas qu’il en soit un. Son origine est inconnue, et une origine étrangère n’a pas été démontrée. Aucune route ni aucune charge n’ont été signalées.","La découverte de Topola est distincte d’une découverte antérieure enregistrée à Tyulenovo le 14 août."]},"N035":{"headline":"La marine récupère un drone trouvé à flot au large du cap Kaliakra, en Bulgarie","description":"En fin d’après-midi du 6 septembre 2026, la marine a récupéré un drone flottant à environ 650 m au nord-est du cap Kaliakra, en Bulgarie. Son origine n’a pas été annoncée.","summary":["En fin d’après-midi du 6 septembre 2026, une équipe de la marine de Varna a récupéré un drone flottant (UAV) dans les eaux côtières à environ 3,5 encablures, soit 650 m, au nord-est du cap Kaliakra, sur la côte bulgare de la mer Noire. L’équipe a été mobilisée à la demande du ministère de l’Intérieur. L’opération a été signalée le 7 septembre.","Le type, l’origine et l’opérateur du drone n’ont pas été annoncés. Le moment où il a volé ou est tombé, et la question de savoir s’il est lié à d’autres drones récupérés le long de la côte, ne sont pas résolus.","Le drone a été jugé sûr à récupérer, bien qu’aucune information détaillée sur la charge n’ait été publiée, et il a été emmené à la base navale."]},"N036":{"headline":"Des garde-frontières lituaniens saisissent un drone de contrebande de cigarettes à Daugidonys","description":"Le 6 septembre 2026, des garde-frontières ont intercepté à Daugidonys, Šalčininkai, un drone artisanal transportant des cigarettes vers la Lituanie ; le VSAT a dit qu’il venait de Biélorussie.","summary":["Juste après minuit le 6 septembre 2026, dans la nuit du 5 au 6 septembre, des garde-frontières lituaniens (VSAT) ont intercepté un drone cargo artisanal (UAV) à Daugidonys, dans le district de Šalčininkai, à la frontière de la Lituanie. Le drone transportait 1 000 paquets de cigarettes. Le VSAT a signalé l’opération le 7 septembre.","Selon le VSAT, le drone était piloté par des contrebandiers opérant de l’autre côté de la frontière, depuis la Biélorussie. La nationalité des opérateurs et tout parrainage étatique n’ont pas été établis. Il s’agissait d’un vol cargo criminel, et non d’une frappe militaire, et le récit officiel relève du contrôle aux frontières et ne prouve pas une attaque d’un État étranger.","Les garde-frontières ont arrêté le drone par des moyens électroniques, l’obligeant à descendre ; cela n’est pas classé comme un abattage ni comme un écrasement confirmé. Le drone et sa cargaison ont été saisis, et aucune victime ni aucun dommage à des tiers n’ont été signalés. Le VSAT l’a décrit comme le 55e cas de ce type de l’année. Il est distinct d’un incident antérieur enregistré à Daugidonys."]},"N038":{"headline":"Des fragments de drone trouvés sur la plage de Capu Midia, en Roumanie, neutralisés par la marine","description":"Des fragments de drone signalés sur la plage de Capu Midia, en Roumanie, dans la soirée du 9 septembre 2026, ont été neutralisés par l’EOD de la marine le lendemain matin. Origine non résolue.","summary":["Vers 20:00 le 9 septembre 2026, des fragments de drone aérien ont été signalés sur la plage de Capu Midia, dans le département de Constanța, sur la côte roumaine de la mer Noire. La zone a été isolée pendant la nuit, et une équipe de neutralisation d’engins explosifs (EOD) de la marine est intervenue vers 09:30 le 10 septembre et a neutralisé les matériaux. Les deux dates sont des étapes d’un même incident.","Le ministère de la Défense (MApN) a indiqué que les fragments ne portaient aucune charge explosive. Aucun opérateur ni aucune origine nationale n’ont été confirmés, le nombre de drones dont proviennent les fragments n’a pas été précisé, et le vol d’origine est inconnu.","La neutralisation était une neutralisation contrôlée menée par les autorités, et non une explosion survenue pendant l’incident. Des découvertes distinctes signalées à la police à Mamaia Nord et à Corbu le 10 septembre sont différentes de celle-ci."]},"N040":{"headline":"Des touristes trouvent un drone de type militaire endommagé sur la plage de Kavatsi, en Bulgarie","description":"Le 11 septembre 2026, des touristes ont trouvé un drone de type militaire endommagé sur la plage de Kavatsi, près de Sozopol, en Bulgarie. Son opérateur et son origine nationale ne sont pas confirmés.","summary":["Le 11 septembre 2026, des touristes ont trouvé un drone échoué sur la plage touristique de Kavatsi, près de Sozopol, sur la côte bulgare de la mer Noire. Le corps du drone était endommagé et son modèle n’a pas été précisé. Des spécialistes ont été appelés et la zone a été sécurisée.","Les articles ont décrit le drone comme d’aspect militaire, mais il ne s’agit pas d’une attribution confirmée à une nation ou à un opérateur, et aucune évaluation finale n’a été signalée. Le moment où il a volé ou est tombé, et la question de savoir s’il est lié à d’autres drones récupérés le long de la côte, ne sont pas résolus.","Le sort final du drone n’a pas été établi dans l’article disponible. La découverte de Kavatsi est distincte d’une découverte de fin août sur la jetée de Sveti Ivan, dans la zone de Sozopol."]},"N042":{"headline":"Des débris de drone aérien récupérés à 46 milles marins à l’est de Midia, en Roumanie","description":"Le 11 septembre 2026, deux fragments de drone ont été récupérés à environ 46 milles marins à l’est de Midia, en dehors de la mer territoriale roumaine. Origine inconnue.","summary":["Le 11 septembre 2026, un navire marchand a signalé deux fragments de drone aérien en mer Noire, à environ 46 milles marins à l’est de Midia, en Roumanie. Un patrouilleur des garde-côtes a récupéré les deux. La chronologie des interventions du ministère de la Défense indique 16:00 comme heure.","La zone est située au large et en dehors de la mer territoriale roumaine, dans une zone liée à la ZEE ; la découverte n’est donc pas une incursion sur le territoire souverain roumain. Les débris provenaient d’un drone aérien, et non d’un drone maritime. Aucun opérateur ni aucune attribution nationale n’ont été annoncés, et la date du vol ou de l’écrasement est inconnue.","Aucun danger pyrotechnique n’a été identifié. La récupération est distincte des découvertes sur les plages de la côte roumaine signalées le même jour et des cas antérieurs d’août liés à Neptun Deep."]},"N043":{"headline":"Deux fragments de drone sans explosifs trouvés à Câșla Vădanei, en Roumanie","description":"Le 11 septembre 2026, des experts en déminage ont examiné deux fragments de drone sur la plage de Câșla Vădanei, à Tulcea, en Roumanie, sans y trouver d’explosifs. Origine inconnue.","summary":["Le 11 septembre 2026, deux fragments de drone aérien ont été trouvés échoués sur la plage de Câșla Vădanei, entre Sulina et Sfântu Gheorghe, à Tulcea, en Roumanie. Une équipe de neutralisation d’engins explosifs (EOD) du ministère de la Défense (MApN) les a examinés à 13:30, ce qui correspond à l’heure d’intervention et non à une heure d’écrasement connue, et n’a trouvé aucune charge explosive.","Le compte rendu du ministère ne donne aucun opérateur ni aucune attribution nationale, et l’origine des fragments est inconnue. On ignore de combien d’aéronefs ils proviennent, et la date du vol ou de l’écrasement n’est pas résolue."]},"N044":{"headline":"Des restes de quatre drones trouvés et neutralisés à Edighiol–Periboina, en Roumanie","description":"Le 11 septembre 2026, une équipe EOD a trouvé des restes de quatre drones, dont un intercepteur chargé d’explosifs, à Edighiol–Periboina, en Roumanie. Origines inconnues.","summary":["Le 11 septembre 2026, en vérifiant un signalement des garde-côtes, une équipe héliportée de neutralisation d’engins explosifs (EOD) a observé plusieurs épaves de drones dans le secteur côtier d’Edighiol–Periboina, dans le département de Constanța, en Roumanie. Les restes appartenaient à quatre drones aériens, dont un drone intercepteur. La chronologie du ministère de la Défense (MApN) indique l’intervention à 17:55.","La chronologie citée ne donne aucun opérateur ni aucune attribution nationale pour aucun des drones. Le moment où ils ont volé ou sont tombés, et la question de savoir s’ils sont liés à d’autres drones récupérés le long de la côte, ne sont pas résolus.","Des explosifs ont été signalés spécifiquement à bord du drone intercepteur. Tous les éléments ont été sécurisés et neutralisés lors d’une neutralisation contrôlée par les autorités, ce qui est distinct d’une explosion pendant l’incident."]},"N045":{"headline":"Un fragment de drone avec explosifs neutralisé sur la plage de Periteașca, en Roumanie","description":"Le 11 septembre 2026, la Police des frontières a trouvé deux fragments de drone sur la plage de Periteașca, à Tulcea, en Roumanie ; l’un contenait des explosifs et a été neutralisé. Origine inconnue.","summary":["Vers 09:30 le 11 septembre 2026, la Police des frontières a trouvé deux fragments de drone sur la plage de Periteașca, à Tulcea, en Roumanie. L’intervention pour les traiter est indiquée à 15:18. La date du vol ou de l’écrasement est inconnue.","Aucun opérateur ni aucune attribution nationale n’ont été annoncés, et l’origine des fragments est inconnue. On ignore de combien de drones ils proviennent, et tout lien avec d’autres drones récupérés le long de la côte n’est pas résolu.","Des explosifs ont été confirmés dans l’un des fragments, et des artificiers du SRI l’ont neutralisé lors d’une neutralisation contrôlée ; les garde-côtes ont pris l’autre fragment. La découverte est distincte d’un cas antérieur à Gura Portiței le 23 août."]},"N049":{"headline":"Un drone de contrebande s’écrase près de Versekėlė, en Lituanie, après interception","description":"Tard le 13 septembre 2026, un drone de contrebande de cigarettes venu de Biélorussie s’est écrasé près de Versekėlė, en Lituanie, après une action antidrone, ont indiqué les garde-frontières.","summary":["Tard dans la soirée du 13 septembre 2026, des garde-frontières lituaniens ont détecté un drone cargo entrant près d’Ūta, dans le district de Šalčininkai, à la frontière avec la Biélorussie. Une action antidrone l’a perturbé ; le drone a fait demi-tour vers la frontière et s’est écrasé dans une prairie à environ 500 mètres à l’intérieur de la Lituanie, près de Versekėlė. Il transportait 200 paquets de cigarettes Minsk Superslims et un dispositif GPS.","Selon le service des garde-frontières VSAT, qui a signalé l’affaire le 14 septembre, le drone était piloté par des contrebandiers opérant depuis la frontière biélorusse ou de l’autre côté de celle-ci. La nationalité des opérateurs et tout parrainage étatique n’ont pas été établis. Il s’agissait d’un vol cargo criminel, et non d’une attaque militaire.","Les garde-frontières ont récupéré le drone artisanal brisé en une heure environ et ont ouvert une procédure administrative. Aucune victime ni aucun dommage à des tiers n’ont été signalés."]},"N052":{"headline":"Un vieux drone trouvé dans une forêt à Keneliai, dans le district de Pasvalys, en Lituanie","description":"Le 16 septembre 2026, un vieux drone a été signalé dans une forêt à Keneliai, dans le district de Pasvalys, en Lituanie. La police n’a trouvé aucun explosif ; une origine étrangère n’est pas prouvée.","summary":["Le 16 septembre 2026, un drone qui semblait être resté dans la végétation pendant des mois a été trouvé dans une forêt du village de Keneliai, dans le district lituanien de Pasvalys, et signalé à la police. La date est celle de la découverte et du signalement, et non la preuve d’un vol ce jour-là.","Les premières spéculations selon lesquelles il s’agissait d’un drone militaire étranger n’ont pas été confirmées par le compte rendu ultérieur de la police. Le drone n’a pas été identifié comme un drone de frappe russe ou ukrainien, et la police l’a ensuite associé à une enquête sur de la contrebande. Son origine étrangère n’a pas été établie publiquement, et la manière dont il a atteint la forêt n’est pas connue.","L’ARAS et l’armée sont intervenus face au risque explosif possible. Dans une mise à jour du 17 septembre, la police a indiqué qu’aucun explosif n’avait été trouvé."]},"N053":{"headline":"Un drone de contrebande contraint à se poser et saisi à Norviliškės, en Lituanie","description":"Peu après minuit le 16 septembre 2026, des garde-frontières ont contraint à se poser un drone de contrebande de cigarettes venu de Biélorussie à Norviliškės, en Lituanie, et ont saisi sa cargaison.","summary":["Peu après minuit le 16 septembre 2026, dans la nuit de mardi à mercredi, l’imagerie thermique a repéré un drone transportant une cargaison rectangulaire alors qu’il entrait en Lituanie depuis la Biélorussie près de Norviliškės, dans le district de Šalčininkai. Une action antidrone l’a contraint à se poser, et les garde-frontières ont saisi le drone avec 1 000 paquets de cigarettes NZ Gold.","Selon le service des garde-frontières VSAT, le drone était piloté par des contrebandiers opérant depuis la frontière biélorusse ou de l’autre côté de celle-ci ; la nationalité des opérateurs et tout parrainage étatique n’ont pas été établis. Il s’agissait d’un vol cargo criminel, et non d’une frappe militaire, et il a été mis à terre par des mesures électroniques antidrones plutôt qu’abattu.","Aucune victime ni aucun dommage à des tiers n’ont été signalés. Une procédure administrative a été ouverte, et le VSAT a compté l’affaire comme la 57e de l’année."]},"N055":{"headline":"La Grèce signale le survol de l’îlot de Zourafa, en mer Égée, par un UAV turc","description":"Le 18 septembre 2026, l’armée grecque a dit qu’un UAV turc avait survolé l’îlot de Zourafa, dans le nord-est de la mer Égée. La trajectoire n’a pas été vérifiée de manière indépendante.","summary":["Le 18 septembre 2026, un UAV a survolé Zourafa, un îlot du nord-est de la mer Égée, selon un compte rendu de l’armée grecque relayé le jour même par le média grec Politica. L’heure exacte et l’itinéraire complet n’ont pas été publiés, et le modèle du drone n’a pas été précisé.","Le compte rendu grec a identifié le drone comme turc et présenté le survol comme une violation de l’espace aérien ; la trajectoire n’a pas été vérifiée de manière indépendante. Le même compte rendu faisait état d’une formation de F-16 pilotés au-dessus de Ro, ce qui n’est pas un incident de drone. Pour l’ensemble de la journée, il recensait cinq UAV parmi dix aéronefs, avec 13 infractions à la région d’information de vol (FIR) et sept violations de l’espace aérien par des aéronefs de types divers ; le nombre de drones concernés n’a pas été précisé.","Aucun impact ni aucune victime n’ont été signalés, et le compte rendu n’a pas décrit de réaction précise au survol de Zourafa."]},"N059":{"headline":"Un drone de contrebande intercepté brûle près d’Antaniškės, en Lituanie","description":"Dans la nuit du 21 au 22 septembre 2026, un drone de contrebande venu de Biélorussie a brûlé près d’Antaniškės, en Lituanie, après une action antidrone ; sa cargaison de cigarettes a survécu.","summary":["Dans la nuit du 21 au 22 septembre 2026, des garde-frontières lituaniens ont détecté un drone cargo entrant à Liškūniškės, dans le district de Šalčininkai, près de la frontière biélorusse. Il est descendu après une action antidrone, et le matin du 22 septembre, les garde-frontières ont trouvé le drone endommagé et brûlé à environ 800 mètres de la frontière, près d’Antaniškės. Le VSAT a signalé l’affaire le 23 septembre.","Selon le service des garde-frontières VSAT, le drone était piloté par des contrebandiers opérant depuis la frontière biélorusse ou de l’autre côté de celle-ci. La nationalité des opérateurs et tout parrainage étatique n’ont pas été établis. Il s’agissait d’un vol cargo criminel, et non d’une frappe militaire.","Le drone a été endommagé par son impact et par le feu, mais sa cargaison de 1 000 paquets de cigarettes Minsk Superslims a survécu. Le drone et les cigarettes ont été saisis et une procédure administrative a été ouverte ; le VSAT l’a compté comme le 58e cas de ce type de l’année. Aucune victime parmi des tiers n’a été signalée."]},"N062":{"headline":"Des fragments de drone d’origine inconnue signalés sur la plage de Mamaia Nord, en Roumanie","description":"La police a été avisée vers 08:30 le 10 septembre 2026 de fragments de drone sur la plage de Mamaia Nord, dans le département de Constanța, en Roumanie. Aucun explosif ; origine inconnue.","summary":["Vers 08:30, heure locale, le 10 septembre 2026, la police a reçu un signalement concernant des fragments de drone sur la plage de Mamaia Nord, dans le département de Constanța, sur la côte roumaine de la mer Noire. L’heure est celle à laquelle la police a été avisée, et non une heure d’écrasement vérifiée.","L’opérateur et l’origine n’ont pas été établis dans les comptes rendus cités, et le nombre d’aéronefs dont proviennent les fragments n’a pas été précisé. La récupération ne montre pas qu’un drone soit entré dans l’espace aérien roumain ce jour-là ; l’itinéraire d’origine est inconnu.","Après examen, aucune matière explosive n’a été signalée. Les fragments ont été remis aux garde-côtes ou à d’autres autorités compétentes. La découverte de Mamaia Nord est distincte de celle de Capu Midia la veille au soir et d’un signalement à la police sur la plage de Corbu vers 09:40 le même matin."]},"N063":{"headline":"Des fragments de drone d’origine inconnue signalés sur la plage de Corbu, en Roumanie","description":"La police a été avisée vers 09:40 le 10 septembre 2026 de fragments de drone sur la plage de Corbu, dans le département de Constanța, en Roumanie. Aucun explosif ; origine inconnue.","summary":["La police a été avisée vers 09:40, heure locale, le 10 septembre 2026 de fragments de drone sur la plage de Corbu, dans le département de Constanța, sur la côte roumaine de la mer Noire. Il s’agit de l’heure du signalement, et non d’une heure d’écrasement vérifiée.","Les comptes rendus cités n’établissent ni opérateur ni origine, et on ignore de combien d’aéronefs proviennent les fragments. La découverte de fragments ne prouve pas une incursion le même jour dans l’espace aérien roumain, et l’itinéraire est inconnu.","Aucune matière explosive n’a été signalée après l’examen des fragments, et ils ont été remis aux garde-côtes ou à d’autres autorités compétentes. Le signalement de Corbu est distinct du signalement de 08:30 concernant des fragments à Mamaia Nord ce matin-là et de la découverte de Capu Midia la veille au soir."]},"N064":{"headline":"Un fragment de drone présumé d’origine inconnue trouvé à Agigea, en Roumanie","description":"Le 26 septembre 2026, des pêcheurs ont trouvé un fragment de drone présumé parmi les blocs côtiers d’Agigea, dans le département de Constanța, en Roumanie. Son origine n’est pas résolue.","summary":["Dans la matinée du 26 septembre 2026, des pêcheurs ont trouvé un fragment de drone présumé parmi les blocs côtiers d’Agigea, dans le département de Constanța, en Roumanie, et ont prévenu les autorités. Antena 3 CNN a décrit un objet pâle, en forme d’aile, pouvant faire partie d’un drone aérien. La date est celle de la découverte ; le moment et la manière dont l’objet a atteint le rivage sont inconnus.","Radio România a fait état d’une enquête en cours. On n’a pas établi si l’objet est un drone, ni son modèle, son origine, son opérateur et le moment où il a été perdu. La découverte seule ne montre pas qu’un drone ait franchi la frontière roumaine, et elle n’a été liée à aucune incursion suivie.","Les premières informations ne montraient aucune charge explosive attachée, mais aucune évaluation pyrotechnique officielle finale n’avait été publiée. Aucune victime, aucun dommage ni aucune détonation n’ont été signalés, et les articles n’établissent pas que le fragment ait été physiquement récupéré."]},"N065":{"headline":"Un drone signalé pénètre dans l’espace aérien roumain près de Chilia Veche, à Tulcea","description":"Dans la nuit du 26 au 27 septembre 2026, un radar a suivi une cible aérienne, signalée comme un drone, entrant en Roumanie près de Chilia Veche, à Tulcea. Son opérateur est inconnu.","summary":["Dans la nuit du 26 au 27 septembre 2026, le ministère roumain de la Défense a signalé qu’une cible aérienne était entrée dans l’espace aérien national près de Chilia Veche, dans le département de Tulcea. Un radar l’a suivie pendant plusieurs minutes, à peu près parallèlement au bras de Chilia du Danube, avant que le contact ne soit perdu près de Pardina. L’heure exacte à laquelle elle a franchi la frontière n’a pas été indiquée.","Le ministère l’a qualifiée de cible aérienne ; Digi24 l’a signalée comme un drone, et son modèle n’a pas été établi. Un radar militaire a confirmé une entrée transfrontalière, mais l’opérateur et la nationalité ne sont pas résolus, et le communiqué du ministère ne l’a pas attribuée à la Russie. La perte du contact radar ne montre pas où la cible est allée, et aucun écrasement, abattage, explosion ni récupération n’a été confirmé.","Deux F-18 espagnols assurant la police du ciel renforcée de l’OTAN et un hélicoptère roumain IAR-330 SOCAT ont décollé pour la surveiller. Une alerte RO-Alert a été émise pour le nord du département de Tulcea à 23:32, et l’alerte a pris fin à 00:48 le 27 septembre. Le communiqué ne donnait aucune évaluation des victimes ou des dégâts."]},"N066":{"headline":"Une cible aérienne non identifiée pénètre en Roumanie près de Ceatalchioi, à Tulcea","description":"Dans la soirée du 27 septembre 2026, un radar a suivi une cible aérienne non identifiée, peut-être un drone, de Ceatalchioi à Somova, en Roumanie. Son opérateur est inconnu.","summary":["Dans la soirée du 27 septembre 2026, le ministère roumain de la Défense a signalé qu’une cible aérienne non identifiée était entrée dans l’espace aérien roumain près de Ceatalchioi, dans le département de Tulcea. Un radar l’a d’abord suivie au-dessus de l’Ukraine, au nord de Chilia Veche ; elle a ensuite longé la frontière et a disparu du radar environ 10 minutes plus tard près de Somova. L’heure exacte d’entrée n’a pas été donnée.","Le radar a confirmé l’entrée transfrontalière, mais l’opérateur et la nationalité de l’objet ne sont pas résolus. Il a été décrit comme un drone probable, mais cela n’a pas été confirmé, et son type est inconnu. La perte du contact radar n’établit pas un écrasement, et aucun abattage, explosion ni récupération de débris n’a été signalé.","Deux F-16 roumains ont décollé de Borcea. Une alerte RO-Alert a été émise à 20:35 et l’alerte aérienne a pris fin à 22:05. Une recherche par des spécialistes a été annoncée pour la matinée du 28 septembre ; son résultat n’a pas été établi. L’incursion est survenue le soir après qu’une cible aérienne distincte avait été suivie entre Chilia Veche et Pardina."]},"N067":{"headline":"Des débris de drone possible trouvés sur Insula Mare a Brăilei, en Roumanie","description":"Le 29 septembre 2026, des fragments d’un drone possible ont été trouvés sur Insula Mare a Brăilei, en Roumanie, après une chute et un incendie signalés. L’origine étrangère n’est pas confirmée.","summary":["Dans la nuit du 28 au 29 septembre 2026, un habitant a appelé le 112 pour signaler la chute d’un objet et un incendie sur des terres arables d’Insula Mare a Brăilei, en face de Gropeni, dans le département de Brăila, en Roumanie. Les autorités ont trouvé des fragments, et la découverte a été signalée dans la matinée du 29 septembre ; l’incendie s’était éteint. L’heure exacte de la chute est inconnue.","Le ministère roumain de la Défense a décrit les fragments comme ceux d’un drone possible ; l’identification et le modèle étaient en attente d’examen. L’origine étrangère, l’opérateur et la nationalité ne sont pas résolus, et le ministère n’a signalé aucune entrée non autorisée détectée par radar dans l’espace aérien roumain pendant la nuit précédente. La chute et l’incendie signalés n’établissent pas un écrasement ou une explosion de drone confirmé.","Aucune victime ni aucun dégât matériel n’ont été signalés. Des équipes du ministère de l’Intérieur et du Service roumain de renseignement ont sécurisé le périmètre, et le ministère de la Défense a dit qu’une équipe de spécialistes examinerait la zone ; un examen achevé ou une récupération n’avaient pas été signalés."]},"N068":{"headline":"La Grèce signale deux violations de l’espace aérien par un UAV turc en mer Égée","description":"Le 1er octobre 2026, l’armée grecque a signalé qu’un UAV turc avait commis deux violations de l’espace aérien et une infraction à la FIR d’Athènes dans le sud-est de la mer Égée.","summary":["Le 1er octobre 2026, l’État-major général de la défense nationale hellénique a signalé qu’un UAV turc avait commis deux violations de l’espace aérien national et une infraction aux règles de la circulation aérienne dans la région d’information de vol (FIR) d’Athènes, au-dessus du sud-est de la mer Égée. OnAlert a relayé le compte rendu le soir même, suivi par NewsIT. Aucune île, coordonnée, heure ni trajectoire de vol n’ont été publiées.","L’identification comme turc et l’évaluation de la violation sont celles de l’armée grecque, et la trajectoire de vol n’a pas été vérifiée de manière indépendante. Le modèle du drone n’a pas été précisé. Les trois chiffres sont des mesures différentes de l’activité d’un seul drone, et non des aéronefs ou des incidents distincts.","Les forces grecques auraient identifié et intercepté l’UAV. Aucun engagement d’armes, abattage, écrasement, victime ni dégât n’ont été signalés."]},"N069":{"headline":"Un drone possible signalé tombant et déclenchant un incendie près de Plauru, en Roumanie","description":"Le 2 octobre 2026, un objet, peut-être un drone, a été signalé tombant et déclenchant un incendie près de Plauru, dans le département de Tulcea, en Roumanie. Son origine étrangère n’est pas confirmée.","summary":["Vers 05:00 le 2 octobre 2026, le ministère roumain de la Défense a reçu un signalement indiquant qu’un objet était tombé près de Plauru, dans le département de Tulcea, et avait déclenché un incendie. Le signalement est survenu pendant des attaques nocturnes de drones contre des cibles ukrainiennes de l’autre côté du Danube. L’heure exacte de la chute et le site précis n’ont pas été publiés.","L’objet était peut-être un drone aérien ; l’identification et le modèle étaient en attente d’un examen technique. Son opérateur, sa nationalité et son origine étrangère ne sont pas résolus. Les attaques voisines contre l’Ukraine constituent un contexte, et non une attribution, et le ministère n’a enregistré aucune entrée non autorisée dans l’espace aérien roumain au radar pendant la nuit. Un incendie seul n’établit ni une charge explosive ni une détonation.","Des pompiers de l’IGSU et des équipes du ministère de la Défense ont été envoyés sur le site, et la zone a été sécurisée. Un examen par des spécialistes a été annoncé mais n’a pas été signalé comme achevé. Aucune victime ni aucun dégât matériel n’ont été signalés. La découverte est distincte d’une découverte antérieure de drone à Plauru en août 2026."]},"N070":{"headline":"Alerte à un drone présumé dans le comté de Vilnius, en Lituanie ; objet introuvable","description":"Le 3 octobre 2026, un contact radar non identifié a déclenché une alerte aérienne et fermé l’espace aérien de l’aéroport de Vilnius, en Lituanie. Une incursion de drone n’est pas confirmée.","summary":["Dans la matinée du 3 octobre 2026, un contact radar non identifié a conduit la Lituanie à émettre une alerte aérienne jaune pour le comté de Vilnius à 09:48, heure locale, et à fermer temporairement l’espace aérien contrôlé de l’aéroport de Vilnius. La levée de l’alerte a suivi à 10:34. L’objet a d’abord été signalé comme entrant depuis la Biélorussie ; des responsables ont ensuite décrit une trajectoire vers Vilnius et Ukmergė qui s’est évanouie avant d’atteindre Vilnius.","Il n’a pas été établi que l’objet était un drone. Des responsables ont dit que la trajectoire inhabituellement lente pouvait correspondre à des oiseaux ou à une anomalie radar, et une incursion de drone étranger reste non confirmée. Une approche depuis la Biélorussie n’établit pas la responsabilité de la Biélorussie ou de la Russie, et aucun opérateur ni aucune nationalité n’ont été identifiés.","Des chasseurs de l’OTAN n’ont pas localisé l’objet, et un hélicoptère de l’armée de l’air lituanienne n’a rien trouvé de suspect ; la recherche s’est terminée vers 13:00. Aucun débris, aucune victime ni aucun dégât n’ont été confirmés, et les informations sur un possible incendie ou une possible explosion n’ont pas été étayées."]},"N071":{"headline":"La Grèce signale six violations de l’espace aérien par deux UAV turcs en mer Égée","description":"Le 4 octobre 2026, l’armée grecque a signalé six violations de l’espace aérien et trois infractions à la FIR par deux UAV turcs dans le nord-est et le centre de la mer Égée.","summary":["Le 4 octobre 2026, l’État-major général de la défense nationale hellénique a signalé que deux UAV turcs avaient été actifs au-dessus du nord-est et du centre de la mer Égée, enregistrant six violations de l’espace aérien national et trois infractions à la région d’information de vol (FIR) d’Athènes. OnAlert a relayé le compte rendu le soir même ; les sites exacts et les heures des sorties n’ont pas été publiés.","L’identification comme turcs et la description des vols comme des violations de l’espace aérien national sont des évaluations de l’armée grecque, et le différend gréco-turc sur l’espace aérien demeure pertinent. Les modèles des drones n’ont pas été précisés, et aucune coordonnée ni trajectoire n’a été vérifiée de manière indépendante. Les chiffres mesurent des choses différentes et ne correspondent pas à des incidents distincts.","Les drones ont été identifiés et interceptés selon les procédures habituelles. Aucun aéronef armé, engagement, abattage, écrasement, victime ni dégât n’ont été signalés."]},"N072":{"headline":"Attaque de drones meurtrière signalée contre le céréalier Royad Mammadov au large de la Roumanie","description":"Le 5 octobre 2026, des drones auraient frappé le céréalier Royad Mammadov dans la ZEE roumaine de la mer Noire. Les récits sur les morts divergent ; l’Ukraine a mis en cause la Russie.","summary":["Le 5 octobre 2026, le céréalier Royad Mammadov, qui naviguait d’Izmail, en Ukraine, vers Ravenne, en Italie, a été endommagé par une frappe de drone signalée, une explosion à bord et un incendie en mer Noire, près de la plateforme Pescăruș, à environ 30 milles marins au sud de Sfântu Gheorghe. Le site se trouvait dans la zone économique exclusive (ZEE) de la Roumanie, en dehors de ses eaux territoriales. Une demande de secours a été enregistrée à 10:37, heure locale ; l’heure exacte de la frappe n’est pas vérifiée.","Le président ukrainien Volodymyr Zelensky a déclaré que deux drones russes avaient frappé le navire. Il s’agit d’une affirmation ukrainienne, et non d’une vérification indépendante, et la Roumanie n’a publié aucune conclusion d’attribution. Marius Roibu, directeur du centre de sauvetage MRCC Constanța, a décrit une attaque apparente de plusieurs drones ; le type des drones, leur point de lancement et leurs opérateurs ne sont pas établis.","Les récits sur les victimes divergent. Le ministère roumain de l’Intérieur a d’abord fait état de deux morts et de onze personnes secourues ; le 6 octobre, le ministère azerbaïdjanais des Affaires étrangères a déclaré que le capitaine avait été tué et qu’un autre membre d’équipage azerbaïdjanais était porté disparu. L’ambassade d’Inde a indiqué que trois membres d’équipage indiens avaient survécu, dont un blessé. Un premier signalement selon lequel le navire avait coulé a été corrigé le 6 octobre, lorsqu’il a été signalé à flot et en attente d’un remorquage vers Midia. Petrom a dit que la plateforme Pescăruș n’avait pas été touchée.","La Roumanie a émis un avertissement de risque de naufrage le 7 octobre. L’Avis aux navigateurs 10/65/26, dans la révision des cartes datée du 22 octobre, a ensuite répertorié le navire comme épave dangereuse. Cela établit son état ultérieur, mais ni le moment où il a coulé, ni la réalisation d’un remorquage, ni le point exact de la frappe."]},"N073":{"headline":"Une attaque de drones au large de la Bulgarie coule l’ALFA WATAN et met le feu à l’ABLE","description":"Tôt le 6 octobre 2026, des drones ont attaqué deux navires marchands dans la ZEE bulgare de la mer Noire, à l’est de Byala, coulant l’ALFA WATAN. La Bulgarie ne l’a pas attribuée.","summary":["Aux premières heures du 6 octobre 2026, deux navires marchands, l’ALFA WATAN, battant pavillon togolais, et l’ABLE, battant pavillon des Palaos, ont été attaqués à environ 70 milles marins à l’est de Byala, dans la zone économique exclusive de la Bulgarie, en dehors de ses eaux territoriales. Les autorités bulgares ont fait état de drones d’attaque aériens et maritimes. L’ALFA WATAN a coulé, et le ferry DIOSCURIA voisin a été témoin d’une explosion ; l’ABLE a pris feu.","La Bulgarie n’a pas attribué l’attaque. Rumen Radev a dit le 7 octobre que les circonstances suggéraient la Russie mais que les preuves étaient insuffisantes pour une attribution définitive ; la Russie a nié avoir visé le navire. Le 6 octobre, Zelensky a allégué une attaque russe combinée, en citant une enquête conjointe ; il s’agit d’une affirmation ukrainienne, et non d’une conclusion bulgare. Le 9 octobre, le ministre de la Défense Dimitar Stoyanov a évalué les dégâts de l’ABLE comme une frappe de drone de surface, sans nommer d’opérateur.","L’équipage de l’ALFA WATAN est porté disparu, non confirmé mort. Reuters a fait état de douze Syriens disparus le 7 octobre, puis de dix disparus, dont neuf Syriens, le 8 octobre ; l’écart n’est pas résolu. Les dix-huit membres d’équipage de l’ABLE ont tous été secourus, dont deux blessés. La Bulgarie a interrompu les recherches le 7 octobre, et le 8 octobre, la Syrie a demandé une enquête indépendante. Une inspection du 9 octobre n’a trouvé aucun reste de drone identifiable à bord de l’ABLE, qui était toujours à flot.","NOVA a rapporté le 20 octobre que l’ABLE avait coulé au large de la Turquie après avoir disparu des radars tard le 19 octobre. Le navire avait quitté la zone économique exclusive de la Bulgarie le 14 octobre. Ce naufrage ultérieur signalé reste un prolongement de l’attaque du 6 octobre ; aucun relevé direct de l’épave ni position exacte du naufrage n’ont été obtenus."]},"N074":{"headline":"La Grèce signale neuf violations de l’espace aérien par quatre UAV turcs en mer Égée","description":"Le 6 octobre 2026, l’armée grecque a signalé quatre UAV turcs au-dessus de la mer Égée, avec neuf violations de l’espace aérien national et sept infractions à la FIR d’Athènes.","summary":["Le 6 octobre 2026, un bulletin de l’armée grecque (GEETHA), reproduit le soir même par Liberal, a signalé quatre UAV turcs au-dessus du nord-est et du sud-est de la mer Égée. Il enregistrait neuf violations de l’espace aérien national et sept infractions à la région d’information de vol (FIR) d’Athènes par les drones. Les sites exacts et les heures des sorties n’ont pas été publiés.","L’identification comme turcs est celle du GEETHA, et l’évaluation selon laquelle les vols ont violé l’espace aérien national reste celle de la Grèce, compte tenu du différend gréco-turc sur l’espace aérien. Aucune trajectoire de vol n’a été vérifiée de manière indépendante. Le bulletin recensait aussi deux F-16 pilotés et un CN-235, qui sont exclus des chiffres des drones ; il décrivait les F-16, et non les UAV, comme armés.","Les UAV ont été identifiés et interceptés selon les procédures habituelles. Aucun abattage, engagement d’armes, écrasement, victime ni dégât n’ont été signalés. Les chiffres comptent des choses différentes et ne correspondent pas à des incidents distincts."]},"N075":{"headline":"La Grèce signale quatre violations de l’espace aérien par trois UAV turcs en mer Égée","description":"Le 7 octobre 2026, l’armée grecque a signalé que trois UAV turcs avaient commis quatre violations de l’espace aérien et trois infractions à la FIR d’Athènes au-dessus de la mer Égée.","summary":["Dans la soirée du 7 octobre 2026, OnAlert a publié un compte rendu de l’armée grecque (GEETHA) sur trois UAV turcs au-dessus du nord-est, du centre et du sud-est de la mer Égée ce jour-là. Selon ce compte rendu, les drones ont commis quatre violations de l’espace aérien national et trois infractions à la région d’information de vol (FIR) d’Athènes. Les sites exacts et les heures des sorties n’ont pas été publiés.","L’identification comme turcs est celle du GEETHA, et l’évaluation des violations de l’espace aérien national reste celle de la Grèce, compte tenu du différend gréco-turc sur l’espace aérien. Aucune trajectoire de vol ni évaluation des limites n’ont été vérifiées de manière indépendante. Les modèles, l’armement et la charge des drones n’ont pas été établis.","Les UAV ont été identifiés et interceptés selon les procédures habituelles. Aucun aéronef armé, engagement, abattage, écrasement, victime ni dégât n’ont été signalés. Les trois chiffres comptent des choses différentes et ne correspondent pas à des incidents distincts."]},"N076":{"headline":"La Grèce signale cinq violations de l’espace aérien par cinq UAV turcs en mer Égée","description":"Le 8 octobre 2026, l’armée grecque a signalé cinq UAV turcs au-dessus de la mer Égée, avec cinq violations de l’espace aérien national et cinq infractions à la FIR d’Athènes.","summary":["Le 8 octobre 2026, un compte rendu de l’armée grecque (GEETHA), publié le soir même par Dimokratiki et NewsIT, a signalé cinq UAV turcs au-dessus du nord-est et du sud-est de la mer Égée. Il enregistrait cinq violations de l’espace aérien national et cinq infractions à la région d’information de vol (FIR) d’Athènes par les drones. Les sites exacts et les heures des sorties n’ont pas été publiés.","L’identification comme turcs est celle du GEETHA, et l’évaluation des violations de l’espace aérien national reste celle de la Grèce, compte tenu du différend gréco-turc sur l’espace aérien. Aucune trajectoire de vol n’a été vérifiée de manière indépendante. Un ATR-72 piloté figurant dans le même bulletin représentait deux infractions supplémentaires à la FIR, qui ne font pas partie des chiffres des drones.","Les UAV ont été identifiés et interceptés selon les procédures habituelles. Aucun abattage, engagement d’armes, écrasement, victime ni dégât n’ont été signalés. Les chiffres comptent des choses différentes et ne correspondent pas à des incidents distincts."]},"N077":{"headline":"Des débris d’UAV d’origine inconnue détruits en mer au large de Sinemorets, en Bulgarie","description":"Le 9 octobre 2026, la marine bulgare a détruit lors d’une détonation contrôlée des fragments de drone flottants à 15 milles marins à l’est de Sinemorets. Leur origine est inconnue.","summary":["Vers midi le 9 octobre 2026, des éléments flottants d’un drone aérien ont été repérés en mer Noire, à 15 milles marins à l’est de Sinemorets selon les informations, au large de la Bulgarie. La marine bulgare a envoyé le chasseur de mines Struma pour les examiner. La date est celle de la découverte ; le moment où le drone est initialement tombé n’est pas connu.","Les fragments n’ont pas été identifiés au-delà du fait qu’ils proviennent d’un UAV, et le modèle et le nombre d’aéronefs sont inconnus. Leur origine, leur opérateur et leur nationalité n’ont pas été établis, et aucune attribution à la Russie ou à l’Ukraine n’a été confirmée. Rien ne permet de les relier à l’attaque de drones du 6 octobre contre les navires marchands ALFA WATAN et ABLE.","De la matière explosive était soupçonnée mais n’a pas été confirmée. Des plongeurs du navire auxiliaire Kapitan I rang Dimitar Dobrev ont recommandé de détruire les débris sur place, et le commandant de la marine a autorisé une détonation contrôlée. Aucune victime ni aucun dommage à un navire n’ont été signalés."]},"N078":{"headline":"La Grèce signale cinq violations de l’espace aérien par six UAV turcs en mer Égée","description":"Le 10 octobre 2026, l’armée grecque a signalé six UAV turcs au-dessus de la mer Égée, avec cinq violations de l’espace aérien national et huit infractions à la FIR d’Athènes.","summary":["Le 10 octobre 2026, l’armée grecque (GEETHA) a signalé six UAV militaires turcs au-dessus du nord-est, du centre et du sud-est de la mer Égée, avec cinq violations de l’espace aérien national et huit infractions à la région d’information de vol (FIR) d’Athènes. OnAlert a publié le compte rendu le soir même, et DefenceNet l’a repris tôt le 11 octobre ; les deux décrivent l’activité du même jour.","L’identification comme turcs et l’évaluation de l’espace aérien national sont celles du GEETHA, et le différend gréco-turc sur l’espace aérien demeure pertinent. Aucune trajectoire ni évaluation des limites n’ont été vérifiées de manière indépendante. Les modèles, l’armement et la charge n’ont pas été établis.","Les drones ont été identifiés et interceptés selon les procédures habituelles. Aucun abattage, engagement d’armes, écrasement, victime ni dégât n’ont été signalés. Les chiffres comptent des choses différentes et ne correspondent pas à des incidents distincts."]},"N079":{"headline":"La Bulgarie signale une frappe de drones sur le navire CHELSEA 3 au large de Byala ; équipage secouru","description":"La Bulgarie a dit que des drones avaient frappé le navire CHELSEA 3 à l’est de Byala dans la nuit du 13 octobre 2026 ; les 15 membres d’équipage ont été secourus. L’opérateur n’a pas été identifié.","summary":["Dans la nuit du 13 octobre 2026, le navire marchand CHELSEA 3, battant pavillon maltais, a été frappé par des drones en mer Noire, à 18 milles marins à l’est de Byala, dans la province de Varna, selon les informations, dans la zone économique exclusive de la Bulgarie et en dehors de ses eaux territoriales. Selon le récit de l’équipage, relayé par le Premier ministre bulgare, trois drones aériens ont touché le pont et la coque. Une notification de détresse est parvenue au centre de sauvetage maritime de Varna à 01:30, heure locale.","L’opérateur et la nationalité ne sont pas résolus. Radev a dit que les preuves étaient insuffisantes pour accuser l’un ou l’autre belligérant ; il a soutenu que les attaques profitent à la Russie, mais cet argument et les consultations diplomatiques prévues n’établissent pas la responsabilité de la Russie. Le navire appartiendrait à des intérêts ukrainiens et serait immatriculé à Odessa, ce qui est distinct de la question de savoir qui l’a attaqué.","La Police des frontières a évacué les 15 membres d’équipage, sept Ukrainiens et huit Azerbaïdjanais, qui ont été amenés à Varna ; cinq ont été soignés pour des blessures légères signalées au départ, et aucun décès n’a été signalé. La BNR rapporte que le navire endommagé a accosté à Bourgas-Ouest le 17 octobre ; l’enquête reste ouverte. Le 13 octobre, un autre navire a été signalé frappé et coulé à l’est de Krapets.","Le récit de MaltaDaily indique le 12 octobre et quatre blessés légers. Ces différences avec le récit bulgare ne sont pas résolues et n’identifient pas une seconde attaque.","Le 19 octobre, Zhivko Petrov, directeur de l’administration maritime de Bourgas, a évalué les trois brèches dans la coque comme des dégâts d’explosion, possiblement causés par un drone de surface. Cela contredit le récit initial d’un drone aérien et reste soumis à une enquête de spécialistes. Le navire était stable au port et une enquête du parquet militaire était en cours.","Le 20 octobre, le Premier ministre a fait état de l’examen de restes de drone et d’une analyse chimique. Chernomore/BGNES a spécifiquement rapporté des fragments à bord du navire et l’absence de munitions ou de radiations lors des premiers contrôles ; le récit de la BNR/BTA était moins précis sur la déclaration du ministre concernant la récupération. L’identification finale de l’arme et l’opérateur restent non résolus. Chernomore indique aussi deux blessés, en plus des récits antérieurs de quatre blessés et de cinq personnes soignées ; les chiffres différents ne sont pas additionnés.","Le 21 octobre, le ministre de la Défense a précisé que le matériel récupéré pouvait provenir du navire, d’un drone ou d’un autre objet. NOVA et BNT ont rapporté que des équipes partenaires inspectaient déjà le navire ; l’identification des fragments et l’analyse des explosifs étaient encore en attente. Ces développements mettent à jour la même attaque, et non un nouvel incident."]},"N080":{"headline":"Le HS Dignity identifié comme le navire coulé au large de Krapets ; onze marins disparus","description":"Le HS Dignity a coulé lors d’une attaque de drone signalée au large de Krapets, en Bulgarie, le 13 octobre 2026. Cinq marins ont été secourus et onze étaient portés disparus ; l’attribution n’est pas résolue.","summary":["Le navire marchand signalé comme frappé par un drone et coulé au large de Krapets le 13 octobre 2026 a été identifié comme le HS Dignity, battant pavillon de la Guinée-Bissau. L’emplacement signalé, à environ 17 milles marins à l’est de Krapets, se trouve dans la zone économique exclusive de la Bulgarie, en dehors des eaux territoriales. Les heures exactes de la frappe et du naufrage restent non publiées.","Des informations ultérieures font état de cinq marins secourus et de onze disparus, remplaçant le premier récit d’un seul sauvetage. Les opérations de recherche et de sauvetage se poursuivaient au moment de ces informations. Les marins disparus ne sont pas comptés comme morts confirmés. L’identification et la mise à jour sur le sauvetage concernent le même naufrage, et non une autre attaque.","Le type du drone et son opérateur restent non résolus. L’Ukraine a accusé la Russie, mais les autorités bulgares n’ont pas établi de responsabilité de manière concluante. Le pavillon du navire n’indique pas la nationalité de son équipage. Cet incident reste distinct de l’attaque du CHELSEA 3 près de Byala et des attaques du 6 octobre contre l’ALFA WATAN et l’ABLE."]},"N082":{"headline":"La Roumanie émet une alerte RO-Alert pour le nord de Tulcea ; aucune entrée dans l’espace aérien détectée","description":"La Roumanie a émis une alerte RO-Alert pour le nord de Tulcea le 14 octobre 2026. Trois cibles aériennes sont restées au-dessus de l’Ukraine ; le MApN n’a signalé aucune entrée dans l’espace aérien roumain.","summary":["La Roumanie a émis une alerte RO-Alert pour le nord du département de Tulcea à 06:39 le 14 octobre 2026, après qu’un radar a détecté trois cibles aériennes près de Vâlkove, en Ukraine. Deux chasseurs F-16 roumains et un hélicoptère IAR-330 SOCAT ont été déployés.","Le ministère de la Défense a explicitement déclaré qu’aucune des trois cibles n’était entrée dans l’espace aérien national roumain. La déclaration n’a établi ni leurs modèles ni leur opérateur, et trois cibles aériennes ne doivent pas être lues comme trois drones confirmés.","Le registre inclut cette fiche comme une seule alerte et réponse de protection civile, et non comme une incursion étrangère. Aucune frappe, aucun abattage, aucune victime, aucun dégât ni aucun débris n’ont été signalés. Son marqueur sur la carte représente la zone d’alerte roumaine, et non la position d’un drone."]},"N083":{"headline":"Une cible aérienne pénètre en Roumanie près de Sulina, puis est abattue en Ukraine","description":"Une cible est brièvement entrée dans l’espace aérien roumain à l’est de Sulina le 14 octobre 2026, puis a été abattue en Ukraine. L’identité du drone et l’opérateur restent non résolus.","summary":["Le ministère roumain de la Défense a signalé une brève incursion dans la matinée à l’est de Sulina le 14 octobre 2026. Une alerte RO-Alert de 10:19 a prévenu les habitants du nord et de l’est de Tulcea, et deux F-16 roumains ont décollé. L’heure exacte d’entrée n’a pas été donnée.","La cible non identifiée est retournée dans l’espace aérien ukrainien, où la défense aérienne ukrainienne l’a abattue, selon le ministère. Le marqueur roumain sur la carte identifie la zone de l’incursion, et non le site de l’abattage ultérieur. Son identité d’UAV et son opérateur restent non résolus.","La fin d’alerte est intervenue à 11:22. Cette fiche est distincte de l’alerte de 06:39, qui n’impliquait aucune entrée en Roumanie, et des incursions de l’après-midi et de la soirée. Aucune victime ni aucun dégât n’ont été signalés en Roumanie."]},"N084":{"headline":"Une cible aérienne passe huit minutes dans l’espace aérien roumain au nord-est de Sulina","description":"Une cible aérienne non identifiée est entrée dans l’espace aérien roumain au nord-est de Sulina de 17:38 à 17:46 le 14 octobre 2026. Son opérateur et son identité d’UAV ne sont pas résolus.","summary":["Un radar roumain a suivi une cible non identifiée entrant dans l’espace aérien national à 17:38 le 14 octobre 2026, à environ 22 km au nord-est de Sulina, au-dessus des eaux territoriales. Elle est repartie à 17:46.","Deux F-16 roumains ont décollé et une alerte RO-Alert a été émise à 17:39. L’alerte aérienne a pris fin à 19:03. Aucun engagement d’armes, abattage, dégât ni victime n’ont été signalés.","Il s’agit d’une incursion distincte en après-midi. La déclaration officielle établit le franchissement et sa durée, tandis que l’identification comme UAV, son modèle et son opérateur restent non résolus."]},"N085":{"headline":"Deux cibles aériennes pénètrent en Roumanie au large de Tulcea ; l’une est détruite plus tard près de Reni","description":"Deux cibles sont entrées dans l’espace aérien roumain à 20:04 le 14 octobre 2026. L’une a disparu du radar en mer ; l’autre a été détruite plus tard en Ukraine. Attribution inconnue.","summary":["Deux cibles aériennes sont entrées dans l’espace aérien roumain au-dessus de la mer Noire à 20:04 le 14 octobre 2026, selon le ministère de la Défense. Le contact avec l’une a été perdu au-dessus de la mer ; l’autre est repartie à 20:13 en direction de Vâlcove et a ensuite été détruite par la défense aérienne ukrainienne près de Reni.","Deux F-18 espagnols ont décollé. Des alertes ont été émises pour Tulcea à 20:02 et pour l’est de Galați à 20:33 ; la fin d’alerte est intervenue à 21:14. Les modèles et les opérateurs des cibles restent non résolus.","Les deux cibles sont conservées dans une seule fiche d’incursion horodatée. La perte radar ne prouve ni un écrasement ni une frappe sur le YARA J, dont l’incident distinct est enregistré sous N086. Un lien reste non prouvé, et les fiches ne doivent pas être interprétées comme un décompte vérifié de drones distincts."]},"N086":{"headline":"Une frappe de drone met le feu au YARA J près de Sulina ; équipage sain et sauf","description":"Le YARA J a été touché près de Sulina le 14 octobre 2026. Ses 17 membres d’équipage étaient sains et saufs. Une source militaire de l’OTAN a évalué les drones comme d’origine russe.","summary":["Un drone a frappé le pétrolier YARA J, battant pavillon des Comores, près de Sulina le 14 octobre 2026. Le président roumain a confirmé l’attaque le lendemain. Une source militaire de l’OTAN citée par Reuters a évalué les drones qui ont touché le YARA J et le WINE TRADER comme d’origine russe ; un opérateur précis n’a pas été établi dans les informations examinées.","L’équipage a signalé une explosion et un incendie. L’incendie a été éteint et les 17 membres d’équipage signalés étaient sains et saufs, sans blessé ni naufrage signalé. Le navire se trouvait dans les eaux territoriales roumaines. Le MRCC a demandé de l’aide à 20:25 ; le SAR Apollo est parti à 20:31 et a été rappelé à 21:30 après que l’équipage a dit qu’une aide n’était plus nécessaire. Ce sont des heures de sauvetage, et non une heure de frappe vérifiée.","Cette fiche met à jour l’incident d’origine et conserve son URL. L’absence initiale d’approche détectée par radar n’annule pas la confirmation ultérieure de l’attaque. Un lien avec l’épisode radar de 20:04 de N085 reste non prouvé. Le WINE TRADER et le Sea Destiny ont des fiches distinctes."]},"N087":{"headline":"Un drone pénètre brièvement dans l’espace aérien roumain au sud-est de Sulina à 01:34","description":"Le ministère roumain de la Défense a signalé un drone dans l’espace aérien national au sud-est de Sulina à 01:34 le 15 octobre 2026. Il a disparu du radar ; son opérateur est inconnu.","summary":["Un drone a été détecté dans l’espace aérien roumain au-dessus des eaux territoriales au sud-est de Sulina à 01:34 le 15 octobre 2026. Le ministère de la Défense a indiqué qu’il était resté visible environ une minute avant de disparaître du radar.","Des F-18 espagnols ont décollé pendant l’alerte nocturne. Des F-16 roumains ont ensuite été déployés pour d’autres contacts plus à l’est de l’île des Serpents, suivis d’une alerte à 04:57. Le communiqué n’a signalé aucune autre entrée et une fin d’alerte à 05:46.","Il s’agit d’une incursion distincte après minuit. Le modèle et l’opérateur du drone sont inconnus. La perte du contact radar n’établit ni un abattage, ni un écrasement, ni un impact ; aucun n’a été confirmé dans la déclaration examinée."]},"N088":{"headline":"La Grèce signale six UAV turcs et quatre violations de l’espace aérien en mer Égée","description":"La Grèce a signalé six UAV turcs, quatre violations de l’espace aérien et onze infractions à la FIR le 15 octobre 2026. Aucun engagement d’armes n’a été signalé.","summary":["L’armée grecque a signalé six UAV turcs au-dessus du nord-est et du sud-est de la mer Égée le 15 octobre 2026. NewsIT et ProtoThema ont reproduit quatre violations de l’espace aérien national et onze infractions à la FIR d’Athènes. Les six aéronefs ont tous été identifiés et interceptés, sans engagement d’armes signalé.","Les modèles des aéronefs, les sites exacts et les heures des sorties n’ont pas été publiés. L’attribution à la Turquie et l’évaluation de l’espace aérien national sont celles des autorités grecques ; cette dernière reste soumise au différend gréco-turc de longue date sur l’espace aérien. Le bulletin GEETHA d’origine n’a pas été obtenu directement.","Aucun écrasement, aucune victime, aucun dégât ni aucune opération EOD n’ont été signalés. Il s’agit d’une fiche d’activité datée unique. Les décomptes d’UAV, de violations et de FIR mesurent des choses différentes et ne créent pas de lignes d’incident supplémentaires."]},"N089":{"headline":"Le Sea Destiny signale une explosion à proximité après que l’OTAN l’a nommé comme navire visé","description":"L’OTAN a nommé le Sea Destiny comme visé près de Sulina dans la nuit du 14 au 15 octobre 2026. Le navire a signalé une explosion à proximité mais aucun dégât ; la cause n’est pas résolue.","summary":["L’OTAN a nommé le vraquier Sea Destiny, battant pavillon des Îles Marshall, comme navire supplémentaire visé lors des incidents des 14–15 octobre près de Sulina. Le ministre roumain de la Défense a dit qu’il avait signalé une explosion à portée de vue mais n’avait pas été touché. Le navire a été signalé dans les eaux territoriales roumaines.","L’incident reste provisoire. Une explosion causée par un drone, un impact sur le navire et son opérateur n’ont pas été confirmés. L’évaluation d’origine russe rapportée pour les drones qui ont frappé le YARA J et le WINE TRADER n’est pas spécifiquement une attribution pour le Sea Destiny. Aucun dégât, aucune victime, aucune récupération ni aucune opération EOD n’ont été signalés.","L’heure et le lieu exacts de l’explosion restent non publiés. La lecture utilise le 14 octobre, premier jour de la plage nocturne. Cette fiche reste distincte des deux pétroliers ; le Dania J à Izmail, en Ukraine, est hors du périmètre UE du registre."]},"N090":{"headline":"Frappe de drone sur le WINE TRADER au large de Sulina ; des restes humains retrouvés ensuite à Varna","description":"Des restes humains ont été trouvés lors des réparations du WINE TRADER à Varna après la frappe de drone du 15 octobre au large de Sulina. L’identification ADN et les enquêtes se poursuivent.","summary":["Un drone a frappé le pétrolier WINE TRADER, battant pavillon de Saint-Marin, au large de Sulina le 15 octobre 2026. Le président roumain a confirmé l’attaque. Une source militaire de l’OTAN citée par Reuters a évalué les drones qui ont touché ce pétrolier et le YARA J comme d’origine russe ; un opérateur précis n’a pas été établi dans les informations examinées.","Au départ, cinq des douze membres d’équipage ont été secourus et sept ont été portés disparus. Deux survivants avaient des brûlures du cuir chevelu ou une légère inhalation de fumée ; les cinq étaient stables et ont été conduits à l’hôpital. La mer agitée et les dégâts ont gêné les recherches. Une déclaration syndicale du 19 octobre a rapporté que des équipes avaient fouillé les espaces accessibles. Le 22 octobre, le ministère croate des Affaires étrangères a dit que les recherches avaient cessé en raison du temps écoulé.","Le 7 novembre, le parquet de Varna a confirmé que des restes humains gravement endommagés avaient été trouvés lors du déblaiement d’un navire touché par un drone et reçu pour réparations début novembre. La BNR l’identifie comme le WINE TRADER et fait état du corps d’un marin et de restes humains. Des examens ADN ont été ordonnés pour établir les identités, et les enquêtes se poursuivent en Bulgarie et en Roumanie. La déclaration de source primaire ne donne aucun bilan des morts. Les premiers chiffres rapportés par les médias divergent ; ni un bilan définitif ni un nombre actuel de disparus ne sont donc déduits des chiffres historiques du sauvetage.","Le navire a été signalé à environ 13 milles marins au sud-est de Sulina, juste en dehors des eaux territoriales roumaines. Il est inclus dans la couverture en mer du registre. La demande de secours à 06:58 n’est pas une heure d’attaque vérifiée. Cette fiche fait passer la piste antérieure de la liste de surveillance, qui ne concernait qu’un incendie, à une fiche Frappe rouge unique, combinant l’attaque, l’incendie et le sauvetage ; elle reste distincte du YARA J et du Sea Destiny."]},"N091":{"headline":"Dailidžiai : des garde-frontières récupèrent un drone transfrontalier chargé de cigarettes","description":"Des garde-frontières lituaniens signalent un drone transportant des cigarettes venu de Biélorussie près de Dailidžiai. Une cargaison criminelle n’établit pas de parrainage étatique.","summary":["Vers minuit, de mardi à mercredi, 13–14 octobre 2026 : contraint de se poser par des moyens électroniques ; endommagé à l’impact ; drone et cargaison récupérés après le lever du jour.","1 000 paquets de cigarettes NZ Gold et Minsk Super Slims ont été récupérés. Le VSAT décrit un transport criminel depuis la Biélorussie ; la nationalité des opérateurs et un éventuel parrainage étatique restent non établis."]},"N092":{"headline":"Adutiškis : des garde-frontières récupèrent un drone transfrontalier chargé de cigarettes","description":"Des garde-frontières lituaniens signalent un drone transportant des cigarettes venu de Biélorussie près d’Adutiškis. Une cargaison criminelle n’établit pas de parrainage étatique.","summary":["Nuit de vendredi, 9–10 octobre 2026 : équipement antidrone utilisé ; cargaison trouvée à 400 m de la frontière, drone 300 m plus loin.","1 000 paquets de cigarettes Minsk City MS ont été récupérés. Le VSAT décrit un transport criminel depuis la Biélorussie ; la nationalité des opérateurs et un éventuel parrainage étatique restent non établis."]},"N093":{"headline":"Šiulgiai : des garde-frontières récupèrent un drone transfrontalier chargé de cigarettes","description":"Des garde-frontières lituaniens signalent un drone transportant des cigarettes venu de Biélorussie près de Šiulgiai. Une cargaison criminelle n’établit pas de parrainage étatique.","summary":["Nuit de samedi, 10–11 octobre 2026 : prise de contrôle ; le drone est tombé dans une zone boisée et a été récupéré à environ 500 m de la frontière.","250 paquets de cigarettes NZ Gold ont été récupérés. Le VSAT décrit un transport criminel depuis la Biélorussie ; la nationalité des opérateurs et un éventuel parrainage étatique restent non établis."]},"N094":{"headline":"Tribonys : des garde-frontières récupèrent un drone transfrontalier chargé de cigarettes","description":"Des garde-frontières lituaniens signalent un drone transportant des cigarettes venu de Biélorussie près de Tribonys. Une cargaison criminelle n’établit pas de parrainage étatique.","summary":["Nuit de samedi, 3–4 octobre 2026 : l’équipement antidrone a forcé la descente ; drone récupéré sur des terres agricoles à environ 2 km de la frontière.","320 paquets de cigarettes NZ Gold ont été récupérés. Le VSAT décrit un transport criminel depuis la Biélorussie ; la nationalité des opérateurs et un éventuel parrainage étatique restent non établis."]},"N095":{"headline":"Des F-16 roumains abattent deux drones de la famille Geran au large de Sulina","description":"La Roumanie confirme que deux drones à réaction de la famille Geran ont été abattus au-dessus de ses eaux territoriales au large de Sulina le 17 octobre. Une seule opération, deux drones.","summary":["Le ministère roumain de la Défense indique que deux F-16 ont abattu deux drones d’attaque à réaction de la famille Geran au-dessus des eaux territoriales roumaines le 17 octobre 2026. Le premier se trouvait au sud-est de Sulina à 18:01 EEST, le second à l’est de Sulina à 18:05.","Le ministère indique respectivement deux et cinq minutes dans l’espace aérien national avant l’interception. Il s’agit d’une seule opération impliquant deux drones ; la déclaration n’identifie ni l’opérateur ni les cibles visées. Le point d’ancrage sur la carte est approximatif.","Le 18 octobre, le ministre de la Défense Radu Miruță a évalué les drones comme probablement des Geran 4 d’origine russe. Le modèle exact et le sous-type de propulsion restent incertains, et l’opérateur du lancement et les cibles visées restent non établis."]},"N096":{"headline":"Une explosion de drone près de Juodžionys endommage une voiture qui passait","description":"Un drone est entré en Lituanie le 18 octobre et a explosé près de Juodžionys, endommageant une voiture. Des responsables ont identifié une origine ukrainienne ; une enquête conjointe se poursuit.","summary":["Un drone est entré en Lituanie dans la matinée du 18 octobre 2026 et aurait explosé près de Juodžionys, dans le district de Pasvalys. Des débris ont endommagé une voiture qui passait sans blesser ses occupants. La séquence précise de l’explosion et de la chute faisait l’objet d’une enquête.","Le ministre de la Défense Robertas Kaunas a relié l’engin à l’attaque ukrainienne contre Saint-Pétersbourg et a évalué que la guerre électronique russe l’avait dévié. Le 19 octobre, le Premier ministre lituanien a dit que les débris et la notification de l’Ukraine étayaient une origine ukrainienne et que le drone transportait des explosifs. Le ministère polonais de la Défense l’a également identifié comme ukrainien et a démenti l’affirmation selon laquelle il avait été lancé depuis la Lituanie. L’explication par le brouillage restait une évaluation.","La chronologie publiée par la Lituanie place le premier contact radar à 05:47 EEST au-dessus de la Pologne et l’entrée en Lituanie à 06:02. Le radar polonais n’a pas corroboré cette trajectoire de manière indépendante. Des chasseurs de l’OTAN ont décollé en urgence mais n’ont pas tiré. Le premier compte rendu des NBS lettones n’indiquait pas d’entrée en Lettonie de ce vol ; des signalements polonais non vérifiés ne sont pas des événements confirmés supplémentaires.","Le 20 octobre, le président Nausėda a dit que les ministères lituanien et polonais de la Défense avaient formé un groupe d’enquête conjoint. L’itinéraire complet et le mécanisme de l’écrasement restaient non résolus."]},"N097":{"headline":"La Grèce signale six UAV turcs et neuf violations de l’espace aérien le 19 octobre","description":"Des comptes rendus militaires grecs recensent six UAV turcs, neuf violations de l’espace aérien national et neuf infractions à la FIR d’Athènes en mer Égée le 19 octobre 2026.","summary":["Des comptes rendus militaires grecs, reproduits par OnAlert et recoupés par Veteranos, décrivent six UAV turcs dans le nord-est et le sud-est de la mer Égée le 19 octobre 2026. Ils recensent neuf violations de l’espace aérien national et neuf infractions à la FIR d’Athènes. Ce sont des mesures différentes au sein d’une même fiche d’activité datée, et non dix-huit incidents distincts.","Une identification et une interception de routine ont été signalées, sans engagement armé, écrasement ni victime. Les trajectoires de vol exactes et les heures des sorties individuelles n’ont pas été publiées. L’évaluation de l’espace aérien reste attribuée à la Grèce compte tenu du différend gréco-turc ; le bulletin GEETHA d’origine n’a pas été obtenu directement. NewsIT cite OnAlert et est traité comme une republication."]},"N098":{"headline":"Dumblė · drone à cigarettes transfrontalier intercepté en Lituanie","description":"Zone du village de Dumblė, district de Šalčininkai ; récupéré à environ 290 m à l’intérieur de la frontière avec la Biélorussie. Le VSAT signale une intervention électronique, des dégâts dus à l’écrasement et une récupération ; opérateur inconnu.","summary":["Nuit de vendredi ; récupéré le samedi matin, 16–17 octobre 2026 : l’équipement antidrone a interrompu l’aéronef ; l’obscurité et le brouillard ont retardé la récupération jusqu’au lever du jour. Le drone a été endommagé dans sa chute. 100 paquets de cigarettes NZ Gold avec timbres fiscaux biélorusses.","Zone du village de Dumblė, district de Šalčininkai ; récupéré à environ 290 m à l’intérieur de la frontière avec la Biélorussie. Transport criminel transfrontalier depuis la Biélorussie selon le VSAT ; nationalité des opérateurs et parrainage étatique non établis.","Le rapport du VSAT du 19 octobre indique « Penktadienio naktį » (nuit de vendredi), avec une récupération après l’aube le samedi. L’intervalle du 16–17 octobre est déduit de ces jours de la semaine ; l’heure exacte du vol et la limite de minuit ne sont pas publiées. La lecture utilise la première date. Les dégâts d’impact signalés étayent un écrasement ; une intervention électronique n’est pas un abattage cinétique. Un seul événement pour l’intervention électronique, l’écrasement et la récupération ultérieure. Distinct de N099 et des saisies antérieures d’octobre ; les totaux annuels agrégés n’ajoutent aucun événement."]},"N099":{"headline":"Daugidonys–Beržiškės · drone à cigarettes transfrontalier intercepté en Lituanie","description":"Détecté près de Daugidonys ; récupéré dans une zone boisée près de Beržiškės, district de Šalčininkai, à environ 1 050 m de la frontière avec la Biélorussie. Le VSAT signale une intervention électronique, des dégâts dus à l’écrasement et une récupération ; opérateur inconnu.","summary":["Nuit de dimanche, 18 octobre 2026 ; limite de minuit non résolue : la surveillance a enregistré la chute de l’aéronef après une intervention électronique. Les garde-frontières ont récupéré le drone endommagé et la cargaison détachée quelques minutes plus tard. 750 paquets de cigarettes Minsk 5 Superslims avec timbres fiscaux biélorusses.","Détecté près de Daugidonys ; récupéré dans une zone boisée près de Beržiškės, district de Šalčininkai, à environ 1 050 m de la frontière avec la Biélorussie. Transport criminel transfrontalier depuis la Biélorussie selon le VSAT ; nationalité des opérateurs et parrainage étatique non établis.","Le rapport du VSAT du 19 octobre indique « sekmadienio naktį » (nuit de dimanche), sans heure précise. La lecture utilise le dimanche nommé, 18 octobre, comme date déduite ; la source ne précise pas si l’intervalle nocturne a commencé le 17 octobre ou s’est poursuivi jusqu’au 19 octobre. Aucune limite précise de minuit n’est affirmée. La chute observée par la surveillance et les dégâts d’impact étayent un écrasement ; une intervention électronique n’est pas un abattage cinétique. Un seul événement pour la détection, l’intervention électronique, l’écrasement et la récupération. Distinct de l’opération de Daugidonys N036 de septembre et de l’événement de Dumblė N098 d’octobre."]},"N100":{"headline":"La Grèce signale un UAV turc et une violation de l’espace aérien le 17 septembre","description":"Des comptes rendus militaires grecs recensent un UAV turc, une violation de l’espace aérien national et trois infractions à la FIR d’Athènes en mer Égée le 17 septembre 2026.","summary":["Des comptes rendus militaires grecs, reproduits par OnAlert et Veteranos, recensent un UAV turc, une violation de l’espace aérien national et trois infractions à la FIR d’Athènes dans le nord-est / sud-est de la mer Égée le 17 septembre 2026. Ce sont des mesures différentes au sein d’une même fiche d’activité datée.","Une identification/interception de routine a été signalée. Les trajectoires de vol exactes n’ont pas été publiées, et le bulletin GEETHA d’origine n’a pas été obtenu directement. L’évaluation de l’espace aérien reste attribuée à la Grèce ; des comptes rendus concordants ne la vérifient pas de manière indépendante."]},"N101":{"headline":"La Grèce signale quatre UAV turcs et quatre violations de l’espace aérien le 19 septembre","description":"Des comptes rendus militaires grecs recensent quatre UAV turcs, quatre violations de l’espace aérien national et cinq infractions à la FIR d’Athènes en mer Égée le 19 septembre 2026.","summary":["Des comptes rendus militaires grecs, reproduits par Capital.gr et Veteranos, recensent quatre UAV turcs, quatre violations de l’espace aérien national et cinq infractions à la FIR d’Athènes dans le nord-est / sud-est de la mer Égée le 19 septembre 2026. Ce sont des mesures différentes au sein d’une même fiche d’activité datée.","Une identification/interception de routine a été signalée. Les trajectoires de vol exactes n’ont pas été publiées, et le bulletin GEETHA d’origine n’a pas été obtenu directement. L’évaluation de l’espace aérien reste attribuée à la Grèce ; des comptes rendus concordants ne la vérifient pas de manière indépendante."]},"N102":{"headline":"La Grèce signale six UAV turcs et six violations de l’espace aérien le 20 septembre","description":"Des comptes rendus militaires grecs recensent six UAV turcs, six violations de l’espace aérien national et sept infractions à la FIR d’Athènes en mer Égée le 20 septembre 2026.","summary":["Des comptes rendus militaires grecs, reproduits par CNN Greece et OnAlert, recensent six UAV turcs, six violations de l’espace aérien national et sept infractions à la FIR d’Athènes dans le nord-est / centre / sud-est de la mer Égée le 20 septembre 2026. Ce sont des mesures différentes au sein d’une même fiche d’activité datée.","Une identification/interception de routine a été signalée. Les trajectoires de vol exactes n’ont pas été publiées, et le bulletin GEETHA d’origine n’a pas été obtenu directement. L’évaluation de l’espace aérien reste attribuée à la Grèce ; des comptes rendus concordants ne la vérifient pas de manière indépendante."]},"N103":{"headline":"La Grèce signale cinq UAV turcs et trois violations de l’espace aérien le 22 septembre","description":"Des comptes rendus militaires grecs recensent cinq UAV turcs, trois violations de l’espace aérien national et neuf infractions à la FIR d’Athènes en mer Égée le 22 septembre 2026.","summary":["Des comptes rendus militaires grecs, reproduits par OnAlert et Parapolitika, recensent cinq UAV turcs, trois violations de l’espace aérien national et neuf infractions à la FIR d’Athènes dans le nord-est / sud-est de la mer Égée le 22 septembre 2026. Ce sont des mesures différentes au sein d’une même fiche d’activité datée. Deux des cinq UAV ont commis les trois violations de l’espace aérien national.","Une identification/interception de routine a été signalée. Les trajectoires de vol exactes n’ont pas été publiées, et le bulletin GEETHA d’origine n’a pas été obtenu directement. L’évaluation de l’espace aérien reste attribuée à la Grèce ; des comptes rendus concordants ne la vérifient pas de manière indépendante."]},"N104":{"headline":"La Grèce signale sept UAV turcs et deux violations de l’espace aérien le 23 septembre","description":"Des comptes rendus militaires grecs recensent sept UAV turcs, deux violations de l’espace aérien national et sept infractions à la FIR d’Athènes en mer Égée le 23 septembre 2026.","summary":["Des comptes rendus militaires grecs, reproduits par OnAlert et Veteranos, recensent sept UAV turcs, deux violations de l’espace aérien national et sept infractions à la FIR d’Athènes dans le sud-est de la mer Égée le 23 septembre 2026. Ce sont des mesures différentes au sein d’une même fiche d’activité datée.","Une identification/interception de routine a été signalée. Les trajectoires de vol exactes n’ont pas été publiées, et le bulletin GEETHA d’origine n’a pas été obtenu directement. L’évaluation de l’espace aérien reste attribuée à la Grèce ; des comptes rendus concordants ne la vérifient pas de manière indépendante."]},"N105":{"headline":"La Grèce signale cinq UAV turcs et six violations de l’espace aérien le 25 septembre","description":"Des comptes rendus militaires grecs recensent cinq UAV turcs, six violations de l’espace aérien national et six infractions à la FIR d’Athènes en mer Égée le 25 septembre 2026.","summary":["Des comptes rendus militaires grecs, reproduits par OnAlert et Veteranos, recensent cinq UAV turcs, six violations de l’espace aérien national et six infractions à la FIR d’Athènes dans le nord-est / centre / sud-est de la mer Égée le 25 septembre 2026. Ce sont des mesures différentes au sein d’une même fiche d’activité datée.","Une identification/interception de routine a été signalée. Les trajectoires de vol exactes n’ont pas été publiées, et le bulletin GEETHA d’origine n’a pas été obtenu directement. L’évaluation de l’espace aérien reste attribuée à la Grèce ; des comptes rendus concordants ne la vérifient pas de manière indépendante."]},"N106":{"headline":"La Grèce signale trois UAV turcs et deux violations de l’espace aérien le 26 septembre","description":"Des comptes rendus militaires grecs recensent trois UAV turcs, deux violations de l’espace aérien national et trois infractions à la FIR d’Athènes en mer Égée le 26 septembre 2026.","summary":["Des comptes rendus militaires grecs, reproduits par OnAlert et Veteranos, recensent trois UAV turcs, deux violations de l’espace aérien national et trois infractions à la FIR d’Athènes dans le nord-est / sud-est de la mer Égée le 26 septembre 2026. Ce sont des mesures différentes au sein d’une même fiche d’activité datée.","Une identification/interception de routine a été signalée. Les trajectoires de vol exactes n’ont pas été publiées, et le bulletin GEETHA d’origine n’a pas été obtenu directement. L’évaluation de l’espace aérien reste attribuée à la Grèce ; des comptes rendus concordants ne la vérifient pas de manière indépendante."]},"N107":{"headline":"La Grèce signale un UAV turc et quatre violations de l’espace aérien le 28 septembre","description":"Des comptes rendus militaires grecs recensent un UAV turc, quatre violations de l’espace aérien national et deux infractions à la FIR d’Athènes en mer Égée le 28 septembre 2026.","summary":["Des comptes rendus militaires grecs, reproduits par OnAlert et VoiceNews, recensent un UAV turc, quatre violations de l’espace aérien national et deux infractions à la FIR d’Athènes dans le sud-est de la mer Égée le 28 septembre 2026. Ce sont des mesures différentes au sein d’une même fiche d’activité datée.","Une identification/interception de routine a été signalée. Les trajectoires de vol exactes n’ont pas été publiées, et le bulletin GEETHA d’origine n’a pas été obtenu directement. L’évaluation de l’espace aérien reste attribuée à la Grèce ; des comptes rendus concordants ne la vérifient pas de manière indépendante."]},"N108":{"headline":"La Grèce signale trois UAV turcs et trois violations de l’espace aérien le 29 septembre","description":"Des comptes rendus militaires grecs recensent trois UAV turcs, trois violations de l’espace aérien national et cinq infractions à la FIR d’Athènes en mer Égée le 29 septembre 2026.","summary":["Des comptes rendus militaires grecs, reproduits par OnAlert et Veteranos, recensent trois UAV turcs, trois violations de l’espace aérien national et cinq infractions à la FIR d’Athènes dans le nord-est / sud-est de la mer Égée le 29 septembre 2026. Ce sont des mesures différentes au sein d’une même fiche d’activité datée.","Une identification/interception de routine a été signalée. Les trajectoires de vol exactes n’ont pas été publiées, et le bulletin GEETHA d’origine n’a pas été obtenu directement. L’évaluation de l’espace aérien reste attribuée à la Grèce ; des comptes rendus concordants ne la vérifient pas de manière indépendante."]},"N109":{"headline":"La Grèce signale quatre UAV turcs et une violation de l’espace aérien le 30 septembre","description":"Des comptes rendus militaires grecs recensent quatre UAV turcs, une violation de l’espace aérien national et cinq infractions à la FIR d’Athènes en mer Égée le 30 septembre 2026.","summary":["Des comptes rendus militaires grecs, reproduits par OnAlert et Veteranos, recensent quatre UAV turcs, une violation de l’espace aérien national et cinq infractions à la FIR d’Athènes dans le nord-est / centre / sud-est de la mer Égée le 30 septembre 2026. Ce sont des mesures différentes au sein d’une même fiche d’activité datée.","Une identification/interception de routine a été signalée. Les trajectoires de vol exactes n’ont pas été publiées, et le bulletin GEETHA d’origine n’a pas été obtenu directement. L’évaluation de l’espace aérien reste attribuée à la Grèce ; des comptes rendus concordants ne la vérifient pas de manière indépendante."]},"N110":{"headline":"La Grèce signale quatre UAV turcs et sept violations de l’espace aérien le 5 octobre","description":"Des comptes rendus militaires grecs recensent quatre UAV turcs, sept violations de l’espace aérien national et quatre infractions à la FIR d’Athènes en mer Égée le 5 octobre 2026.","summary":["Des comptes rendus militaires grecs, reproduits par OnAlert et SKAI, recensent quatre UAV turcs, sept violations de l’espace aérien national et quatre infractions à la FIR d’Athènes dans le nord-est / sud-est de la mer Égée le 5 octobre 2026. Ce sont des mesures différentes au sein d’une même fiche d’activité datée.","Une identification/interception de routine a été signalée. Une rencontre avec un avion de chasse dans le compte rendu portant sur des aéronefs de types divers n’est pas établie comme un engagement d’UAV. Les trajectoires exactes et le bulletin GEETHA d’origine n’ont pas été obtenus ; l’évaluation de l’espace aérien reste attribuée à la Grèce."]},"N111":{"headline":"La Grèce signale cinq UAV turcs et neuf violations de l’espace aérien le 20 octobre","description":"Des comptes rendus militaires grecs recensent cinq UAV turcs, neuf violations de l’espace aérien national et huit infractions à la FIR d’Athènes en mer Égée le 20 octobre 2026.","summary":["Des comptes rendus militaires grecs, reproduits par OnAlert, ProtoThema et NewsIT, recensent cinq UAV turcs, neuf violations de l’espace aérien national et huit infractions à la FIR d’Athènes dans le nord-est / centre / sud-est de la mer Égée le 20 octobre 2026. Ce sont des mesures différentes au sein d’une même fiche d’activité datée.","Le CN-235, avec ses cinq violations de l’espace aérien et ses deux infractions à la FIR, est exclu. ProtoThema concorde avec les chiffres de cinq UAV / neuf violations ; NewsIT est traité comme une couverture dérivée. Les trajectoires exactes et le bulletin GEETHA d’origine n’ont pas été obtenus ; l’évaluation de l’espace aérien reste attribuée à la Grèce. Thestival a été ajouté lors de la relecture et concorde aussi avec les chiffres de cinq UAV / neuf violations ; il ne donne que le total mixte de la FIR. Aucun incident supplémentaire n’est créé."]},"N112":{"headline":"Signalement de frappe de drone sur le KHORYV : une inspection de la marine trouve l’épave entièrement immergée","description":"Le KHORYV aurait été touché au large le 23 octobre. Une inspection navale du 19 novembre aurait trouvé l’épave entièrement immergée. Le résultat final des recherches est inconnu.","summary":["Le KHORYV a été signalé touché par un drone et a pris feu au large de Constanța le 23 octobre avant de chavirer. Le NAVWARN 766/26 décrit l’observation, datée du 28 octobre à 18:00 UTC, d’une épave chavirée, semi-immergée et à la dérive. Le 29 octobre, bTV, citant le ministère bulgare de la Défense, a fait état d’une immersion partielle et d’un danger persistant ; Maritime.bg a ensuite rapporté, dans une nouvelle mise à jour du 1er novembre, que la poupe était échouée et la proue encore visible. Maritime.bg, citant une confirmation du service de presse du ministère bulgare de la Défense, a rapporté qu’une inspection navale du 19 novembre avait trouvé l’épave entièrement immergée au large de Shabla, sous environ 50 mètres d’eau. L’heure précise du naufrage et l’annulation de l’avertissement antérieur n’ont pas été vérifiées. Ces observations ultérieures de l’épave ne déplacent pas le lieu de la frappe initiale en mer.","La Roumanie fait état de treize membres d’équipage : neuf secourus, un mort et trois disparus. L’Ukraine confirme un décès ukrainien mais fait état de quatorze membres d’équipage ; l’écart reste non résolu. Les avis donnent des positions datées du chavirement et de l’épave à la dérive qui a suivi, et non une coordonnée de frappe vérifiée. L’attribution à un opérateur et le résultat final des recherches restent non résolus.","La Bulgarie a annoncé une surveillance et une inspection navale prévue le 27 octobre. Le lendemain matin, son ministre de la Défense a déclaré que l’épave entrait dans la mer territoriale bulgare. Il s’agit de signalements ultérieurs de l’épave à la dérive, et non d’une nouvelle attaque ni d’un changement du lieu de la frappe initiale en mer.","bTV a fait état de la présence du Reshitelni sur place et d’opérations suspendues en raison du mauvais temps ; Maritime.bg a décrit des tentatives de sabordage. Il s’agit toujours de suivis du même événement, et non d’une nouvelle attaque ni d’une résolution du sort des disparus."]},"N113":{"headline":"La Grèce signale 8 UAV turcs et 12 violations de l’espace aérien le 21 octobre","description":"Des comptes rendus militaires grecs recensent 8 UAV turcs, 12 violations de l’espace aérien national et 9 infractions à la FIR d’Athènes le 21 octobre 2026.","summary":["Les autorités grecques ont signalé 8 UAV turcs dans le nord-est / centre / sud-est de la mer Égée le 21 octobre 2026, avec 12 violations de l’espace aérien national et 9 infractions à la FIR d’Athènes. Il s’agit d’une fiche datée unique ; les trois décomptes mesurent des choses différentes.","Les six F-16 d’accompagnement, avec leurs cinq violations de l’espace aérien et leurs deux infractions à la FIR, sont exclus. Les UAV ont été identifiés et interceptés ; aucun engagement armé, aucune victime ni aucun dégât n’ont été signalés. L’évaluation de l’espace aérien reste attribuée à la Grèce. Militaire et NewsIT reproduisent des chiffres concordants propres aux UAV ; To Vima corrobore les huit UAV et l’activité régionale mais donne des totaux combinés pour les aéronefs. Le bulletin GEETHA d’origine et les trajectoires précises n’ont pas été obtenus."]},"N114":{"headline":"La Grèce signale 5 UAV turcs et 3 violations de l’espace aérien le 22 octobre","description":"Des comptes rendus militaires grecs recensent 5 UAV turcs, 3 violations de l’espace aérien national et 7 infractions à la FIR d’Athènes le 22 octobre 2026.","summary":["Les autorités grecques ont signalé 5 UAV turcs dans le centre / sud-est de la mer Égée le 22 octobre 2026, avec 3 violations de l’espace aérien national et 7 infractions à la FIR d’Athènes. Il s’agit d’une fiche datée unique ; les trois décomptes mesurent des choses différentes.","Deux F-16 d’accompagnement et un ATR-72, responsables de trois autres infractions à la FIR, sont exclus. Les UAV ont été identifiés et interceptés ; aucun engagement armé, aucune victime ni aucun dégât n’ont été signalés. L’évaluation de l’espace aérien reste attribuée à la Grèce. TheOpinion et Edolio5 reproduisent des chiffres concordants, avec un texte très proche ; ils ne sont pas traités comme une vérification indépendante des trajectoires de vol. Le bulletin GEETHA d’origine et les trajectoires précises n’ont pas été obtenus."]},"N115":{"headline":"Des fragments de drone non identifié trouvés près de Moșești, dans le département de Buzău","description":"Des fragments de drone ont été trouvés près de Moșești, en Roumanie, le 21 octobre 2026. Aucun explosif n’a été trouvé ; l’origine et la date de l’écrasement restent non résolues.","summary":["Un habitant a trouvé ce qui semblait être des restes de drone dans un champ à l’extérieur de Moșești, commune de Robeasca, le 21 octobre 2026. Le préfet a décrit des fragments de moteur, de fuselage et d’hélice dispersés sur environ 100 mètres carrés. Des spécialistes du MApN et du SRI ont enquêté.","Les premières vérifications n’ont trouvé aucun élément explosif. Il s’agit d’une fiche de récupération provisoire : l’implication étrangère, l’identité de l’aéronef et la date de l’écrasement restent non résolues. La carte utilise la date de la découverte et un point d’ancrage approximatif au village."]},"N116":{"headline":"Un aéronef en mousse non armé trouvé à Lubaczów ; origine non résolue","description":"Une cellule en mousse a été trouvée à Lubaczów le 21 octobre 2026. La Police militaire n’a trouvé aucun explosif ; l’origine et tout lien étranger restent inconnus.","summary":["Des débris ont été signalés sur une propriété inoccupée de la rue Herzoga, à Lubaczów, peu après 13:00 le 21 octobre 2026. Des habitants voisins ont été évacués pendant que des spécialistes évaluaient d’éventuels dangers ; aucun blessé ni dégât matériel n’ont été signalés.","La Police militaire a identifié une cellule en mousse non armée et a exclu les explosifs et les dangers radiologiques, biologiques ou chimiques le 22 octobre. L’article de Radio Lublin du 22 octobre cite le porte-parole du parquet, selon lequel le drone avait été transféré au contre-espionnage militaire et son colis envoyé pour analyse ; le communiqué primaire du même jour décrit encore le transfert comme à venir. L’évaluation préliminaire de courte portée n’établit ni l’origine ni une entrée étrangère. Cela reste une seule piste de récupération provisoire."]},"N117":{"headline":"La Grèce signale six UAV turcs et treize violations de l’espace aérien le 23 octobre","description":"Des comptes rendus grecs recensent six UAV turcs, treize violations de l’espace aérien national et neuf infractions à la FIR d’Athènes le 23 octobre 2026.","summary":["Le compte rendu militaire grec reproduit par OnAlert et NewsIT recense six UAV turcs, treize violations de l’espace aérien national et neuf infractions à la FIR d’Athènes dans le nord-est, le centre et le sud-est de la mer Égée le 23 octobre 2026. Ce sont des mesures distinctes au sein d’une même fiche d’activité quotidienne.","Un CN-235, avec ses deux infractions à la FIR, est exclu. Une identification et une interception ont été signalées, mais aucun engagement armé d’UAV n’est établi. Les trajectoires de vol, les heures et les charges restent inconnues ; l’évaluation de l’espace aérien est attribuée à la Grèce, et le bulletin militaire d’origine n’a pas été obtenu directement."]},"N119":{"headline":"UAV ukrainien trouvé à Iitti le 11 avril","description":"Les enquêteurs finlandais ont établi qu’un UAV militaire récupéré à Iitti le 11 avril 2026 était d’origine ukrainienne. Ses dates d’entrée et d’écrasement restent inconnues.","summary":["Les enquêteurs finlandais ont identifié l’UAV trouvé à Iitti le 11 avril 2026 comme le quatrième drone du printemps récupéré. Ils ont établi une origine ukrainienne et une entrée non autorisée, le brouillage et la météo étant à l’origine des déviations du printemps, et non la Finlande comme cible visée.","Il s’agit d’une fiche de récupération unique, distincte des découvertes de mars. La date de découverte n’est pas une date de vol ou d’écrasement établie ; le site exact et la méthode d’élimination individuelle restent non résolus."]},"N120":{"headline":"Des débris d’UAV étranger trouvés dans la paroisse de Liepna, en Lettonie","description":"Les autorités lettones ont confirmé la découverte de débris d’un UAV étranger dans la paroisse de Liepna le 24 octobre. Son origine, ses intentions et sa date d’arrivée précise restent non résolues.","summary":["Les forces armées lettones ont confirmé la découverte d’un UAV étranger dans la paroisse de Liepna le 24 octobre. La police a vérifié des débris en forêt ; aucun blessé civil, dommage aux infrastructures ni danger persistant n’ont été signalés.","Les autorités ont dit qu’il avait peut-être pénétré dans l’espace aérien letton le 18 octobre. La fiche utilise la date de découverte confirmée, et non une date d’écrasement supposée. L’origine nationale, l’opérateur, l’itinéraire et les intentions restent inconnus.","L’hypothèse avancée par un ministre selon laquelle un drone ukrainien aurait pu être endommagé au-dessus de la Russie et avoir plané jusqu’en Lettonie est explicitement conditionnelle ; elle n’établit ni l’origine ni l’itinéraire."]},"N121":{"headline":"La Grèce signale 7 UAV turcs et 6 violations de l’espace aérien le 24 octobre","description":"Des comptes rendus grecs recensent 7 UAV turcs, 6 violations de l’espace aérien national et 11 infractions à la FIR d’Athènes le 24 octobre 2026.","summary":["Le compte rendu militaire grec du 24 octobre 2026 fait état de 7 UAV turcs, 6 violations de l’espace aérien national et 11 infractions à la FIR d’Athènes dans le nord-est, le centre et le sud-est de la mer Égée. Il s’agit d’une fiche d’activité quotidienne, et non de la somme des trois mesures.","Flight et Veteranos publient des comptes rendus concordants attribués au GEETHA. Le bulletin d’origine n’a pas été obtenu directement, et les publications ne sont pas des observations de vol indépendantes. Une identification et une interception ont été signalées, sans engagement armé signalé ; les trajectoires précises, les heures et les charges restent inconnues."]},"N122":{"headline":"La Grèce signale 11 UAV turcs et 18 violations de l’espace aérien le 25 octobre","description":"Des comptes rendus grecs recensent 11 UAV turcs, 18 violations de l’espace aérien national et 13 infractions à la FIR d’Athènes le 25 octobre 2026.","summary":["Le compte rendu militaire grec du 25 octobre 2026 fait état de 11 UAV turcs, 18 violations de l’espace aérien national et 13 infractions à la FIR d’Athènes dans le nord-est, le centre et le sud-est de la mer Égée. Il s’agit d’une fiche d’activité quotidienne, et non de la somme des trois mesures.","Dnews et The Press Room publient des comptes rendus concordants attribués au GEETHA. Le bulletin d’origine n’a pas été obtenu directement, et les publications ne sont pas des observations de vol indépendantes. Une identification et une interception ont été signalées, sans engagement armé signalé ; les trajectoires précises, les heures et les charges restent inconnues."]},"N123":{"headline":"La Grèce signale trois UAV turcs et trois violations de l’espace aérien le 26 octobre","description":"Des comptes rendus grecs recensent trois UAV, trois violations de l’espace aérien et une infraction à la FIR par un UAV le 26 octobre 2026 ; les décomptes d’aéronefs pilotés restent séparés.","summary":["Le compte rendu attribué au GEETHA pour le 26 octobre recense trois UAV turcs, trois violations de l’espace aérien national et une infraction à la FIR par un UAV dans le nord-est et le sud-est de la mer Égée. Deux autres infractions à la FIR concernent un ATR-72 piloté, et non des drones.","NewsIT et OnAlert reproduisent le même compte rendu officiel plutôt que des observations indépendantes. Une identification et une interception ont été signalées, sans engagement armé. Il s’agit d’une fiche d’activité quotidienne, et non d’une somme des décomptes d’aéronefs et de franchissements."]},"N124":{"headline":"Le CONTSHIP JET frappé par des drones de surface au large ; équipage secouru, le navire a ensuite coulé","description":"Les autorités bulgares font état d’une frappe de drones de surface contre le CONTSHIP JET le 28 octobre. Les 18 membres d’équipage ont été secourus ; Varna Radio confirme son naufrage ultérieur.","summary":["Les autorités de défense bulgares indiquent que la surveillance de la marine et un avion de patrouille français ont observé une attaque de drones de surface contre le CONTSHIP JET à 12:00, heure locale (10:00 UTC), le 28 octobre, avec trois impacts observés. Varna Radio situe la frappe à 43°15′N, 028°48′E, au large du cap Kaliakra. Il s’agit d’un seul événement en mer concernant la marine marchande, et non d’une incursion confirmée sur le territoire bulgare.","Les autorités de la défense et des transports confirment que les 18 membres d’équipage ont été secourus. Le NAVWARN 768/26 de Varna Radio confirme que le navire a ensuite coulé à 20:30 UTC le 28 octobre, par 43°07.80′N, 028°45.36′E, avec plus de 20 conteneurs à la dérive, dont des marchandises dangereuses. Cela remplace le signalement officieux antérieur du naufrage.","L’opérateur des drones, l’origine du lancement et le mobile restent inconnus. Reuters fait état de l’évaluation provisoire d’Ambrey, fondée sur des vidéos, d’une conception probablement dérivée du Murena-300S ; il ne s’agit pas d’une identification confirmée du modèle ou de l’opérateur. Les trois drones signalés et les trois impacts observés ne sont pas des incidents distincts. La position ultérieure du naufrage ne remplace pas la coordonnée initiale de la frappe.","Des avertissements de navigation du 1er novembre ont signalé des conteneurs à la dérive près de la baie de Bourgas. Leur lien avec le CONTSHIP JET reste provisoire. Le 3 novembre, l’administration régionale de Bourgas a fait état de trois objets sous surveillance près d’Oasis–Arapya, de Kamennite Korabi à Sinemorets et de Butamyata. Les informations du manifeste décrivaient une cargaison non dangereuse et une citerne vide ; à ce moment-là, le contenu physique et le navire d’origine faisaient encore l’objet d’une enquête. Les prélèvements et la garde des objets se sont poursuivis, sans qu’aucun feu vert d’un laboratoire ne soit signalé. Il s’agit de suivis liés aux risques de la cargaison, et non de nouvelles attaques de drones ni d’un total cumulé de conteneurs.","Le 4 novembre, le gouverneur a déclaré à bTV que la météo et l’accès difficile retardaient la récupération. L’emplacement du troisième conteneur était inconnu, les eaux turques n’étant qu’une possibilité. Aucun feu vert d’un laboratoire n’a été fourni.","L’autorité maritime du Libéria a indiqué que l’équipage était sain et sauf, sans blessés signalés, dans un bulletin décrivant un navire non nommé dont la date, le pavillon, la classe et les trois impacts signalés correspondent aux récits bulgares qui nomment le navire. La municipalité de Tsarevo a indiqué le 12 novembre que des équipes avaient retiré des sacs de piment rouge des deux plages de Lipite. Le lien de la cargaison avec le CONTSHIP JET restait provisoire, et l’annonce ne fournissait pas de résultats de laboratoire.","Le 24 novembre, les autorités ont ouvert le conteneur qui s’était échoué près de Tsarevo le 2 novembre. Le gouverneur de Bourgas a déclaré à la BTA qu’il contenait environ 80 cartons de décorations de Noël correspondant au manifeste. Contships Management a déclaré à Reuters ne pas pouvoir confirmer que le conteneur se trouvait à bord du CONTSHIP JET. L’ouverture n’établit ni le navire d’origine, ni le reste de la cargaison, ni les résultats concernant la pollution."]},"N125":{"headline":"Un UAV récupéré près d’Osieka après un franchissement depuis la Russie signalé par le parquet","description":"Le parquet fait état d’un franchissement non autorisé de la frontière russo-polonaise le 8 mai ; l’UAV non armé a été récupéré près d’Osieka le 9 mai. L’opérateur reste inconnu.","summary":["Un UAV de reconnaissance non armé a été récupéré intact après sa découverte par un civil dans un champ près d’Osieka le 9 mai. Le 11 mai, le porte-parole du parquet d’Olsztyn a déclaré que les enquêteurs étaient certains qu’il avait franchi la frontière russo-polonaise et a daté au 8 mai le franchissement faisant l’objet de l’enquête.","Le fondement probatoire de cette conclusion sur le franchissement n’a pas été divulgué. L’opérateur, la fabrication, la cible visée, la trajectoire précise et l’heure de l’écrasement restent non résolus. Les affirmations des médias concernant des caméras et des marquages cyrilliques n’ont pas été confirmées par le parquet. Il s’agit d’un seul événement rétrospectif, et non d’une nouvelle activité en octobre."]},"N126":{"headline":"Des fragments d’UAV récupérés sur la plage de Popski ; origine non résolue","description":"Une équipe de la marine a récupéré des pièces d’UAV sur la plage de Popski, à Tsarevo, le 21 octobre, selon une réponse du ministère de la Défense. La date du vol et l’origine nationale restent inconnues.","summary":["OFFNews cite le ministère bulgare de la Défense, qui confirme qu’une équipe de la marine a examiné et collecté des pièces d’UAV sur la plage de Popski le 21 octobre et les a transportées à la base. Cela date une opération de récupération, et non un vol ou un écrasement.","Le ministère a explicitement distingué cette récupération d’une allégation non vérifiée concernant Arapya, à proximité. Le modèle, l’origine, l’opérateur, la charge et le mode d’arrivée restent non résolus. Cette piste de récupération provisoire n’est ni une incursion étrangère confirmée ni la preuve d’une autre cellule distincte."]},"N127":{"headline":"Des fragments de drone signalés sur la plage de Listi ; date de récupération inconnue","description":"La BNR a fait état d’une aile et d’une section de fuselage collectées sur la plage de Listi, près de Sinemorets. Le 28 octobre est la date de publication, non une date de découverte vérifiée.","summary":["Le correspondant de la BNR à Bourgas a fait état d’une aile et d’une section de fuselage trouvées sur la plage de Listi et collectées par la Police des frontières après signalement. L’article a été publié le 28 octobre mais ne fournit aucune date exacte de découverte ou de récupération ; le registre utilise la date du reportage comme approximation explicite.","L’origine, le modèle, l’opérateur, la charge et la date du vol ou de l’écrasement restent non résolus. Cette piste de récupération provisoire se distingue de la plage de Popski par le lieu signalé, mais l’existence d’une autre cellule unique n’est pas établie. L’allégation d’attribution concernant Arapya, à proximité, n’est pas transposée à ces fragments."]},"N128":{"headline":"La Grèce signale cinq UAV turcs dans 13 violations de l’espace aérien en mer Égée","description":"Des comptes rendus militaires grecs attribuent 13 violations de l’espace aérien national à cinq UAV turcs le 30 octobre. Une seule fiche quotidienne ; les trajectoires exactes ne sont pas publiées.","summary":["Des chiffres militaires grecs communiqués le 30 octobre attribuent 13 violations de l’espace aérien national et 11 infractions à la FIR d’Athènes à cinq UAV turcs dans le nord-est, le centre et le sud-est de la mer Égée. L’évaluation de l’espace aérien national et l’attribution militaire sont celles de la Grèce ; les trajectoires précises restent non publiées.","Il s’agit d’une seule fiche régionale quotidienne, et non de 13 attaques. Les infractions d’aéronefs pilotés et les deux engagements figurant dans le compte rendu quotidien mixte ne prouvent ni l’armement d’UAV, ni un engagement par des armes, ni un abattage. Les modèles exacts, les charges et les cibles visées restent inconnus."]},"N129":{"headline":"La Roumanie confirme deux entrées non autorisées de drones dans le nord-est du pays","description":"La Roumanie signale deux entrées de drones le 31 octobre. L’un est reparti ; l’autre a été observé pour la dernière fois près de Vaslui et de Bacău. Aucun écrasement n’a été signalé.","summary":["Le ministère roumain de la Défense confirme que deux drones sont entrés dans l’espace aérien national, dans le nord-est, le soir du 31 octobre 2026. L’un est reparti ; l’autre a été observé pour la dernière fois entre les départements de Vaslui et de Bacău. Aucun écrasement n’avait été signalé au moment de la publication.","Quatre F-16 et un IAR-330 SOCAT ont décollé, et les alertes publiques ont pris fin à 19:19, heure locale. Il s’agit d’un seul événement impliquant deux drones, et non de deux attaques vérifiées. L’opérateur, le modèle, l’intention et les cibles restent inconnus ; le point d’ancrage sur la carte est approximatif.","Selon le directeur de l’aéroport de Iași, un vol Wizz Air en provenance d’Eindhoven a été dérouté vers Suceava pendant la fermeture temporaire de l’espace aérien. Cette perturbation relève du même épisode, et non d’une autre incursion."]},"N130":{"headline":"La Lettonie évalue l’UAV qui a traversé son territoire le 1er novembre comme probablement un Geran russe","description":"Les NBS évaluent l’UAV qui a traversé la Lettonie le 1er novembre comme probablement un Geran russe. Il est reparti vers la Russie ; une éventuelle charge explosive et l’intention restent inconnues.","summary":["Les responsables ont décrit un drone traversant l’est de la Lettonie depuis la Biélorussie et repartant vers la Russie à 19:16 le 1er novembre. Les NBS l’ont ensuite évalué comme probablement un Geran russe après avoir analysé les données des capteurs et de l’intercepteur et consulté des partenaires ukrainiens.","La Lettonie a fait s’autodétruire son propre intercepteur à 19:19. Il ne s’agissait pas d’un abattage signalé de l’UAV détecté. Les NBS ne peuvent pas établir si cet UAV transportait des explosifs ; l’opérateur, l’intention et la cible restent non confirmés."]},"N131":{"headline":"Alerte dans le nord de Tulcea ; aucune entrée dans l’espace aérien roumain signalée","description":"La Roumanie a émis une alerte pour le nord du département de Tulcea le 2 novembre après des attaques à proximité en Ukraine. Le MApN n’a signalé aucune entrée dans l’espace aérien national roumain.","summary":["Le nord du département de Tulcea a reçu une alerte RO-Alert à 04:11 le 2 novembre après des attaques de drones contre des ports ukrainiens du Danube. La Roumanie a déployé des F-16 et un hélicoptère Puma SOCAT ; l’alerte a pris fin à 05:26, heure locale.","Le MApN n’a signalé aucune entrée dans l’espace aérien roumain. Il s’agit d’une alerte de protection civile, et non d’une incursion ou d’une attaque confirmée en Roumanie. Le point sur la carte représente la zone d’alerte."]},"N132":{"headline":"La Lettonie confirme la détection d’un UAV ; origine et possible chute à Balvi non résolues","description":"Les NBS confirment la présence d’un UAV en Lettonie le 3 novembre. Il ressemblait visuellement à des drones militaires ukrainiens, mais le type, l’origine et une possible chute à Balvi restent non confirmés.","summary":["Les NBS confirment qu’un UAV a été détecté dans l’espace aérien letton lors de l’alerte Balvi–Ludza du 3 novembre. Selon l’identification visuelle initiale, il ressemblait à des UAV militaires ukrainiens, mais les forces armées n’ont explicitement pas pu en confirmer le type ni l’origine.","L’UAV est peut-être tombé dans la municipalité de Balvi ; les recherches au sol se sont poursuivies. Cela reste une piste dont l’origine et l’issue ne sont pas résolues, et non une incursion étrangère, un écrasement ou un abattage confirmés. Le point régional sur la carte n’est pas un site d’écrasement vérifié."]},"N133":{"headline":"Alerte nocturne à Tulcea : aucune entrée dans l’espace aérien roumain signalée","description":"Le nord du département de Tulcea a reçu une alerte tard le 2 novembre après une activité aérienne au-dessus de l’Ukraine. Le MApN n’a signalé aucune entrée en Roumanie ; l’alerte a pris fin après minuit.","summary":["Le MApN a signalé deux cibles radar au-dessus de l’Ukraine, près d’Izmail et de Chilia, dans la nuit du 2 au 3 novembre. Le nord du département de Tulcea a reçu une alerte RO-Alert à 23:43 ; l’alerte a pris fin à 00:21, heure locale. Deux F-18 espagnols ont décollé en réponse.","Aucune entrée dans l’espace aérien roumain n’a été signalée. Il s’agit d’une alerte de protection civile sélectionnée, distincte de l’alerte antérieure du 2 novembre, et non d’une incursion ou d’une attaque confirmée en Roumanie. Le point d’ancrage sur la carte représente la zone d’alerte."]},"N134":{"headline":"Alerte dans le nord de Tulcea le 4 novembre ; aucune entrée en Roumanie signalée","description":"Une cible au-dessus de l’Ukraine a entraîné le décollage de deux F-16 et une alerte dans le nord du département de Tulcea le 4 novembre. Le MApN n’a signalé aucune entrée dans l’espace aérien roumain.","summary":["Le nord du département de Tulcea a reçu une alerte RO-Alert à 10:57 le 4 novembre après la détection d’une cible radar au nord de Vîlcove, en Ukraine. Deux F-16 ont décollé de Borcea.","Le MApN n’a signalé aucune entrée dans l’espace aérien roumain. Cette alerte sélectionnée est distincte de l’alerte nocturne du 2 au 3 novembre ; le point sur la carte représente la zone d’alerte."]},"N135":{"headline":"Des fragments de drone trouvés à Boghicea ; neutralisation contrôlée signalée","description":"Des fragments de drone trouvés à Boghicea le 5 novembre auraient été détruits le soir même. L’origine et tout lien avec le vol du 31 octobre restent non résolus.","summary":["Un habitant a prévenu la police rurale de Sagna après avoir trouvé des fragments éparpillés à Boghicea. La police, les pompiers et des spécialistes du SRI se sont rendus sur place. ProTV rapporte que des spécialistes ont fait exploser les restes le soir du 5 novembre, après examen et une alerte RO-Alert.","L’origine étrangère, la date de la chute et tout lien avec N129 restent non confirmés. ProTV fournit un compte rendu clair de l’achèvement de la neutralisation ; aucune déclaration officielle directe d’achèvement n’a été obtenue. Les inscriptions décrites par des témoins oculaires n’établissent ni l’opérateur ni le modèle.","Une seule fiche de découverte, et non un vol nouvellement vérifié ni un UAV supplémentaire dans le décompte. Un éventuel lien avec N129 reste non résolu ; à fusionner ou à croiser si des éléments établissent plus tard qu’il s’agit du même drone. L’intervention d’urgence et l’alerte de neutralisation ne sont pas des événements distincts."]},"N136":{"headline":"Tulcea · Alerte RO-Alert dans la nuit du 6 novembre","description":"Alerte officielle ; aucune entrée dans l’espace aérien roumain signalée. Alerte uniquement ; aucune incursion, aucun engagement ni aucune frappe n’est déduit.","summary":["Des attaques à proximité contre des ports ukrainiens ont entraîné une alerte. Alerte RO-Alert émise à 00:19 ; fin de l’alerte à 00:41, heure locale.","Nombre et modèle des drones non précisés dans le communiqué. Aucune trajectoire de vol, aucun nombre de drones ni aucun modèle établi.","Une seule alerte sélectionnée, distincte de l’alerte N137, plus tard dans la matinée, à 08:56."]},"N137":{"headline":"Nord de Tulcea · Alerte du matin du 6 novembre pour une cible près de Sulina","description":"Alerte officielle pour une cible radar ; entrée en Roumanie non établie. Alerte uniquement ; aucune incursion, aucun engagement ni aucune frappe n’est déduit.","summary":["Une activité aérienne à proximité a entraîné une alerte de protection civile. Deux F-16 ont décollé de Borcea ; l’alerte pour le nord du département de Tulcea a duré de 08:56 à 09:27, heure locale.","Cible radar aérienne ; identification comme drone et modèle non confirmés dans la déclaration citée. Aucun modèle, opérateur ni franchissement de la frontière roumaine vérifié. La conclusion d’absence d’entrée de la nuit relève de N136 et ne peut pas être transposée à cet épisode.","Alerte matinale distincte, et non l’épisode N136 de 00:19–00:41. L’intervention des chasseurs n’ajoute aucun événement."]},"N138":{"headline":"Récupération de drone : Shabla · Drone classé russe échoué sur la côte et détruit, Bulgarie","description":"6 novembre 2026, Shabla · Drone classé russe échoué sur la côte et détruit, Bulgarie. Drone aérien officiellement identifié, récupéré et détruit. Découverte côtière…","summary":["Découverte côtière signalée aux autorités à 10:00, heure locale.","Drone aérien officiellement identifié, récupéré et détruit. La classification russe est l’évaluation de l’inspection bulgare ; opérateur et mission précis non établis. Le premier récit du maire faisant état de marquages Shahed et d’explosifs a été supplanté par l’inspection militaire : aucune inscription et aucune charge explosive. La date de la chute et tout lien avec une attaque contre la navigation restent inconnus."]},"N139":{"headline":"Mer Égée · Activité d’UAV turcs signalée le 6 novembre","description":"Le registre grec signale 10 UAV turcs le 6 novembre. Les chiffres combinés des aéronefs ne concernent pas uniquement des drones.","summary":["Le registre mensuel primaire du GEETHA recense 10 UAV et un ATR-72, avec, tous aéronefs confondus, 15 infractions à la FIR et 23 violations de l’espace aérien national. Le registre ne répartit pas ces totaux mixtes par type d’aéronef.","Le bulletin quotidien reproduit antérieurement attribuait 9 infractions à la FIR et 15 violations de l’espace aérien national à 7 UAV. La raison de cet écart n’est pas indiquée. Ces chiffres proviennent des autorités grecques ; il ne s’agit ni de trajectoires vérifiées de façon indépendante ni d’un nombre confirmé d’attaques."]},"N140":{"headline":"Mer Égée · Activité d’UAV turcs signalée le 5 novembre","description":"Le registre grec signale 5 UAV turcs le 5 novembre. Les chiffres quotidiens antérieurs différaient.","summary":["Le registre mensuel primaire du GEETHA recense 5 UAV et aucun aéronef piloté, avec 8 infractions à la FIR et 17 violations de l’espace aérien national. Tous les aéronefs signalés ce jour-là étaient des UAV.","Le bulletin quotidien reproduit antérieurement attribuait 6 infractions à la FIR et 9 violations de l’espace aérien national à 4 UAV. La raison de cet écart n’est pas indiquée. Ces chiffres proviennent des autorités grecques ; il ne s’agit ni de trajectoires vérifiées de façon indépendante ni d’un nombre confirmé d’attaques."]},"N141":{"headline":"Mer Égée · Activité d’UAV turcs signalée le 7 novembre","description":"Le registre grec signale 8 UAV turcs le 7 novembre. Les chiffres quotidiens antérieurs différaient.","summary":["Le registre mensuel primaire du GEETHA recense 8 UAV et aucun aéronef piloté, avec 10 infractions à la FIR et 8 violations de l’espace aérien national. Tous les aéronefs signalés ce jour-là étaient des UAV.","Le bulletin quotidien reproduit antérieurement attribuait 8 infractions à la FIR et 4 violations de l’espace aérien national à 6 UAV. La raison de cet écart n’est pas indiquée. Ces chiffres proviennent des autorités grecques ; il ne s’agit ni de trajectoires vérifiées de façon indépendante ni d’un nombre confirmé d’attaques."]},"N142":{"headline":"Objet non identifié : eaux territoriales roumaines · Une cible non identifiée entre dans l’espace aérien, Roumanie","description":"5 novembre 2026, eaux territoriales roumaines · Une cible non identifiée entre dans l’espace aérien, Roumanie. Entrée dans l’espace aérien signalée par le MApN ; identification comme drone non confirmée. Une…","summary":["Une entrée de trois minutes dans l’espace aérien national a été signalée par le MApN.","Entrée dans l’espace aérien signalée par le MApN ; identification comme drone non confirmée. Opérateur non identifié. L’entrée est signalée par l’autorité, mais l’identification comme drone, le modèle, l’opérateur et l’intention restent non résolus. Les comptes rendus des médias reproduisent la même déclaration officielle. Aucun lien établi avec Boghicea (N135)."]},"N143":{"headline":"Alerte drone : est de Tulcea · Alerte pour une cible près de l’île des Serpents, Roumanie","description":"8 novembre 2026, est de Tulcea · Alerte pour une cible près de l’île des Serpents, Roumanie. Alerte officielle pour une cible radar ; entrée en Roumanie non établie. Deux détections…","summary":["Deux détections de cibles à proximité ont entraîné une alerte et une surveillance militaire.","Alerte officielle pour une cible radar ; entrée en Roumanie non établie. Opérateur non identifié. Les déclarations citées n’établissent ni l’entrée en Roumanie, ni le type de drone, ni l’opérateur. La disparition de la première cible des écrans radar n’est pas un écrasement. Aucune évaluation explicite d’absence d’entrée n’est déduite du silence."]},"N144":{"headline":"Alerte drone : nord de Tulcea · Alerte pour une cible près de Chilia Veche, Roumanie","description":"8 novembre 2026, nord de Tulcea · Alerte pour une cible près de Chilia Veche, Roumanie. Alerte officielle pour une cible radar ; entrée en Roumanie non établie. Une détection ultérieure…","summary":["Une détection de cible ultérieure et distincte a entraîné une alerte dans le nord du département de Tulcea.","Alerte officielle pour une cible radar ; entrée en Roumanie non établie. Opérateur non identifié. Le type de cible, l’opérateur et tout franchissement de la frontière roumaine restent non établis. Une alerte et un décollage de chasseurs ne constituent pas à eux seuls une incursion ou un engagement."]},"N145":{"headline":"Objet non identifié : plage de Lipite, Sinemorets · Découverte d’un drone non identifié, Bulgarie","description":"8 novembre 2026, plage de Lipite, Sinemorets · Découverte d’un drone non identifié, Bulgarie. Découverte d’un drone et collecte officielle attribuée ; origine non résolue. Une équipe de la BNT…","summary":["Une équipe de la BNT a trouvé l’appareil alors qu’elle faisait un reportage sur une cargaison échouée sur la côte.","Découverte d’un drone et collecte officielle attribuée ; origine non résolue. Origine nationale et opérateur non résolus ; aucun vol étranger ni aucune entrée transfrontalière confirmés. L’origine, l’opérateur, la charge et la voie d’arrivée restent non résolus. La cargaison à proximité ne constitue pas un élément reliant le drone à un navire ou à une attaque. L’évaluation du gouverneur liée au contexte de guerre n’est pas une identification technique. Aucune neutralisation achevée n’est établie."]},"N146":{"headline":"Mer Égée · Activité d’UAV turcs signalée le 8 novembre","description":"Le registre grec signale 5 UAV turcs le 8 novembre. Les chiffres quotidiens antérieurs différaient.","summary":["Le registre mensuel primaire du GEETHA recense 5 UAV et aucun aéronef piloté, avec 6 infractions à la FIR et 6 violations de l’espace aérien national. Tous les aéronefs signalés ce jour-là étaient des UAV.","Le bulletin quotidien reproduit antérieurement attribuait 4 infractions à la FIR et 4 violations de l’espace aérien national à 4 UAV. La raison de cet écart n’est pas indiquée. Ces chiffres proviennent des autorités grecques ; il ne s’agit ni de trajectoires vérifiées de façon indépendante ni d’un nombre confirmé d’attaques."]},"N147":{"headline":"Mer Égée · Activité d’UAV turcs signalée le 9 novembre","description":"Le registre grec signale 5 UAV turcs le 9 novembre. Les chiffres combinés des aéronefs ne concernent pas uniquement des drones.","summary":["Le registre mensuel primaire du GEETHA recense 5 UAV et un ATR-72, avec, tous aéronefs confondus, 7 infractions à la FIR et 3 violations de l’espace aérien national. Le registre ne répartit pas ces totaux mixtes par type d’aéronef.","Le bulletin quotidien reproduit antérieurement attribuait 5 infractions à la FIR et 2 violations de l’espace aérien national à 5 UAV. La raison de cet écart n’est pas indiquée. Ces chiffres proviennent des autorités grecques ; il ne s’agit ni de trajectoires vérifiées de façon indépendante ni d’un nombre confirmé d’attaques."]},"N148":{"headline":"Vol de drone : Sulina · Entrée signalée d’un drone dans l’espace aérien, Roumanie","description":"9 novembre 2026, Sulina · Entrée signalée d’un drone dans l’espace aérien, Roumanie. Entrée d’un drone dans l’espace aérien national roumain signalée par le MApN. Des informations ultérieures…","summary":["Des informations ultérieures confirment explicitement l’entrée après l’alerte initiale pour une cible à proximité. La trajectoire a ensuite disparu des écrans radar.","Entrée d’un drone dans l’espace aérien national roumain signalée par le MApN. Opérateur, origine nationale, cible visée et intention non établis. Les sources relaient des informations du ministère de la Défense, et non des trajectoires radar vérifiées de façon indépendante. Heure et durée de l’entrée, modèle, opérateur, cible et issue finale inconnus. La perte du contact radar ne prouve ni un écrasement, ni un abattage, ni une sortie."]},"N149":{"headline":"Alerte drone : est de Tulcea · Alerte du 10 novembre pour une cible près de Sulina, Roumanie","description":"10 novembre 2026, est de Tulcea · Alerte du 10 novembre pour une cible près de Sulina, Roumanie. Cible aérienne à proximité signalée par le MApN ; entrée en Roumanie non établie. Une cible…","summary":["Une cible à proximité a entraîné le décollage de deux F-16 et une alerte publique dans l’est du département de Tulcea.","Cible aérienne à proximité signalée par le MApN ; entrée en Roumanie non établie. Opérateur, origine, cible visée et intention inconnus. Aucune entrée en Roumanie, aucune attaque, aucune interception ni aucun écrasement confirmé n’est établi pour cet épisode. Les informations sur une entrée le 9 novembre relèvent de N148 et ne peuvent pas être transposées à cette alerte."]},"N150":{"headline":"Lituanie–Lettonie · Incursion d’un drone et interception infructueuse","description":"Incursion de drone officiellement confirmée ; interception infructueuse. Du sud au nord de la Lituanie ; sortie signalée vers la Lettonie près du district de Pasvalys.","summary":["Le chef d’état-major de la défense lituanienne a déclaré que des chasseurs avaient identifié le drone près de Kaunas mais ne l’avaient pas engagé à cet endroit en raison du risque pour les civils. Deux tentatives de destruction ultérieures ont échoué. La Lettonie a confirmé de manière indépendante qu’un drone était entré depuis la Lituanie et avait traversé son territoire du sud au nord.","Des chasseurs de l’OTAN ont été activés en Lituanie et ont poursuivi leur intervention au-dessus de la Lettonie ; pas de conditions opérationnelles sûres et adaptées pour une destruction en Lettonie. Des débris d’un missile intercepteur ont été récupérés près de Biržai ; il ne s’agit pas d’une épave de drone.","Le modèle, la charge, l’opérateur, la cible visée et la cause restent inconnus. Un détournement par la guerre électronique est une évaluation, et non un fait établi. Les autorités estoniennes ont confirmé séparément de brèves entrées cette nuit-là ; le recoupement exact avec cette trajectoire et d’autres drones reste en cours de rapprochement. Aucune attaque, aucun écrasement de drone, aucune récupération ni aucun abattage confirmés."]},"N151":{"headline":"Lettonie · Deux brèves entrées de drones à la frontière orientale","description":"Brèves incursions de drones confirmées par les NBS. Municipalité de Ludza / frontière orientale de la Lettonie","summary":["Les NBS lettones ont déclaré que deux drones avaient brièvement franchi la frontière orientale pendant 1 à 2 minutes. Elles situent l’alerte associée à Ludza vers 23:30 le mardi 10 novembre.","Des unités d’intercepteurs de drones et de défense aérienne ainsi que des chasseurs de l’OTAN ont été activés.","Les points de franchissement exacts, l’opérateur, la charge et l’intention restent non résolus. Les approches ultérieures vers Krāslava/Augšdaugava et Balvi n’ont pas donné lieu à une entrée ; il ne s’agit pas d’incursions supplémentaires."]},"N152":{"headline":"Finlande · Entrée présumée d’un UAV au-dessus de l’est du golfe","description":"Violation présumée de l’espace aérien signalée par le ministère ; enquête ouverte. Est du golfe de Finlande ; espace aérien national finlandais présumé","summary":["Le ministère finlandais de la Défense a signalé une violation présumée de l’espace aérien par un UAV après 02:00 le 11 novembre, d’une durée d’environ cinq minutes avant le départ de l’appareil.","Les garde-frontières enquêtent. Les Forces de défense ont imposé des restrictions aériennes et maritimes temporaires à titre de précaution.","L’entrée reste présumée, et non confirmée. Aucune origine, aucun modèle ni aucune intention identifiés, et aucun lien prouvé avec des transits dans la région de la Baltique ou des attaques en Russie."]},"N153":{"headline":"Estonie · Brèves incursions de drones au-dessus du golfe de Finlande","description":"Les autorités estoniennes ont signalé de brèves incursions de drones au-dessus du golfe de Finlande le 11 novembre 2026. Le nombre exact, les trajectoires et les charges restent non résolus.","summary":["Dans un entretien accordé à ERR, le ministre de la Défense a distingué de brèves violations de l’espace aérien au-dessus du golfe de Finlande d’un drone distinct entré depuis la Lettonie vers 03:30. Le gouvernement estonien a confirmé séparément que certains drones étaient brièvement entrés dans l’espace aérien national cette nuit-là.","Des chasseurs de l’OTAN étaient en vol. Le ministre a déclaré que les conditions d’une destruction sûre n’étaient pas réunies, notamment en raison de la proximité de la frontière russe.","Le nombre exact de drones, les heures de franchissement et les trajectoires restent non résolus. L’attribution ukrainienne signalée relève du récit du ministre, et non d’une confirmation indépendante. Aucune attaque contre l’Estonie, aucun écrasement, aucune récupération ni aucun abattage confirmés. Aucun lien prouvé avec le franchissement présumé en Finlande."]},"N154":{"headline":"Un possible drone près de Sulina déclenche une alerte ; entrée en Roumanie non établie","description":"Un possible drone au nord-est de Sulina a déclenché une alerte à Tulcea le 12 novembre 2026. Des chasseurs espagnols sont intervenus ; l’entrée en Roumanie n’a pas été établie.","summary":["Le ministère roumain de la Défense a signalé une cible aérienne à environ 28 km au nord-est de Sulina le 12 novembre. La radio publique l’a décrite comme un possible drone.","Une alerte a été en vigueur de 12:35 à 13:12, heure locale, et deux F-18 espagnols ont décollé. Cette alerte sélectionnée n’est ni une incursion ni une attaque confirmée en Roumanie."]},"N155":{"headline":"Signalement : 5 UAV turcs impliqués dans 2 violations de l’espace aérien grec le 16 octobre","description":"Veteranos fait état de 5 UAV turcs et de 2 violations de l’espace aérien grec le 16 octobre 2026. Récit d’une source unique fondé sur des chiffres officiels ; les trajectoires exactes restent inconnues.","summary":["Veteranos fait état de 5 UAV turcs dans le centre et le sud-est de la mer Égée le 16 octobre, citant des chiffres officiels : 2 violations de l’espace aérien national et 7 infractions à la FIR d’Athènes.","Une identification et une interception de routine ont été signalées. Il s’agit d’une seule fiche d’activité quotidienne, et non d’événements distincts pour chaque UAV ou chaque violation.","Le bulletin GEETHA d’origine reste indisponible et aucun second compte rendu concordant n’a été obtenu. Il s’agit de chiffres grecs attribués, et non de trajectoires vérifiées de façon indépendante ; le différend gréco-turc sur l’espace aérien reste pertinent."]},"N156":{"headline":"Signalement : 2 UAV turcs impliqués dans 6 violations de l’espace aérien grec le 17 octobre","description":"Veteranos fait état de 2 UAV turcs et de 6 violations de l’espace aérien grec le 17 octobre 2026. Récit d’une source unique fondé sur des chiffres officiels ; les trajectoires exactes restent inconnues.","summary":["Veteranos fait état de 2 UAV turcs dans le nord-est et le sud-est de la mer Égée le 17 octobre, citant des chiffres officiels : 6 violations de l’espace aérien national et 4 infractions à la FIR d’Athènes.","Une identification et une interception de routine ont été signalées. Il s’agit d’une seule fiche d’activité quotidienne, et non d’événements distincts pour chaque UAV ou chaque violation.","Le bulletin GEETHA d’origine reste indisponible et aucun second compte rendu concordant n’a été obtenu. Il s’agit de chiffres grecs attribués, et non de trajectoires vérifiées de façon indépendante ; le différend gréco-turc sur l’espace aérien reste pertinent."]},"N157":{"headline":"Alerte dans le nord de Tulcea après la détection d’une cible dans l’espace aérien ukrainien","description":"La Roumanie a émis une alerte pour le nord du département de Tulcea le 13 novembre après avoir détecté une cible dans l’espace aérien ukrainien. L’identification comme drone et l’entrée en Roumanie n’ont pas été établies.","summary":["Les autorités roumaines ont émis une alerte pour le nord du département de Tulcea le 13 novembre 2026 après que le radar eut détecté une cible aérienne au sud-est de l’île des Serpents, dans l’espace aérien ukrainien.","Deux F-16 roumains ont décollé de Fetești. L’alerte a été en vigueur de 21:53 à 22:58, heure locale ; il s’agit des heures de l’alerte, et non d’une durée de vol vérifiée.","Le compte rendu du ministère examiné n’a pas identifié la cible comme un drone ni établi une entrée en Roumanie. Il s’agit d’une alerte sélectionnée, et non d’une incursion ou d’une attaque confirmée."]},"N158":{"headline":"Le LARISSA 1 endommagé par un impact de drone signalé au large de la Roumanie ; l’équipage est sain et sauf","description":"Un impact de drone a endommagé le LARISSA 1 au large de Sfântu Gheorghe le 13 novembre. Le ministre roumain a reconnu l’incident ; l’opérateur et la position précise restent non résolus.","summary":["Un impact signalé de drone aérien a endommagé la grue de chargement du LARISSA 1 près de Sfântu Gheorghe le soir du 13 novembre 2026. Les autorités maritimes ont été prévenues vers 21:40, heure locale. Aucun blessé, aucun mort ni aucun incendie n’ont été signalés.","Le 14 novembre, le ministre roumain de la Défense a reconnu l’impact survenu dans la nuit. TVR identifie le navire, tandis qu’Europa FM situe l’incident signalé à 6,8 milles marins au nord-est de Sfântu Gheorghe, dans les eaux territoriales roumaines. Les coordonnées exactes de l’impact n’ont pas été publiées.","L’opérateur, l’origine et la cible visée restent inconnus. Les conclusions techniques étaient en attente, et aucun lien avec l’alerte distincte pour une cible aérienne à Tulcea n’a été établi."]},"N159":{"headline":"Tulcea reçoit deux alertes au cours d’un même épisode matinal de cible aérienne","description":"La Roumanie a émis deux alertes à Tulcea le 14 novembre après la détection d’une cible près de l’île des Serpents. L’identification comme drone et l’entrée en Roumanie n’ont pas été établies.","summary":["Le MApN a signalé une cible aérienne dans la zone de l’île des Serpents le matin du 14 novembre 2026. Deux F-16 roumains ont décollé de Fetești.","L’est du département de Tulcea a reçu une alerte à 04:45, heure locale, puis le nord du département à 05:39. La fin d’alerte a été donnée à 05:52. Ces messages relèvent d’un seul épisode d’alerte, et non de deux événements de drones confirmés.","La déclaration n’a pas identifié la cible comme un drone ni confirmé une entrée en Roumanie. Cette alerte sélectionnée est distincte de l’alerte de la veille au soir ; aucun lien avec l’impact sur le Larissa 1 n’est établi."]},"N160":{"headline":"L’EVIA PETROL V touché par un drone au large de Sulina, selon un compte rendu rapporté du ministère","description":"L’EVIA PETROL V aurait été touché au large de Sulina le 14 novembre. L’équipage a éteint un incendie ; aucune victime n’a été signalée. L’opérateur et la position exacte restent inconnus.","summary":["L’EVIA PETROL V a été touché par un drone vers 21:10, heure locale, le 14 novembre 2026, selon le compte rendu par News.ro d’informations du MApN provenant des autorités maritimes civiles. Le lieu signalé se situait à environ 4 milles marins à l’est-sud-est de Sulina.","L’équipage a éteint un incendie à bord ; aucune victime n’a été signalée. Radio România Constanța évoque les eaux territoriales roumaines, mais les coordonnées exactes de l’impact et la juridiction n’ont pas été vérifiées de façon indépendante.","L’opérateur, l’origine, l’intention et tout lien avec d’autres navires touchés ou des alertes à proximité restent inconnus.","Dans une communication réglementaire du 19 novembre, le groupe Trans-Oil a indiqué que le navire était au mouillage à l’entrée du canal de Sulina, dans l’attente d’une autorisation pour se rendre à Giurgiulești. Les dégâts ont empêché le voyage prévu pour charger environ 6 500 tonnes d’huile de tournesol. La présence de cette cargaison à bord n’a pas été confirmée ; d’éventuels retards et coûts logistiques restent des mises en garde de l’entreprise."]},"N161":{"headline":"Le MARSOL touché par un drone au large de Sulina, selon un compte rendu rapporté du ministère","description":"Le MARSOL aurait été touché au large de Sulina le 14 novembre. L’équipage a éteint un incendie ; aucune victime n’a été signalée. L’opérateur et la position exacte restent inconnus.","summary":["Le MARSOL a été touché par un drone vers 21:45, heure locale, le 14 novembre 2026, selon le compte rendu par News.ro d’informations du MApN provenant des autorités maritimes civiles. Le lieu signalé se situait à environ 5 milles marins au sud-est du canal de Sulina.","L’équipage a éteint un incendie à bord ; aucune victime n’a été signalée. Radio România Constanța évoque les eaux territoriales roumaines, mais les coordonnées exactes de l’impact et la juridiction n’ont pas été vérifiées de façon indépendante.","L’opérateur, l’origine, l’intention et tout lien avec d’autres navires touchés ou des alertes à proximité restent inconnus. Un compte rendu maritime antérieur indique plutôt 21:29 CET ; cet écart d’horaire reste non résolu."]},"N162":{"headline":"Est de Tulcea · Alerte du soir du 14 novembre","description":"Les autorités roumaines ont émis une alerte de protection civile après une détection aérienne. L’identification comme drone et l’entrée en Roumanie restent non confirmées.","summary":["Deux F-16 roumains ont décollé de Fetești ; alerte dans l’est du département de Tulcea à 20:51, fin d’alerte à 21:37.","La terminologie du ministère citée ne confirme ni un drone, ni une entrée, ni une attaque, ni un engagement. Aucun lien démontré avec les frappes contre des navires."]},"N163":{"headline":"Secteur de Sulina · Alerte pour un contact radar tard le 14 novembre","description":"Les autorités roumaines ont émis une alerte de protection civile après une détection aérienne. L’identification comme drone et l’entrée en Roumanie restent non confirmées.","summary":["Nouvelle alerte dans l’est du département de Tulcea à 23:19 ; fin d’alerte à 00:27 le lendemain. Un décollage distinct n’est pas établi.","La terminologie du ministère citée ne confirme ni un drone, ni une entrée, ni une attaque, ni un engagement. Aucun lien démontré avec les frappes contre des navires."]},"N164":{"headline":"Brève incursion d’un drone près de Chilia le 2 mai","description":"Les autorités roumaines de défense ont signalé une brève entrée d’un drone près de Chilia. La cible et l’intention restent non établies ; aucune attaque contre la Roumanie n’est déduite.","summary":["Le MApN a signalé une brève entrée confirmée par radar près de Chilia, suivie d’un déplacement vers Ismail. Deux F-16 ont décollé vers 02:00 ; l’alerte dans le nord du département de Tulcea a été en vigueur de 02:03 à 02:50, heure locale.","L’entrée est consignée séparément de l’attaque plus large contre l’Ukraine. L’intention et la cible précise restent non établies ; aucun impact en Roumanie n’est signalé."]},"N165":{"headline":"Brève incursion d’un drone près de Chilia le 7 mai","description":"Les autorités roumaines de défense ont signalé une brève entrée d’un drone près de Chilia. La cible et l’intention restent non établies ; aucune attaque contre la Roumanie n’est déduite.","summary":["Le MApN a signalé une brève entrée confirmée par radar près de Chilia le matin du 7 mai. Deux F-16 ont décollé à 08:37 ; l’alerte dans le nord du département de Tulcea a été en vigueur de 08:40 à 09:40, heure locale.","L’entrée est consignée séparément de l’attaque plus large contre l’Ukraine. L’intention et la cible précise restent non établies ; aucun impact en Roumanie n’est signalé."]},"N166":{"headline":"Un drone entre dans l’espace aérien roumain et s’écrase près de Parcheș","description":"Le MApN a confirmé l’entrée d’un drone le 26 mars et son écrasement aux abords de Parcheș. Des débris ont été trouvés ; l’opérateur, le modèle et la cible visée restent non précisés.","summary":["Le MApN a signalé l’entrée d’un drone à 00:44 le 26 mars ; il a pénétré d’environ 4 km et s’est écrasé aux abords de Parcheș. Des équipes ont trouvé des débris et de la végétation brûlée ; aucun dégât matériel ni aucune victime n’ont été signalés.","Le ministère a déclaré que la défense aérienne ukrainienne avait détourné le drone. Ce récit reste attribué au MApN ; le communiqué n’établit ni son opérateur, ni son modèle, ni une intention d’attaquer la Roumanie."]},"N167":{"headline":"Une cible non identifiée entre dans l’espace aérien roumain près de Chilia Veche","description":"Le MApN a confirmé l’entrée d’une cible aérienne dans la nuit du 16 au 17 avril. L’identification comme drone et un écrasement restent non confirmés malgré la perte ultérieure du contact radar.","summary":["Le MApN a signalé une entrée dans l’espace aérien national dans la nuit du 16 au 17 avril. Le contact a été perdu à environ 16 km au sud-est de Chilia Veche, et une mission de recherche a été annoncée.","Le communiqué officiel décrit une cible aérienne, et non un drone identifié. Ni la perte du contact radar ni une recherche prévue n’établissent un écrasement ou une récupération de débris."]},"N168":{"headline":"L’ALI NAJAFOV signale un impact de drone dans la nuit près des bouches du Danube","description":"Les autorités roumaines ont relayé un signalement d’impact de drone émanant de l’ALI NAJAFOV. Son équipage a éteint un incendie ; la position précise, la juridiction et l’attribution restent inconnues.","summary":["L’ALI NAJAFOV a signalé un impact de drone dans la nuit du 14 au 15 novembre près des bouches du Danube. Les autorités roumaines ont relayé le signalement du navire ; l’équipage a éteint un incendie et aucune victime n’a été signalée.","Il s’agit d’un navire distinct de l’EVIA PETROL V et du MARSOL. Sa position exacte et la juridiction maritime restent non résolues ; aucun opérateur commun ni aucun ciblage délibéré n’est établi."]},"N169":{"headline":"L’alerte de l’après-midi à Tulcea étendue à la ville, puis levée","description":"La détection d’une cible aérienne près de l’Ukraine a entraîné une alerte à Tulcea à 15:02, étendue à la ville avant la fin d’alerte de 17:05. L’entrée en Roumanie reste non confirmée.","summary":["Une alerte consécutive à la détection d’une cible aérienne en Ukraine a commencé à 15:02 le 15 novembre. Elle a été étendue à la municipalité de Tulcea à 16:56 et levée pour toutes les localités concernées à 17:05.","L’extension relève du même épisode d’alerte. Ni l’identification comme drone ni l’entrée dans l’espace aérien roumain ne sont établies ; aucun lien avec les impacts sur des navires n’est déduit."]},"N170":{"headline":"Nord de Sulina · Brève entrée d’un drone le 26 février","description":"Le MApN a confirmé une brève entrée d’un drone le soir du 26 février, qui a pris fin au nord de Sulina vers 18:30.","summary":["Le MApN a confirmé une brève entrée d’un drone le soir du 26 février, qui a pris fin au nord de Sulina vers 18:30.","Elle était distincte de l’alerte antérieure sans entrée et de l’événement du 25 février. L’opérateur, le modèle et l’intention restent non précisés."]},"N171":{"headline":"Tănăsoaia · Récupération de possibles fragments d’un véhicule aérien","description":"Des spécialistes de la défense ont examiné et collecté des fragments métalliques à Tănăsoaia le 18 janvier. Ils indiquaient un possible véhicule aérien.","summary":["Des spécialistes de la défense ont examiné et collecté des fragments métalliques à Tănăsoaia le 18 janvier. Ils indiquaient un possible véhicule aérien.","L’identification comme drone, l’origine et la date de la chute restent non confirmées ; il s’agit d’une piste de découverte, et non d’une incursion confirmée."]},"N172":{"headline":"Botoșenița Mare · Écrasement d’un objet volant non identifié","description":"Le MApN a signalé un objet volant écrasé dans un champ de maïs près de Botoșenița Mare le 12 septembre, avec un petit incendie et sans victimes.","summary":["Le MApN a signalé un objet volant écrasé dans un champ de maïs près de Botoșenița Mare le 12 septembre, avec un petit incendie et sans victimes.","Des autorités étrangères ont également signalé un transit de drone, et un signalement au 112 a été enregistré ailleurs. Un lien continu avec l’objet récupéré n’est pas établi."]},"N173":{"headline":"À l’est de Mangalia · Découverte d’un drone aérien à la dérive","description":"Le MApN a signalé un drone aérien dérivant à environ 45 milles marins à l’est de Mangalia le 15 novembre. L’origine et l’issue de la mission restent inconnues.","summary":["Un ATLANTIQUE 2 de la Marine nationale française a signalé un drone aérien dérivant à environ 45 milles marins à l’est de Mangalia le 15 novembre, selon le ministère roumain de la Défense.","L’évaluation EOD prévue le 16 novembre a été retardée par le mauvais temps : le MApN a indiqué que les deux embarcations étaient rentrées sans avoir achevé leurs évaluations. Aucune récupération ni aucune neutralisation n’est établie.","Il s’agit d’une découverte en mer, et non de la preuve d’une incursion dans l’espace aérien territorial roumain. L’origine du drone, les dates de son vol et de sa chute, sa charge et tout lien avec les récents impacts sur des navires restent inconnus."]},"N174":{"headline":"À l’est de Chituc · Découverte d’un drone aérien à la dérive","description":"Le MApN a signalé un drone aérien dérivant à environ 53 milles marins à l’est de Chituc le 15 novembre. L’origine et l’issue de la mission restent inconnues.","summary":["Un ATLANTIQUE 2 de la Marine nationale française a signalé un drone aérien dérivant à environ 53 milles marins à l’est de Chituc le 15 novembre, selon le ministère roumain de la Défense.","L’évaluation EOD prévue le 16 novembre a été retardée par le mauvais temps : le MApN a indiqué que les deux embarcations étaient rentrées sans avoir achevé leurs évaluations. Aucune récupération ni aucune neutralisation n’est établie.","Il s’agit d’une découverte en mer, et non de la preuve d’une incursion dans l’espace aérien territorial roumain. L’origine du drone, les dates de son vol et de sa chute, sa charge et tout lien avec les récents impacts sur des navires restent inconnus."]},"N175":{"headline":"Le BETUL 8 chavire au large de la Bulgarie ; un membre d’équipage allègue une attaque de drones maritimes","description":"Les 12 membres d’équipage du BETUL 8 ont été secourus après le chavirement du navire dans la ZEE bulgare le 16 novembre. L’allégation d’une attaque de drones maritimes reste non confirmée.","summary":["Les autorités bulgares ont confirmé que le BETUL 8 avait chaviré dans la zone économique exclusive du pays le 16 novembre. Les 12 membres d’équipage ont été évacués ; le ministère n’a signalé aucune blessure grave.","La BNR a cité un marin secouru alléguant une attaque par deux drones maritimes. Les autorités n’avaient pas confirmé cette cause dans les déclarations examinées. Le sinistre en mer est conservé comme piste, et non comme frappe de drone ou incursion territoriale confirmée.","L’avertissement bulgare NAVWARN 860/26 donne une observation ultérieure à 14:45 UTC le 19 novembre : le navire était chaviré et dérivait sans équipage ni contrôle. Il ne s’agit pas d’une détermination de l’état final ou de la cause."]},"N176":{"headline":"Mer Égée · Sept UAV dans le registre grec pour le 16 novembre","description":"Le registre de novembre du GEETHA recense sept UAV, sept violations de l’espace aérien et dix infractions à la FIR pour le 16 novembre, ce qui diffère du bulletin antérieur.","summary":["Le registre mensuel du GEETHA recense sept UAV, soit l’ensemble des aéronefs signalés pour le 16 novembre, avec sept violations de l’espace aérien national et dix infractions à la FIR d’Athènes. Le bulletin antérieur de Parapolitika donnait six violations et neuf infractions ; l’écart n’est pas expliqué.","Cela reste une seule fiche régionale quotidienne. Les chiffres ne s’additionnent pas et ne constituent pas un décompte de vols vérifié de façon indépendante ; aucun engagement par des armes n’est établi."]},"N177":{"headline":"Alerte nocturne dans le nord de Tulcea ; aucune entrée dans l’espace aérien roumain enregistrée","description":"La Roumanie a émis une alerte dans la nuit du 16 au 17 novembre après des détections radar au-dessus de l’Ukraine. Le MApN n’a signalé aucune entrée non autorisée dans l’espace aérien roumain.","summary":["La Roumanie a émis une alerte de protection civile après des détections radar au-dessus de l’Ukraine. Aucune entrée non autorisée dans l’espace aérien roumain n’a été enregistrée.","Il s’agit d’une seule alerte sélectionnée, et non d’une incursion de drone confirmée."]},"N178":{"headline":"L’équipage du GAS HUSKY secouru après un sinistre en mer ; cause liée à des drones non confirmée","description":"Les 19 membres d’équipage du GAS HUSKY ont été secourus au large de la Bulgarie le 17 novembre. Un avertissement officiel décrit un navire gîtant et à la dérive ; les allégations de drones restent non confirmées.","summary":["Les autorités bulgares ont secouru les 19 membres d’équipage du GAS HUSKY le 17 novembre 2026 après un sinistre maritime en mer. Le transporteur de GPL battant pavillon libérien naviguait de l’Égypte vers la Roumanie. Le lieu se trouve dans la zone économique exclusive de la Bulgarie, et non dans ses eaux territoriales.","Un avertissement de navigation de 10:50 UTC décrivait une gîte de 45 degrés, une passerelle immergée et un navire sans équipage à la dérive. Il n’établissait pas un naufrage complet, malgré les premières informations. AP, citant Maritime.bg, rapporte que le capitaine secouru a déclaré que quatre drones avaient touché le navire ; AP indique aussi qu’il n’y a aucune confirmation officielle de la cause. L’allégation n’est pas vérifiée de façon indépendante, et aucun opérateur ni aucun lien avec le BETUL 8 n’est établi.","Le gestionnaire Stealth Maritime indique que le navire a été touché tôt le 17 novembre dans la ZEE bulgare, mais ne précise pas ce qui l’a touché et dit que son état était inconnu à ce moment-là. Sa déclaration, reproduite par Naftemporiki, confirme que du GPL avait été chargé à Alexandrie à destination de Midia.","Un compte rendu ultérieur de Maritime.bg fait état, selon une source anonyme au sein de la société de gestion, d’une attaque combinée de drones de surface et de drones aériens. Cela reste un récit non confirmé ; la déclaration publique du gestionnaire ne précise pas de mécanisme.","Le 18 novembre, le gouverneur de Varna, Mario Smurkov, a déclaré à bTV qu’il y avait eu quatre impacts, mais que les récits des marins divergeaient et que les types de drones restaient non confirmés. Il a dit que les navires n’avaient pas encore coulé et qu’aucune pollution n’avait été détectée à ce moment-là. Quatre impacts n’établissent pas quatre drones vérifiés de façon indépendante.","Reuters a rapporté le 18 novembre que deux sources anonymes de la sécurité maritime attribuaient la frappe à un système sans équipage. L’agence a repris le récit du gouverneur sur les quatre impacts sans établir le type de drone ni l’opérateur. Reuters a décrit le navire comme ayant coulé, mais n’a fourni aucune heure d’observation plus récente permettant de trancher entre les signalements antérieurs sur son état.","L’avertissement bulgare NAVWARN 858/26 donne une observation ultérieure à 13:30 UTC le 19 novembre : le navire gîtait d’environ 45 degrés, passerelle immergée, et dérivait sans équipage ni contrôle. Il ne s’agit pas d’une détermination de l’état final ou de la cause.","Le NAVWARN 865/26 indique qu’à 12:38 UTC le 21 novembre, le GAS HUSKY était toujours sans équipage et à la dérive, fortement gîté et la passerelle immergée. L’observation n’établit ni un naufrage ni le mécanisme initial.","Les autorités philippines avaient signalé que deux membres d’équipage blessés se rétablissaient après avoir été soignés. The Manila Times, citant le ministère philippin des Travailleurs migrants, a rapporté le départ, à l’aéroport de Varna, des 19 membres d’équipage philippins le 25 novembre. Deux groupes devaient arriver à Manille le 26 novembre, heure des Philippines ; leur arrivée n’avait pas été confirmée de façon indépendante lors de cet examen. Cela n’établit ni l’état final du navire ni la cause initiale."]},"N179":{"headline":"Mer Égée · Six UAV dans le registre grec pour le 17 novembre","description":"Le registre du GEETHA recense six UAV le 17 novembre, contre cinq initialement. Les totaux combinés de l’espace aérien ne peuvent pas être attribués aux seuls drones.","summary":["Le registre mensuel du GEETHA recense six UAV et quatre aéronefs pilotés pour le 17 novembre, avec, tous aéronefs confondus, dix-sept violations de l’espace aérien national et dix infractions à la FIR d’Athènes. Il ne répartit pas ces totaux par type d’aéronef.","Le bulletin antérieur recensait cinq UAV, avec quatre violations de l’espace aérien et sept infractions à la FIR. Ce récit d’origine reste cité, mais le registre diffère et n’apporte aucune explication. Aucune des deux versions n’établit de façon indépendante les trajectoires de vol ; la rencontre avec un chasseur n’est pas un abattage de drone."]},"N180":{"headline":"Farmakonisi · Survol par un UAV turc signalé le 30 juillet","description":"Les autorités grecques ont signalé le survol de Farmakonisi par un UAV le 30 juillet. Une réponse ministérielle de novembre confirme un signalement officiel à l’OTAN, et non une conclusion de l’OTAN.","summary":["Des comptes rendus grecs ont attribué huit violations de l’espace aérien national à deux UAV turcs le 30 juillet 2026, dont un survol de Farmakonisi. Quatre infractions distinctes à la FIR d’Athènes ont été attribuées à ces UAV. Il s’agit d’une seule fiche quotidienne, et non de douze incidents.","Une réponse ministérielle datée du 1er novembre et publiée le 16 novembre reconnaît le survol et indique que la Grèce a adressé un rapport officiel à l’OTAN. Elle précisait qu’une analyse de l’OTAN était alors attendue ; elle ne fournit ni conclusion de l’OTAN ni élément indiquant qu’une réponse est toujours en attente. Les trajectoires de vol exactes et l’intention restent inconnues."]},"N181":{"headline":"Endommagé par un drone, le MARIAM M dérive dans les eaux roumaines et s’échoue à Vadu","description":"Le MARIAM M s’est échoué à Vadu le 16 novembre après avoir dérivé depuis l’Ukraine. Consigné comme suite maritime, avec vidéo ; aucune nouvelle frappe en Roumanie signalée.","summary":["Le MARIAM M s’est échoué sur la côte roumaine de Vadu le 16 novembre 2026. Le cargo abandonné, battant pavillon tanzanien, avait dérivé dans les eaux roumaines après que son ancre eut cédé le 14 novembre.","Les autorités roumaines indiquent qu’une frappe de drone survenue en septembre dans les eaux territoriales ukrainiennes avait laissé le navire au mouillage à cet endroit. Cette fiche couvre son arrivée ultérieure et son échouement en Roumanie, classés en Alerte / autre. Elle ne compte pas de nouvelle frappe de drone et ne transpose pas les victimes de l’attaque de septembre.","Le 19 novembre, des remorqueurs ont dégagé le navire de son banc de sable initial. ProTV a ensuite rapporté qu’il s’était déplacé d’environ 100 mètres avant de s’échouer sur un autre banc de sable, après quoi l’équipage l’a ancré et a suspendu le renflouement à la tombée de la nuit. La page comprend des images antérieures de l’intervention de l’ARSVOM et un lien vers une vidéo prise depuis le rivage.","Lors d’une tentative distincte le 22 novembre, Știrile ProTV a rapporté que trois remorqueurs avaient orienté le MARIAM M vers le large, mais qu’il s’était de nouveau partiellement échoué et que les travaux avaient été suspendus à la tombée de la nuit. Le poste d’amarrage final et les conséquences environnementales restent non vérifiés."]},"N182":{"headline":"Mer Égée · Un UAV dans le compte rendu quotidien grec du 18 novembre","description":"Des chiffres grecs attribuent une violation de l’espace aérien national et une infraction distincte à la FIR à un UAV le 18 novembre. Une seule fiche régionale, aucun engagement signalé.","summary":["Des chiffres du GEETHA reproduits par OnAlert et NewsIT attribuent une violation de l’espace aérien national et une infraction distincte à la FIR d’Athènes à un UAV turc le 18 novembre, dans le nord-est et le centre de la mer Égée.","Le CN-235 piloté figurant dans le même tableau est exclu des décomptes d’UAV. Une interception de routine est signalée, sans engagement. Ces médias reproduisent le même récit des autorités, et non des trajectoires indépendantes ; l’itinéraire précis, le modèle et l’intention restent inconnus."]},"N183":{"headline":"Mer Égée · Activité d’UAV turcs signalée le 14 novembre","description":"Les autorités grecques recensent 2 UAV turcs le 14 novembre, avec des chiffres distincts pour l’espace aérien national et la FIR.","summary":["Le registre de novembre du GEETHA recense 2 UAV et aucun aéronef piloté pour le 14 novembre dans le sud-est de la mer Égée.","Le registre fait état d’une violation de l’espace aérien national et de 2 infractions distinctes à la FIR d’Athènes. Il s’agit de chiffres des autorités grecques, et non de trajectoires vérifiées de façon indépendante, de décomptes d’événements uniques ou d’attaques. Aucun engagement n’a été recensé."]},"N184":{"headline":"Mer Égée · Activité d’UAV turcs signalée le 15 novembre","description":"Les autorités grecques recensent 3 UAV turcs le 15 novembre, avec des chiffres distincts pour l’espace aérien national et la FIR.","summary":["Le registre de novembre du GEETHA recense 3 UAV et aucun aéronef piloté pour le 15 novembre dans le centre et le sud-est de la mer Égée.","Le registre fait état de 4 violations de l’espace aérien national et de 4 infractions distinctes à la FIR d’Athènes. Il s’agit de chiffres des autorités grecques, et non de trajectoires vérifiées de façon indépendante, de décomptes d’événements uniques ou d’attaques. Aucun engagement n’a été recensé."]},"N186":{"headline":"Mer Égée · Activité d’UAV turcs signalée le 20 novembre","description":"Les autorités grecques ont signalé trois UAV turcs et trois violations de l’espace aérien national le 20 novembre. Les chiffres distincts relatifs à la FIR ne sont pas des décomptes d’incidents.","summary":["OnAlert reproduit les chiffres de l’état-major général grec pour le sud-est de la mer Égée le 20 novembre : trois UAV turcs, trois violations de l’espace aérien national par des UAV et trois infractions distinctes à la FIR d’Athènes par des UAV. Un ATR-72 piloté est à l’origine de deux autres infractions à la FIR.","Il s’agit de chiffres quotidiens attribués aux autorités grecques, et non de trajectoires de vol indépendantes ni de trois incidents distincts cartographiés. La ligne du registre mensuel primaire n’a pas été vérifiée de façon indépendante."]},"N188":{"headline":"L’Ukraine reconnaît la frappe contre le SPARTA II ; la Finlande a dirigé le sauvetage ultérieur","description":"L’Ukraine a reconnu la frappe de drone du 21 novembre dans le golfe de Finlande. Les récits divergent sur le lieu où le navire a été touché. La Finlande a ensuite dirigé le sauvetage.","summary":["Les Forces de défense finlandaises ont signalé une frappe de drone le 21 novembre dans l’est du golfe de Finlande. L’armée l’a située dans les eaux internationales, tandis que le commandant des garde-frontières, Ilja Iljin, a déclaré qu’elle avait eu lieu dans les eaux territoriales russes. Le navire en feu a ensuite dérivé dans les eaux territoriales finlandaises. Cela n’établit pas qu’un drone ait pénétré en Finlande.","Les garde-côtes finlandais ont confirmé que l’équipage avait été évacué vers le KAPITAN SAKHAROV. Lors de leur point de presse du 22 novembre, les garde-frontières finlandais ont fait état d’un membre d’équipage blessé. La lutte contre l’incendie s’est poursuivie après l’extinction des flammes visibles ; aucun hydrocarbure n’avait été observé en mer à la date de ce point de presse. Il ne s’agissait pas d’une évaluation définitive.","Le directeur de la communication des Forces de défense finlandaises, Aki-Mauri Huhtinen, a estimé que l’Ukraine était probablement responsable. L’opérateur précis, l’intention et la cargaison n’ont pas été établis de façon indépendante.","Le ministère estonien des Affaires étrangères indique que le navire endommagé a dérivé de la zone économique exclusive de l’Estonie vers la zone économique exclusive de la Finlande, puis dans les eaux territoriales finlandaises. L’Estonie a apporté son aide à la demande de la Finlande ; les garde-frontières finlandais ont confirmé la participation estonienne à la lutte contre l’incendie et au refroidissement. Les récits du sauvetage n’établissent ni le lieu de la frappe ni l’itinéraire d’un drone.","Le 22 novembre, le convoi de remorquage a quitté la zone économique exclusive finlandaise et la zone d’intervention environnementale ; la Finlande a mis fin à sa mission et les restrictions temporaires ont été levées. Helsinki a mis fin séparément à son dispositif de veille préventive contre la pollution par hydrocarbures. Svenska Yle a rapporté que la Russie avait pris en charge la responsabilité du sauvetage maritime.","Le 23 novembre, le gouverneur de la région de Leningrad, Alexander Drozdenko, a déclaré que l’équipage avait débarqué à Saint-Pétersbourg à 20:00, heure de Moscou. Il a dit que le navire avait atteint le même port à flot avec sa cargaison, sans donner l’heure d’arrivée du navire. Son affirmation selon laquelle il n’y avait aucun blessé contredit le compte rendu des garde-frontières finlandais. L’issue finale de l’incendie et de la pollution ainsi que l’identité de la cargaison restent non vérifiées.","L’Autorité nationale d’exécution finlandaise a déclaré avoir évalué que le navire appartenait à une société visée par des sanctions de l’UE et a imposé une restriction provisoire de transfert après son entrée dans les eaux territoriales finlandaises le 21 novembre. La restriction comportait des exceptions liées au sauvetage, à la sécurité et à l’environnement. La décision juridique finale n’a pas été établie.","Dans un entretien accordé à Bloomberg et publié le 24 novembre, le président Volodymyr Zelensky a reconnu que l’Ukraine avait mené la frappe et a affirmé qu’elle avait eu lieu dans les eaux territoriales russes. ERR a situé l’impact dans la ZEE estonienne ; un responsable estonien du sauvetage a placé le navire dans cette ZEE au moment de l’incendie et de l’explosion. L’armée finlandaise a qualifié la zone de la frappe d’eaux internationales. Le lieu exact de la frappe et l’affirmation de Zelensky concernant des armes à bord n’ont pas été vérifiés de façon indépendante. Le sauvetage ultérieur mené par la Finlande est un fait documenté distinct."]},"N189":{"headline":"L’Estonie a émis puis levé une alerte à la menace aérienne dans deux comtés du nord-est","description":"L’Estonie a averti les habitants de Lääne-Viru et d’Ida-Viru d’une possible menace aérienne le 21 novembre. L’alerte n’établit pas une incursion de drone.","summary":["Les Forces de défense estoniennes ont émis une alerte de possible menace aérienne pour Lääne-Viru et Ida-Viru le 21 novembre à 04:42, heure locale. Le message conseillait de se mettre à l’abri en cas d’observation d’un drone. La fin d’alerte a suivi à 06:49, heure locale. Il s’agit d’un seul épisode d’alerte, et non d’une incursion vérifiée."]},"N190":{"headline":"Les habitants de Tulcea alertés dans la nuit ; la Roumanie n’a signalé aucune entrée dans son espace aérien","description":"Les autorités ont émis une alerte RO-Alert à 00:46, heure locale, le 22 novembre et fait décoller deux F-16. Le ministère de la Défense n’a signalé aucune entrée dans l’espace aérien roumain.","summary":["Une alerte nocturne a été envoyée au nord et à l’est du département de Tulcea à 00:46, heure locale, le 22 novembre. Le ministère roumain de la Défense a signalé une cible aérienne en dehors de l’espace aérien national et indiqué que deux F-16 avaient décollé. Il n’a signalé aucune entrée dans l’espace aérien national. Le ministère a indiqué que l’alerte aérienne avait pris fin à 02:14, tandis que l’ISU Delta Tulcea a donné 02:16 et n’a signalé ni demande ni problème. Il s’agit de récits d’un seul épisode d’alerte."]},"N191":{"headline":"Mer Égée · Activité d’UAV turcs signalée le 22 novembre","description":"Des chiffres des autorités grecques font état de sept UAV turcs, de sept violations de l’espace aérien national et de sept infractions distinctes à la FIR d’Athènes.","summary":["Des médias grecs citant l’état-major général de la défense nationale hellénique ont fait état de sept UAV turcs, de sept violations de l’espace aérien national grec et de sept infractions à la FIR d’Athènes dans le nord-est, le centre et le sud-est de la mer Égée le 22 novembre. Ils ont signalé une identification et une interception de routine.","Les trois chiffres sont des mesures distinctes au sein d’un même compte rendu quotidien. Ils n’établissent ni des trajectoires de vol indépendantes, ni un abattage, ni une attaque. La ligne d’origine du registre quotidien n’a pas pu être vérifiée."]},"N192":{"headline":"L’alerte RO-Alert de l’après-midi dans le nord de Tulcea a pris fin sans entrée signalée dans l’espace aérien","description":"Le nord du département de Tulcea a reçu une alerte distincte l’après-midi, à 15:06, heure locale, le 22 novembre. Aucune entrée dans l’espace aérien roumain n’a été signalée.","summary":["Le ministère roumain de la Défense a signalé une cible aérienne au nord de Vâlcove, en Ukraine, et une alerte RO-Alert pour le nord du département de Tulcea de 15:06 à 15:42, heure locale, le 22 novembre. Aucune entrée dans l’espace aérien roumain n’a été signalée.","Le ministère a indiqué que des avions de chasse et des hélicoptères espagnols avaient décollé en réponse. Il n’a pas signalé d’interception.","Il s’agit d’une alerte de protection civile, et non d’une incursion ou d’une attaque de drone confirmée. Le type de cible et l’opérateur n’ont pas été établis."]},"N193":{"headline":"L’alerte RO-Alert du soir dans le nord de Tulcea a pris fin sans entrée signalée dans l’espace aérien","description":"Le nord du département de Tulcea a reçu une alerte distincte le soir, à 20:01, heure locale, le 22 novembre. Aucune entrée dans l’espace aérien roumain n’a été signalée.","summary":["Le ministère roumain de la Défense a signalé des cibles aériennes à l’est de l’île des Serpents et une alerte RO-Alert pour le nord du département de Tulcea de 20:01 à 21:15, heure locale, le 22 novembre. Aucune entrée dans l’espace aérien roumain n’a été signalée.","Il s’agit d’une alerte de protection civile, et non d’une incursion ou d’une attaque de drone confirmée. Le type de cible et l’opérateur n’ont pas été établis."]},"N194":{"headline":"Un drone attribué à la Russie entre en Pologne près de Dorohusk et repart vers l’Ukraine","description":"La Pologne signale le franchissement d’un drone près de Dorohusk le 23 novembre. Un abattage a été autorisé, mais aucune arme n’a été utilisée avant son retour en Ukraine.","summary":["Le Commandement opérationnel polonais a confirmé qu’un drone attribué à la Russie était entré dans l’espace aérien polonais le 23 novembre, lors de frappes sur l’ouest de l’Ukraine. L’article de suivi de Rzeczpospolita, citant le commandement et son porte-parole Jacek Goryszewski, situe l’entrée près de Dorohusk à 22:50, heure locale, avec une incursion d’environ 20 km d’une durée de 8 à 9 minutes avant que le drone ne fasse demi-tour vers l’Ukraine.","Un abattage a été autorisé, mais aucune arme n’a été utilisée. Radio Lublin et UNITED24 rapportent que les commandants ont retenu le tir après le virage vers l’est, en tenant compte de la sécurité des civils. Goryszewski a déclaré que les systèmes sol disposaient de l’autorisation ; les avions polonais n’opéraient pas près de la frontière en raison de la météo. Aucune victime, aucun impact ni aucune récupération de débris n’ont été signalés.","Le porte-parole a estimé, d’après la vitesse de vol, qu’il s’agissait d’une propulsion à réaction, mais n’a confirmé ni la présence de caméras ni un rôle de reconnaissance. Le modèle, la charge et la cible visée restent inconnus. Le marqueur de Dorohusk est une référence approximative, et non une coordonnée de franchissement vérifiée. Les alertes publiques font partie de cet unique événement, distinct de l’incident de missile du 20 novembre.","Le Centre gouvernemental de sécurité a enregistré la mise à jour relative à la mise à l’abri à 22:56 CET et la fin d’alerte à 23:54 CET. Il s’agit d’heures d’alerte, et non d’heures de vol."]},"N195":{"headline":"Tausiūnai–Aukštalaukis : des garde-frontières récupèrent un drone chargé de cigarettes venu de Biélorussie","description":"La Lituanie signale une incursion de drone distincte près de Tausiūnai–Aukštalaukis le 27 septembre, avec la récupération de 250 paquets de cigarettes. Opérateur inconnu.","summary":["Le VSAT a signalé un drone transportant des cigarettes venu de Biélorussie tard dans la soirée du dimanche 27 septembre, heure locale. Le drone a été détecté près de Tausiūnai et récupéré près d’Aukštalaukis après une descente forcée. Il était gravement endommagé.","Les garde-frontières ont récupéré 250 paquets de cigarettes et ouvert une procédure administrative. L’opérateur n’a pas été identifié. Il s’agit d’une affaire de contrebande transfrontalière, et non d’une attaque étatique établie."]},"N196":{"headline":"Eišiškės : des garde-frontières récupèrent un drone chargé de cigarettes venu de Biélorussie","description":"La Lituanie signale une incursion de drone distincte près d’Eišiškės le 27 septembre, avec la récupération de 100 paquets de cigarettes. Opérateur inconnu.","summary":["Le VSAT a signalé un drone transportant des cigarettes venu de Biélorussie avant minuit, heure locale, le 27 septembre. Une autre patrouille a intercepté le drone près d’Eišiškės plusieurs heures après le premier incident. Le drone est tombé dans le secteur de la ville et a été récupéré.","Les garde-frontières ont récupéré 100 paquets de cigarettes et ouvert une procédure administrative. L’opérateur n’a pas été identifié. Il s’agit d’une affaire de contrebande transfrontalière, et non d’une attaque étatique établie."]},"N197":{"headline":"Mer Égée : 6 violations de l’espace aérien signalées le 18 octobre","description":"Veteranos, citant des comptes rendus militaires grecs, a décrit 5 UAV turcs dans le centre et le sud-est de la mer Égée le 18 octobre 2026, avec 6 violations signalées de l’espace aérien national et, séparément, 10 infractions aux règles de circulation de la FIR d’Athènes.","summary":["Veteranos, citant des comptes rendus militaires grecs, a décrit 5 UAV turcs dans le centre et le sud-est de la mer Égée le 18 octobre 2026, avec 6 violations signalées de l’espace aérien national et, séparément, 10 infractions aux règles de circulation de la FIR d’Athènes.","Le récit fait état d’une identification et d’une interception de routine, et non d’un engagement par des armes ni d’un abattage.","Il s’agit d’une seule fiche quotidienne attribuée, et non d’un décompte d’incursions confirmées distinctes. L’entrée d’origine du registre militaire grec n’a pas été obtenue, et les trajectoires, les lieux exacts, l’intention et les détails sur l’opérateur ne sont pas vérifiés. Le différend gréco-turc sur l’espace aérien reste pertinent."]},"N198":{"headline":"Mer Égée : 3 violations de l’espace aérien signalées le 21 novembre","description":"Veteranos, citant des comptes rendus militaires grecs, a décrit un UAV turc dans le centre de la mer Égée le 21 novembre 2026, avec 3 violations signalées de l’espace aérien national et, séparément, 1 infraction aux règles de circulation de la FIR d’Athènes.","summary":["Veteranos, citant des comptes rendus militaires grecs, a décrit un UAV turc dans le centre de la mer Égée le 21 novembre 2026, avec 3 violations signalées de l’espace aérien national et, séparément, 1 infraction aux règles de circulation de la FIR d’Athènes.","Le récit fait état d’une identification et d’une interception de routine, et non d’un engagement par des armes ni d’un abattage.","Il s’agit d’une seule fiche quotidienne attribuée, et non d’un décompte d’incursions confirmées distinctes. L’entrée d’origine du registre militaire grec n’a pas été obtenue, et les trajectoires, les lieux exacts, l’intention et les détails sur l’opérateur ne sont pas vérifiés. Le différend gréco-turc sur l’espace aérien reste pertinent."]},"N199":{"headline":"L’alerte RO-Alert du matin dans le nord de Tulcea levée sans entrée signalée dans l’espace aérien roumain","description":"La Roumanie a alerté le nord du département de Tulcea le matin du 24 novembre après la détection d’une cible dans l’espace aérien ukrainien. Aucune entrée dans l’espace aérien roumain n’a été signalée.","summary":["La Roumanie a alerté le nord du département de Tulcea le matin du 24 novembre après la détection d’une cible dans l’espace aérien ukrainien. Aucune entrée dans l’espace aérien roumain n’a été signalée.","Le ministère de la Défense a fait état d’une alerte à 11:11 EET, d’une surveillance par des avions espagnols et d’une fin d’alerte à 11:51 EET.","Le compte rendu des services d’urgence locaux citait une heure de réception téléphonique de 10:11. Cet écart n’indique pas une seconde alerte matinale.","Il s’agit d’une alerte de précaution, et non d’une incursion confirmée en Roumanie."]},"N200":{"headline":"L’alerte RO-Alert de l’après-midi dans le nord de Tulcea levée sans entrée signalée dans l’espace aérien roumain","description":"La Roumanie a de nouveau alerté le nord du département de Tulcea le 24 novembre après la détection d’une cible près du bras de Chilia, dans l’espace aérien ukrainien. Aucune entrée dans l’espace aérien roumain n’a été signalée.","summary":["La Roumanie a de nouveau alerté le nord du département de Tulcea le 24 novembre après la détection d’une cible près du bras de Chilia, dans l’espace aérien ukrainien. Aucune entrée dans l’espace aérien roumain n’a été signalée.","Le ministère de la Défense a fait état d’une alerte à 14:37 EET, d’une surveillance par des aéronefs et d’une fin d’alerte à 15:40 pour le nord du département de Tulcea. ProTV rapporte que la phase d’alerte aérienne à Galați a commencé à 14:52 EET après le signalement d’un drone non identifié se dirigeant vers le département. La fin d’alerte de l’IGSU local a été signalée à 15:46 EET.","L’identité de la cible, l’opérateur et la cible visée sont inconnus. Il n’est pas établi que les alertes de Tulcea et de Galați concernaient la même cible. L’alerte du matin reste distincte.","Il s’agit d’une alerte de précaution, et non d’une incursion confirmée en Roumanie."]},"N201":{"headline":"Žaltūnai–Girdijauskai : la Lituanie signale une contrebande transfrontalière par drone","description":"Les garde-frontières lituaniens ont récupéré 2 appareils et 2 000 paquets de cigarettes après une opération nocturne en juillet près de Žaltūnai–Girdijauskai.","summary":["9–10 juillet 2026 (dans la nuit). Les garde-frontières indiquent avoir détecté des drones venus de Biélorussie pendant la nuit. Les agents ont récupéré deux drones cargo près de Žaltūnai et de Girdijauskai après la reprise des recherches à la lumière du jour.","Les agents ont récupéré 2 000 paquets de cigarettes avec timbres fiscaux biélorusses sur 2 appareils. Une enquête pénale a été ouverte.","L’opérateur ainsi que le point de franchissement et la trajectoire exacts sont inconnus. L’opération est consignée comme contrebande transfrontalière, et non comme une attaque militaire."]},"N202":{"headline":"Šiulgiai–Šumskas : la Lituanie signale une contrebande transfrontalière par drone","description":"Les garde-frontières lituaniens ont récupéré un appareil et 340 paquets de cigarettes après une opération nocturne en juillet près de Šiulgiai–Šumskas.","summary":["17–18 juillet 2026 (dans la nuit). Les garde-frontières ont signalé qu’un drone cargo était entré en Lituanie. Les agents ont entendu le drone près de Šiulgiai, sans le voir. Après une intervention, il est tombé, et l’appareil endommagé a été récupéré près de Šumskas à la lumière du jour.","Les agents ont récupéré 340 paquets de cigarettes avec timbres fiscaux biélorusses sur un appareil. Une procédure administrative a été ouverte.","L’opérateur ainsi que le point de franchissement et la trajectoire exacts sont inconnus. L’opération est consignée comme contrebande transfrontalière, et non comme une attaque militaire."]},"N203":{"headline":"Norviliškės–Daulėnai : la Lituanie signale une contrebande transfrontalière par drone","description":"Les garde-frontières lituaniens ont récupéré 3 appareils et 3 000 paquets de cigarettes après une opération nocturne en juillet près de Norviliškės–Daulėnai.","summary":["29–30 juillet 2026 (dans la nuit). Les garde-frontières ont signalé des drones cargo entrant en Lituanie depuis la Biélorussie. Deux appareils ont été récupérés près de Norviliškės et un près de Daulėnai au cours d’une seule opération nocturne, la dernière récupération ayant eu lieu à la lumière du jour.","Les agents ont récupéré 3 000 paquets de cigarettes avec timbres fiscaux biélorusses sur 3 appareils. Une enquête pénale a été ouverte.","L’opérateur ainsi que le point de franchissement et la trajectoire exacts sont inconnus. L’opération est consignée comme contrebande transfrontalière, et non comme une attaque militaire."]},"N204":{"headline":"Kiemėnai : des garde-frontières lituaniens récupèrent un drone de contrebande","description":"Les garde-frontières lituaniens ont récupéré un drone et 750 paquets de cigarettes après une opération nocturne près de Kiemėnai.","summary":["16–17 avril 2026. Le VSAT a indiqué avoir détecté le drone entrant en Lituanie depuis la Biélorussie. Le drone est tombé après l’intervention des garde-frontières et a été récupéré près de Kiemėnai.","Les agents ont récupéré 750 paquets de cigarettes avec timbres fiscaux biélorusses et ouvert une procédure administrative.","Aucun opérateur, aucun parrainage étatique ni aucune trajectoire de vol exacte n’a été établi. Il s’agit d’une fiche de contrebande frontalière, et non d’une attaque militaire."]},"N205":{"headline":"Prūdelis : des garde-frontières lituaniens récupèrent un drone de contrebande","description":"Les garde-frontières lituaniens ont récupéré un drone et 1 000 paquets de cigarettes après une opération nocturne près de Prūdelis.","summary":["8–9 juillet 2026. Le VSAT a signalé le drone volant vers l’intérieur du pays depuis la frontière biélorusse ; il n’a publié ni le point de franchissement exact ni la trajectoire. Le drone est tombé après l’intervention des garde-frontières et a été récupéré près de Prūdelis.","Les agents ont récupéré 1 000 paquets de cigarettes avec timbres fiscaux biélorusses et ouvert une procédure administrative.","Aucun opérateur, aucun parrainage étatique ni aucune trajectoire de vol exacte n’a été établi. Il s’agit d’une fiche de contrebande frontalière, et non d’une attaque militaire."]},"N206":{"headline":"Mer Égée · Activité d’UAV turcs signalée le 25 novembre","description":"Des chiffres des autorités grecques recensent trois UAV turcs, quatre violations de l’espace aérien national et trois infractions distinctes à la FIR d’Athènes.","summary":["L’état-major général de la défense nationale hellénique (GEETHA), cité par OnAlert et Veteranos, a recensé trois UAV turcs, quatre violations signalées de l’espace aérien national grec et trois infractions distinctes aux règles de circulation de la FIR d’Athènes le 25 novembre. Le compte rendu couvrait le nord-est, le centre et le sud-est de la mer Égée. Une identification et une interception de routine ont été signalées ; aucun engagement n’a été recensé.","Les chiffres sont des mesures distinctes au sein d’un même bulletin militaire quotidien, et non des trajectoires de vol individuelles vérifiées ni des décomptes d’attaques. Les deux comptes rendus citent le même bulletin ; le tableau mensuel officiel n’était pas directement accessible lors de l’examen."]},"N207":{"headline":"Kuodžiai : la Lituanie signale quatre drones de contrebande lors d’une même opération","description":"Les garde-frontières lituaniens ont récupéré quatre drones et 4 000 paquets de cigarettes après une opération le 30 juillet près de Kuodžiai.","summary":["30 juillet 2026, soir. Le Service national lituanien des garde-frontières (VSAT) a indiqué que quatre drones cargo étaient entrés depuis la Biélorussie et qu’ils avaient été ramenés au sol et récupérés lors d’une même opération près de Kuodžiai, dans le district de Lazdijai.","La cargaison récupérée totalisait 4 000 paquets de cigarettes avec timbres fiscaux biélorusses. Le VSAT a indiqué qu’une enquête pénale avait été ouverte. Il s’agit d’une seule opération documentée, et non de quatre fiches d’incident distinctes.","Aucune trajectoire de vol exacte, aucune identité d’opérateur ni aucun parrainage étatique n’a été établi. Il s’agit d’une affaire de contrebande criminelle, et non d’une attaque militaire."]},"N208":{"headline":"Des garde-frontières lituaniens récupèrent un drone de contrebande et 500 paquets de cigarettes près de Jurgionys","description":"Les garde-frontières lituaniens ont signalé l’entrée d’un drone venu de Biélorussie près de Jurgionys avant minuit le 24 novembre et ont récupéré 500 paquets de cigarettes.","summary":["Les garde-frontières lituaniens ont signalé l’entrée d’un drone venu de Biélorussie près de Jurgionys avant minuit le 24 novembre et ont récupéré 500 paquets de cigarettes.","Le communiqué du 26 novembre indique que l’appareil a été endommagé à l’impact. Il s’agissait du 74e appareil intercepté dans cette catégorie de contrôle en 2026 à la date du communiqué, et non de la 74e fiche de ce registre."]},"N209":{"headline":"Des garde-frontières lituaniens signalent l’entrée d’un drone près de Purvėnai et sa récupération près de Geismantai","description":"Le service lituanien des garde-frontières a signalé l’entrée d’un drone le 24 janvier et l’a récupéré près de Geismantai avec 1 000 paquets de cigarettes.","summary":["Le service lituanien des garde-frontières a signalé l’entrée d’un drone le 24 janvier et l’a récupéré près de Geismantai avec 1 000 paquets de cigarettes.","Cet incident est distinct de l’incident de Purvėnai du 27 janvier, signalé séparément."]},"N210":{"headline":"Le parquet lituanien documente une opération de contrebande par drones en mai dans le district de Švenčionys","description":"Le parquet lituanien a déclaré que des drones avaient fait passer 35 500 paquets de cigarettes à travers la frontière depuis la Biélorussie dans la nuit du 27 mai. Le nombre d’appareils est inconnu.","summary":["Le parquet lituanien a déclaré que des drones avaient fait passer 35 500 paquets de cigarettes à travers la frontière depuis la Biélorussie dans la nuit du 27 mai. Le nombre d’appareils est inconnu.","Les garde-frontières ont récupéré des cigarettes après leur déplacement au sol. Aucune interception ni récupération de drone n’a été signalée. L’ordonnance du tribunal n’était pas définitive au moment de l’annonce du 20 novembre."]},"N211":{"headline":"Des garde-frontières lituaniens disent avoir fait tomber quatre drones de contrebande près de Jaskonys","description":"Les garde-frontières lituaniens ont indiqué avoir fait tomber quatre drones entrants lors d’une même opération près de Jaskonys, récupérant les appareils et 4 998 paquets de cigarettes.","summary":["Les garde-frontières lituaniens ont indiqué avoir fait tomber quatre drones entrants lors d’une même opération près de Jaskonys, récupérant les appareils et 4 998 paquets de cigarettes.","Le communiqué du 7 juillet évoque la nuit de vendredi, les récupérations s’étant poursuivies jusqu’au jour. Il ne précise pas de quel côté de minuit se situent les faits. Il ne s’agit pas de l’opération ultérieure de Kuodžiai."]},"N212":{"headline":"L’alerte du soir dans le nord de Tulcea prend fin sans entrée signalée dans l’espace aérien roumain","description":"Le ministère roumain de la Défense a signalé la détection radar d’une cible aérienne non identifiée à l’est de Vâlcove, en Ukraine. Le nord du département de Tulcea a reçu une alerte. Aucune entrée dans l’espace aérien roumain n’a été signalée.","summary":["Le ministère roumain de la Défense a signalé la détection radar d’une cible aérienne non identifiée à l’est de Vâlcove, en Ukraine. Le nord du département de Tulcea a reçu une alerte. Aucune entrée dans l’espace aérien roumain n’a été signalée.","L’alerte RO-Alert de 18:52 EET a pris fin à 19:11. Des avions espagnols déjà en vol d’entraînement ont été réorientés pour assurer la surveillance.","Il s’agit d’une alerte civile, et non d’une incursion de drone confirmée."]},"N213":{"headline":"Le compte rendu quotidien grec recense six UAV turcs en mer Égée le 26 novembre","description":"Veteranos a fait état de six UAV turcs, de neuf violations signalées de l’espace aérien national grec et de neuf infractions distinctes aux règles de circulation de la FIR d’Athènes.","summary":["Veteranos a fait état de six UAV turcs, de neuf violations signalées de l’espace aérien national grec et de neuf infractions distinctes aux règles de circulation de la FIR d’Athènes.","Le tableau couvre le nord-est, le centre et le sud-est de la mer Égée et ne recense ni aéronef armé ni engagement.","Les décomptes sont des mesures distinctes issues d’un même compte rendu quotidien publié, et non des trajectoires de vol vérifiées ni des décomptes d’attaques."]},"N214":{"headline":"L’armée lettone confirme une brève entrée de drone près de sa frontière orientale","description":"Les forces armées nationales lettones ont déclaré qu’un aéronef sans pilote s’était brièvement trouvé sur le territoire letton dans la nuit du 27 novembre. Aucune seconde entrée n’a été confirmée à Balvi.","summary":["Les forces armées nationales lettones ont déclaré qu’un aéronef sans pilote s’était brièvement trouvé sur le territoire letton dans la nuit du 27 novembre. Aucune seconde entrée n’a été confirmée à Balvi.","L’alerte orange de Ludza a été en vigueur de 02:30 à 02:55 EET. L’alerte jaune de Balvi a commencé à 02:55 et a pris fin vers 03:30. Des chasseurs de l’OTAN ont été activés, et un drone intercepteur letton a été déployé puis est revenu.","L’armée n’a identifié ni l’opérateur du drone, ni son origine, ni sa cible, et n’a signalé aucun abattage."]},"N215":{"headline":"Le sud de l’Estonie émet une alerte à la menace aérienne","description":"L’Estonie a alerté six comtés du sud le 27 novembre. Aucune intrusion de drone n’a été confirmée.","summary":["L’alerte a débuté à 06:41 EET. Elle a été levée à 07:22 dans les applications et à 07:23 par SMS."]},"N216":{"headline":"Le nord de Tulcea reçoit une alerte RO-Alert dans la matinée","description":"Une cible radar non identifiée a déclenché une alerte dans le nord de Tulcea le 27 novembre. Aucune intrusion n’a été confirmée.","summary":["L’alerte a duré de 10:32 à 11:10 EET. La Roumanie a signalé une cible radar au nord-est de Vâlcove, en Ukraine."]},"N217":{"headline":"Un drone de contrebande récupéré près de Sabaliūnai","description":"Les gardes-frontières lituaniens ont signalé un drone venu de Biélorussie près de Sabaliūnai et ont saisi un chargement de cigarettes.","summary":["Les gardes-frontières ont récupéré le drone et saisi 1 000 paquets de cigarettes qui lui étaient liés."]},"N218":{"headline":"Un drone de contrebande récupéré près de la forêt de Švedų","description":"Les gardes-frontières lituaniens ont signalé un drone venu de Biélorussie près de la forêt de Švedų et ont saisi un chargement de cigarettes.","summary":["Les gardes-frontières ont récupéré le drone et saisi 240 paquets de cigarettes qui lui étaient liés."]},"N219":{"headline":"Mer Égée : activité de drones signalée le 25 août","description":"Un rapport quotidien grec a recensé 4 drones le 25 août.","summary":["Le rapport liste 3 violations de l’espace aérien national et, séparément, 8 infractions aux règles de la FIR d’Athènes imputées à des drones."]},"N220":{"headline":"Mer Égée : activité de drones signalée le 26 août","description":"Un rapport quotidien grec a recensé 5 drones le 26 août.","summary":["Le rapport liste 6 violations de l’espace aérien national et, séparément, 7 infractions aux règles de la FIR d’Athènes imputées à des drones."]},"N221":{"headline":"Mer Égée : activité de drones signalée le 29 août","description":"Un rapport quotidien grec a recensé 2 drones le 29 août.","summary":["Le rapport liste 2 violations de l’espace aérien national et, séparément, 2 infractions aux règles de la FIR d’Athènes imputées à des drones."]},"N222":{"headline":"Mer Égée : activité de drones signalée le 27 novembre","description":"Un rapport quotidien grec a recensé 7 drones le 27 novembre.","summary":["Le rapport liste 5 violations de l’espace aérien national et, séparément, 10 infractions aux règles de la FIR d’Athènes imputées à des drones."]}};
